var e={"11-14":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`,`c1.identity`,`c1.great_vespers`,`c1.matins`,`c1.liturgy`],commemorations:[{kind:`saint`,title:{text:`COMMEMORATION OF THE HOLY AND GLORIOUS APOSTLE PHILIP`,tier:1,src:{file:`11-14.pdf`,locus:`p1 title`},sourceLabel:`THE 14th DAY OF THE MONTH OF NOVEMBER`},rank:`polyeleos`,fekula_section:`2E`,oca_primary:!0,source_file:`11-14.pdf`,note:`Rank by the encoding_rule_v2.md 1.1 waterfall (ODS vol. III has no 11-14 entry): no Little Vespers is printed; Matins appoints the Polyeleos with a magnification. PROVISIONAL, see open question Q-0001: the page also prints 8 stichera, a Litiya, and the troparion Twice with "Virgin Theotokos, rejoice" Once at the blessing of the Loaves, which is the outline Fekula gives for a Vigil (2F), not a Polyeleos (2E). OCA lists Apostle Philip first on 14 November.`,troparion:{text:`O holy apostle Philip, * entreat the Merciful God * that He grant remission of sins ** unto our souls.`,tier:2,src:{file:`11-14.pdf`,locus:`p4 Troparion of the holy apostle`},sourceLabel:`At the blessing of the Loaves, the Troparion, in Tone III`,tone:3,verified_sites:[{locus:`p4 blessing of the Loaves`,tone:3,repeat:2},{locus:`p5 God is the Lord`,tone:3,repeat:2}]},kontakion:{text:`Thy disciple and friend, the emulator of Thy suffering, * the divinely eloquent Philip, proclaimed Thee to the world as God; * by his prayers and through the Theotokos, ** keep Thy Church and every city from most iniquitous enemies, O greatly Merciful One.`,tier:2,src:{file:`11-14.pdf`,locus:`p10 Kontakion of the holy apostle`},verified_sites:[{locus:`p10 after Ode VI`,tone:8},{locus:`p13 AT LITURGY`,tone:8}],sourceLabel:`Kontakion of the holy apostle, in Tone VIII`,spec_mel:`As the first-born,`,tone:8},ikos:{text:`O Lord, Who created the nature of water, grant me a stream of discourse; and strengthen my heart, O compassionate One, Who established the earth by Thy word; and enlighten my mind, O Thou that art covered with light as with a garment, that I may give utterance and chant fitting things and may praise Thy favorite as is meet, O greatly Merciful One.`,tier:1,src:{file:`11-14.pdf`,locus:`p10 Ikos`},sourceLabel:`Ikos`,label_inline:!0},vespers:{order:[`rubric`,`lic_rubric`,`lic`,`lic_glory`,`dogmatikon`,`entrance_rubric`,`readings`,`litiya`,`aposticha_rubric`,`aposticha`,`aposticha_glory`,`aposticha_closer`,`troparion_rubric`,`troparion`,`virgin_theotokos_rubric`,`troparion_alternate_rubric`,`troparion_alternate`],rubric:{text:`We chant “Blessed is the man ...,” the first Antiphon.`,tier:1,src:{file:`11-14.pdf`,locus:`p1 Vespers rubric`}},lic_rubric:{text:`On “Lord, I have cried ...,” 8 Stichera of the holy apostle, in Tone VI:`,tier:1,src:{file:`11-14.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`Having made activity * the ascent to true vision, * and the end of vision, love for God, * O blessed one, * thou didst beseech Christ * to show thee the ineffable glory of the Father, * for every rational being, O glorious one, * doth desire God the Creator, * and thou didst obtain * that which thou didst desire, * straightway receiving the seal of His Son. ** Entreat Him with boldness on behalf of our souls.`,tier:2,src:{file:`11-14.pdf`,locus:`p1 LIC 1`},label:`plain`,tone:6,repeat:3,spec_mel:`Having set all aside ...`},{text:`Ever instructed * by divine ascents, * as Moses had been in the past, * thou didst desire to behold God; * and noetically thou didst behold His image, * having received His likeness. * For the Son is the immaculate knowledge * and disclosure of the Father; * and the Son is known to be * of the same essence as the Father, * and their unity, kingdom, power, glory and worship ** are exalted with honor by all.`,tier:2,src:{file:`11-14.pdf`,locus:`p1 LIC 2`},label:`plain`,repeat:3,spec_mel:`Having set all aside ...`},{text:`Thou wast an instrument * of the Holy Spirit, * sounding with divine phrases and melodies, * chanting in the world * the music of the transcendent Gospel of the Savior * with thy tongue of fire. * For thou didst utterly consume all delusion * as matter fit to be burned, * as the withered grass of the earth. * And thou didst proclaim to the whole world * the Lord Christ Who is Master over all, ** O Philip, beholder of God.`,tier:2,src:{file:`11-14.pdf`,locus:`p1 LIC 3`},label:`plain`,repeat:2,spec_mel:`Having set all aside ...`}],lic_glory:{text:`Burning with rays of the great Light, O Philip, thou didst shine forth as a universal beacon; and having sought, thou didst find the Father of lights within the Son, for light is revealed in light, just as a seal is identical, disclosing the Archetype. Him do thou beseech, O Philip, that we who have been sealed by His divine blood may be saved.`,tier:1,src:{file:`11-14.pdf`,locus:`p1 LIC Glory`},composer:`Emperor Leo VI, the Wise, of Byzantium`,sourceLabel:`Glory ..., in Tone VI, by Emperor Leo VI, the Wise, of Byzantium`,tone:6},dogmatikon:{text:`Who doth not call thee blessed, O most holy Virgin? * Who will not hymn thy most pure birthgiving? * For the only-begotten Son Who hath shone forth timelessly from the Father, * came forth, ineffably incarnate, from thee, O pure one; * By nature He is God, by nature for our sakes, He hath become a man * not divided into two Hypostases, * but known in two natures without commingling. * Him do thou beseech, O pure and most blessed one, ** that our souls find mercy!`,tier:2,src:{file:`11-14.pdf`,locus:`p1 LIC Both now, Dogmatic Theotokion`},type:`dogmatic_theotokion`,sourceLabel:`Both now ..., the Dogmatic Theotokion, in Tone VI`,tone:6},entrance_rubric:{text:`Entrance. Prokeimenon of the Day. Three Lessons:`,tier:1,src:{file:`11-14.pdf`,locus:`p2 Entrance`}},readings:[{heading:`A READING FROM THE GENERAL EPISTLE OF JOHN`,src:{file:`11-14.pdf`,locus:`p2 Lesson 1`},citation_verbatim:`(I JN. 3: 21-4: 6)`,citation:{book:`1 John`,chapter:3,verses:`3:21-4:6`},citation_basis:`printed`},{heading:`A READING FROM THE GENERAL EPISTLE OF JOHN`,src:{file:`11-14.pdf`,locus:`p2 Lesson 2`},citation_verbatim:`(I JN. 4: 11-16)`,citation:{book:`1 John`,chapter:4,verses:`11-16`},citation_basis:`printed`},{heading:`A READING FROM THE GENERAL EPISTLE OF JOHN`,src:{file:`11-14.pdf`,locus:`p2 Lesson 3`},citation_verbatim:`(I JN. 4: 20-5: 5)`,citation:{book:`1 John`,chapter:4,verses:`4:20-5:5`},citation_basis:`printed`}],litiya:{rubric:{text:`At the Litiya, the Sticheron of the temple, and these of the apostle, in Tone IV:`,tier:1,src:{file:`11-14.pdf`,locus:`p2 Litiya rubric`}},stichera:[{text:`With the rod of grace, * O right wondrous one, * thou didst draw all from the abyss of vanity, * submitting to the order of thy Teacher, * Who wholly enlightened thine understanding * and showed thee to be an honored apostle * and a divine proclaimer * of His unapproachable Divinity, ** O all-blessed Philip.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Litiya 1`},label:`plain`,tone:4,spec_mel:`As one valiant among the martyrs ...`},{text:`The radiance of the Spirit * descended upon thee in the guise of fire, * and made of thee a divine dwelling, O blessed one, * who quickly drivest off the gloom of godlessness, * and enlightenest the world * with the splendor of thine all-wise words, * O proclaimer of the mysteries of God, * adornment of the apostles ** and beholder of Christ, O blessed one.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Litiya 2`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`},{text:`Having illumined with the lightning flashes of thy preaching * those who sit in the darkness of unbelief, * O glorious one, * thou didst show them to be sons of our God and Master * through their faith. * Thou didst emulate His sufferings and death * and didst become an heir to His glory, * in that thou art a wise proclaimer of God, ** a disciple of Truth.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Litiya 3`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`}],glory:{text:`Having forsaken earthly things, thou didst follow after Christ, signed with the inspiration of the Holy Spirit and sent by Him to the Gentiles which were perishing, to turn mankind to the light of the knowledge of God, O apostle Philip. And, having completed the struggles of thy divine suffering and divers torments, thou didst commit thy soul to Christ. Him do thou entreat, O all-blessed one, that He grant us great mercy.`,tier:1,src:{file:`11-14.pdf`,locus:`p3 Litiya Glory`},sourceLabel:`Glory ..., in Tone II`,tone:2},both_now:{text:`All my hope do I place in thee, * O Mother of God; ** keep me under thy protection.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Litiya Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion in Tone II`,tone:2}},aposticha_rubric:{text:`On the Aposticha, these Stichera, in Tone I:`,tier:1,src:{file:`11-14.pdf`,locus:`p3 Aposticha rubric`}},aposticha:[{text:`The proclamations of thy divine pronouncements * have resounded throughout the earth, O all-blessed one, * and have filled it with dogmas; * theologizing therewith, * we mystically glorify the Son, ** Who is of one essence with the Father and the Spirit, O apostle.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Aposticha 1`},label:`plain`,tone:1,spec_mel:`Joy of the ranks of heaven ...`},{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`O thrice-blessed Philip, * having thee as the lamp-bearer of the apostles of Christ * and the radiant beacon of the honored Church, * we are all now enlightened in soul * and delivered from most grievous misfortunes ** by thy prayers, O all-praised one.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Aposticha 2`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`},{text:`The heavens declare the glory of God, * and the firmament proclaimeth the work of His hands.`,tier:2,src:{file:`11-14.pdf`,locus:`p3 Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Having finished thy struggle with a cross of suffering, * thou wast fittingly arrayed in crowns of victory, O Philip, * and entering therewith * into the high places of the kingdom, * thou dost stand before Christ, O apostle, ** praying that we be saved.`,tier:2,src:{file:`11-14.pdf`,locus:`p4 Aposticha 3`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`}],aposticha_glory:{text:`Thy cheeks have been shown to be vessels of perfume in the world, O wise one, which draw forth life-creating drink for the faithful, O apostle Philip. For, possessed of works which led up to divine vision, thou didst become a follower and herald of Christ; with teachings thou didst adorn the barren and childless Church of the Gentiles for Him Who rejoiceth in the children therein. Pray thou that it be delivered from every want and evil circumstances, for thou art able to do much, drawing nigh unto Him.`,tier:1,src:{file:`11-14.pdf`,locus:`p4 Aposticha Glory`},sourceLabel:`Glory ..., in Tone II`,tone:2},aposticha_closer:{text:`O new wonder greater than all the wonders of old! * For who hath ever known a mother to give birth without having known a man, * and to bear on her arm Him Who sustaineth all creation? * Yet it was the will of God to be born. * O most pure one, who carried Him as an infant in thine embrace * and before Whom thou hast a mother's boldness: * cease not to pray on behalf of those who honor thee, ** that He have compassion and save our souls.`,tier:2,src:{file:`11-14.pdf`,locus:`p4 Aposticha Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion, in Tone II`,tone:2},troparion_rubric:{text:`At the blessing of the Loaves, the Troparion, in Tone III:`,tier:1,src:{file:`11-14.pdf`,locus:`p4 Blessing of the Loaves rubric`}},virgin_theotokos_rubric:{text:`And “Virgin Theotokos, rejoice ...,” (Once).`,tier:1,src:{file:`11-14.pdf`,locus:`p4 Virgin Theotokos rejoice rubric`}},troparion_alternate_rubric:{text:`Or this Troparion, in the same tone:`,tier:1,src:{file:`11-14.pdf`,locus:`p4 Or this Troparion rubric`}},troparion_alternate:{text:`The whole world is splendidly adorned; * Ethiopia doth dance, graced as with a crown, * having been enlightened by thee, * and she doth radiantly celebrate thy memory, O divinely eloquent Philip, * for thou didst teach all to believe in Christ * and didst fittingly finish the course of the Gospel; * wherefore, the land of Ethiopia doth boldly entreat God. ** Beseech Him to grant us great mercy.`,tier:2,src:{file:`11-14.pdf`,locus:`p4 Or this Troparion`},sourceLabel:`Or this Troparion, in the same tone`}},matins:{order:`god_is_lord_rubric.troparion.troparion_closer.sessional_1.sessional_2.megalynarion_rubric.megalynarion.megalynarion_verse_rubric.megalynarion_verse.megalynarion_closing_rubric.sessional_polyeleos.anabathmoi_rubric.prokeimenon.prokeimenon_verse.gospel_rubric.gospel.psalm50_sticheron.canon_rubric.canons.sessional_ode3.kontakion.ikos.exapostilarion.exapostilarion_closer.praises_rubric.praises.praises_glory.praises_closer.closing_rubric`.split(`.`),god_is_lord_rubric:{text:`On “God is the Lord ...,” the Troparion, of the holy apostle, in Tone III:`,tier:1,src:{file:`11-14.pdf`,locus:`p5 God is the Lord rubric`}},troparion_closer:{text:`We hymn thee who hast mediated the salvation of our race, * O Virgin Theotokos; * for thy Son and our God, * accepting suffering on the Cross in the flesh * He had received of thee, * hath delivered us from corruption, ** in that He is the Lover of mankind.`,tier:2,src:{file:`11-14.pdf`,locus:`p5 God is the Lord Theotokion`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion`},sessional_1:[{text:`O Philip most wise, apostle, martyr and beholder of Christ, blessed friend of God: by thy prayers do thou free from tenacious transgressions those who celebrate thine honored memory, and grant that they may receive a heavenly inheritance.`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Sessional 1`},label:`plain`,repeat:2,sourceLabel:`After the 1st chanting of the Psalter, the Sessional Hymn, in Tone I`,spec_mel:`Thy tomb, O Savior ...`,tone:1},{text:`O Virgin, we hymn thee, the unburnt bush which Moses saw, the mountain of God, the holy cloud, the undefiled tabernacle, the God-pleasing table, the palace of the King Most High, the all-splendid and impassable gate.`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Sessional 1 Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone I`,tone:1}],sessional_2:[{text:`Like an arrow hast thou been sent, a disciple of the Word and a proclaimer of the truth, enlightening those who are in grievous darkness, O holy apostle, and driving the gloom of godlessness from the earth, thou didst show them forth as right believing children of the day, O beholder of Christ, holy Philip.`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Sessional 2`},label:`plain`,repeat:2,sourceLabel:`After the 2nd chanting of the Psalter, the Sessional Hymn, in Tone V`,spec_mel:`The co-beginningless Word...`,tone:5},{text:`O most pure Virgin, who art our protection, from divers temptations and evil circumstances and grievous misfortunes do thou free us who have steadfast hope in thee, beseeching thy Son together with His apostles, and save thou all that hymn thee.`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Sessional 2 Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone V`,tone:5}],megalynarion_rubric:{text:`After the Polyeleos, this magnification:`,tier:1,src:{file:`11-14.pdf`,locus:`p5 magnification rubric`}},megalynarion:{text:`We magnify thee, O Philip, apostle of Christ, and we honor thy pangs and labors, wherewith thou didst struggle in the proclamation of the Gospel of Christ.`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Magnification`},label_inline:!0},megalynarion_verse_rubric:{text:`Selected Psalm Verse:`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Selected Psalm Verse rubric`}},megalynarion_verse:{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-14.pdf`,locus:`p5 Selected Psalm verse`},label:`refrain`,sourceLabel:`A`,label_inline:!0},megalynarion_closing_rubric:{text:`Glory ..., Both now ..., Alleluia ..., Glory to Thee, O God. (Thrice)`,tier:1,src:{file:`11-14.pdf`,locus:`p5 after the selected verses`}},sessional_polyeleos:[{text:`Thou didst set at naught the deception of idolatry, desiring the Savior's sufferings, O glorious Philip. Thou didst appear unto the world, pouring forth heavenly wonders upon all, and wast an apostle to the Gentiles, O all-blessed one. Wherefore, we honor thy memory as is meet, chanting: O apostle of the Lord, beseech Christ God to grant remission of sins unto those who celebrate thy holy memory with love.`,tier:1,src:{file:`11-14.pdf`,locus:`p6 Polyeleos sessional`},label:`plain`,repeat:2,sourceLabel:`After the Polyeleos, the Sessional Hymn, in Tone VIII`,spec_mel:`Of Wisdom ...`,tone:8},{text:`From the snares of enemies visible and invisible, * we have been overcome by the storms of our uncountable sins, * and fleeing unto the safe harbor of thy goodness O pure one, * we have thee as our rampart and sure protection. * Wherefore we thy servants beseech thee * to ceaselessly make fervent supplication, O most pure one, * unto Him who seedlessly became incarnate from thee, * that those who worthily hymn thee ** may be granted the remission of their sins.`,tier:2,src:{file:`11-14.pdf`,locus:`p6 Polyeleos sessional Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone VIII`,tone:8}],anabathmoi_rubric:{text:`Song of Ascents, the first Antiphon of Tone IV:`,tier:1,src:{file:`11-14.pdf`,locus:`p6 Song of Ascents rubric`}},prokeimenon:{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-14.pdf`,locus:`p6 Prokeimenon`},sourceLabel:`Prokeimenon, in Tone IV`,label_inline:!0,tone:4},prokeimenon_verse:{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-14.pdf`,locus:`p6 Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel_rubric:{text:`Let every breath praise the Lord.`,tier:1,src:{file:`11-14.pdf`,locus:`p6 Let every breath`}},gospel:{heading:`THE GOSPEL ACCORDING TO ST. JOHN`,src:{file:`11-14.pdf`,locus:`p6 Matins Gospel`},citation_verbatim:`(21:15-25)`,citation:{book:`John`,chapter:21,verses:`15-25`},citation_basis:`printed`},psalm50_sticheron:{text:`O most wise fisherman, holy disciple, husbandman of the Savior and recounter of His sufferings, who went about all creation in faith, gathering the deceived nations: rising to God as a sweet fragrance of incense, thou didst ascend unto the heavens. Wherefore, standing before the Judge, ask that we be delivered from our transgressions and freed from torment on the day of Judgment.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 After Psalm 50 sticheron`},sourceLabel:`After Psalm 50, this Sticheron, in Tone VI`,tone:6},canon_rubric:{text:`Canon of the Theotokos (the Paraklisis), with 6 Troparia, including the Irmos; and that of the holy apostle, with 8 Troparia, the acrostic whereof is: “I hymn the glorious Philip in seemly manner,” the composition of Theophanes, in Tone VI:`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Canon rubric`}},canons:[{title:`Canon of the Theotokos (the Paraklisis), with 6 Troparia, including the Irmos; and that of the holy apostle, with 8 Troparia, the acrostic whereof is: “I hymn the glorious Philip in seemly manner,” the composition of Theophanes, in Tone VI:`,composer:`Theophanes`,acrostic:`I hymn the glorious Philip in seemly manner`,tone:6,odes:{1:{irmos:{text:`When Israel walked on foot in the sea as on dry land, * on seeing their pursuer Pharaoh drowned, * they cried: * Let us sing to God * a song of victory.`,tier:2,src:{file:`11-14.pdf`,locus:`p7 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Manifestly delighting in the most luminous rays of the divine splendor of Christ, O divine preacher Philip, do thou enlighten us to partake of thy rays.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 1 troparion 1`},label:`plain`},{text:`Christ Himself, showing thee the glory of the Father, enrolled thee in the choir of His disciples, O Philip, perceiving thy virtue, O divinely blessed one.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 1 troparion 2`},label:`plain`},{text:`Now thou dost not behold Christ, the Wellspring of blessings, the Ultimate of desires, in indistinct images, or shadows, or reflections, O all-wise one, but thou dost clearly behold Him face to face.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 1 troparion 3`},label:`plain`},{text:`O most pure one, thy Son and God, having come forth from the tribe of Judah unto its failing princes, hath now truly reigned as King, Ruler of the ends of the earth.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}],katavasia:{text:`I shall open my mouth ...,`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 1 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},3:{irmos:{text:`There is none as holy as Thou, * O Lord my God, * who hast exalted the horn of Thy faithful O good One, * and strengthened us upon the rock * of Thy confession.`,tier:2,src:{file:`11-14.pdf`,locus:`p7 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Full of the light of active vision, thou wast deemed worthy to serve Christ, the great Light, Who hath been with us, O divinely eloquent Philip.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 3 troparion 1`},label:`plain`},{text:`Thine explication of the mysteries hath been shown to be a ladder of divine dogmas whereby we have come to know the Son, Who is consubstantial and united with the Father.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 3 troparion 2`},label:`plain`},{text:`Thou wast a golden lamp shining forth the ever-existing Light upon mankind and thereby manifestly enlightening the whole world with knowledge, O most eminent Philip.`,tier:1,src:{file:`11-14.pdf`,locus:`p7 Ode 3 troparion 3`},label:`plain`},{text:`Trusting in thee, O most holy and pure one, may I not fall from thine expectation; but, as thou art the merciful Mother of God, the Lover of mankind, deliver me from the snares of the enemy.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Christ is my power, * my God and my Lord, * the holy Church divinely singeth, * crying with a pure mind, * keeping festival in the Lord.`,tier:2,src:{file:`11-14.pdf`,locus:`p8 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou hast been shown to be a dwelling place of the Sun, of Christ Who is the Light, and a temple which containeth His splendor, and a heaven proclaiming the glory of God unto mankind.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode 4 troparion 1`},label:`plain`},{text:`Casting the salt of God which is from Christ, into mankind corrupted by the passions, O right glorious herald of God, thou didst dry up the filth thereof.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode 4 troparion 2`},label:`plain`},{text:`Strengthened with the power of Christ, O Philip, thou wast shown to be more powerful than the legions of demons and the wicked, proclaiming unto those who are on earth the glad tidings of divine life.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode 4 troparion 3`},label:`plain`},{text:`Christ hath revealed a calm harbor unto those who with faith and love and with a pure conscience proclaim thee, the true and all-immaculate Lady, to be the Theotokos.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`Illumine with Thy divine light, I pray, O good One, * the souls of those who with love rise early to pray to Thee, * that they may know Thee, O Word of God, * as the true God, * Who recalleth us from the darkness of sin.`,tier:2,src:{file:`11-14.pdf`,locus:`p9 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O divinely eloquent one, having dried up the deadly abyss of the soul-destroying poison of the enemy with thy healing hands, thou dost deliver those who are opposed by grievous sickness.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 5 troparion 1`},label:`plain`},{text:`Thou hast been revealed to be wholly fiery of breath, O Philip, through the descent and grace of the Paraclete, and with the warmth of faith thou hast restored to life those who were chilled through by the winter of godlessness.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 5 troparion 2`},label:`plain`},{text:`Thou wast close to Christ, receiving directly the rays bestowed upon thee; enlight-ening those who have recourse unto thee, and leading them to their Creator.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 5 troparion 3`},label:`plain`},{text:`The Lord, Who alone doth fashion all things by His Word and doth nourish them in His wise providence, as He willed in His tender compassion, was fashioned of thee and ineffably assumed flesh, O most pure one.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`Jonah was caught but not held * in the belly of the whale; * for, bearing the image of Thee, * Who hast suffered and wast given to burial, * he came forth from the sea-monster as from a bridal chamber, * and he called out to the watch: * “O ye who keep guard falsely and in vain, * ye have forsaken your own mercy.”`,tier:2,src:{file:`11-14.pdf`,locus:`p9 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Beholding the deception of the enemy which doth surround and destroy the human race, taking aim, Thou didst loose Thy sharpened arrows, the apostles, and didst lay open the serpent's mouth of clay, O Savior, healing all who had been harmed by his wounding corruption.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 6 troparion 1`},label:`plain`},{text:`Shining with exalted splendor, thou didst appear as lightning illumining the whole world, as a mountain which sheddeth sweetness like a divine rose given by heaven, as an elect apostle completing the twelve-man host of the disciples of Christ, O all-blessed one.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 6 troparion 2`},label:`plain`},{text:`The godly disciple, having learned the depth of Thy mystery, loudly proclaimed Thee the Glory of the nations, Who, like a river of the world and like a flooding wave, gave rise to streams of delight; and he announced the glad tidings of Thy glorious condescension for us, O good One.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 6 troparion 3`},label:`plain`},{text:`Having given birth unto Christ, the incorrupt Immortality, thou hast called all mankind, who are mortal and perishing, unto eternal life, enlightening and freeing the darkened, and loosing the bonds of our captivity.`,tier:1,src:{file:`11-14.pdf`,locus:`p9 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`In Babylon the children feared not the fiery furnace; * but cast into the midst of the flames * they were bedewed and sang: * ‘O Lord God of our fathers, blessed art Thou.’`,tier:2,src:{file:`11-14.pdf`,locus:`p10 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`As light, thou hast been loosed in the guise of an arrow, O apostle, illumining with splendid radiance those who cry out with faith: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-14.pdf`,locus:`p10 Ode 7 troparion 1`},label:`plain`},{text:`Radiantly shining with the rich outpourings of divine preaching, O blessed one, thou hast enlightened those who are in darkness to chant: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-14.pdf`,locus:`p10 Ode 7 troparion 2`},label:`plain`},{text:`Having vanquished by the mighty word of faith all the craft of the rhetors' logic and fables, thou didst chant: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-14.pdf`,locus:`p10 Ode 7 troparion 3`},label:`plain`},{text:`O pure Virgin, thou didst give birth supra-naturally unto Christ in two unified, yet uncommingled, natures. To Him do we cry out: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-14.pdf`,locus:`p10 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`Suffering affliction for the sake of the laws of their fathers, * the blessed children in Babylon * scorned the foolish decree of the King. * Standing together in the midst of the flames, they remained unharmed, * and sang a song fitting for almighty God: * ‘O ye works of the Lord, praise ye the Lord * and supremely exalt Him throughout all ages.’`,tier:2,src:{file:`11-14.pdf`,locus:`p10 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The hypostatic Word, the Light of the Father, made thee a light unto the world, O thrice-blessed one, choosing thee as an apostle from amongst those in the world. And having armed thee with His divine power, He sent thee as an invincible warrior, crying out: O ye works of the Lord, praise ye the Lord and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-14.pdf`,locus:`p10 Ode 8 troparion 1`},label:`plain`},{text:`Strengthened with divine power, O apostle, thou didst conquer hosts of adversaries, destroying their raging army; for, taking up peace as thine inviolable weapon, thou didst instill a state of peace in the world, crying aloud: O ye works of the Lord, praise ye the Lord and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 8 troparion 2`},label:`plain`},{text:`With all thy love thou didst cleave unto the incarnate Word of God, O apostle, being His disciple, a servant of God and teacher of the mysteries. Hence, sent by Him unto the Gentiles, thou didst preach His coming, crying aloud: O ye works of the Lord, praise ye the Lord and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 8 troparion 3`},label:`plain`},{text:`In thy womb, O all-holy Virgin, the supremely divine One wholly united Himself to all of mankind immutably and in a manner which surpasseth all understanding. Wherefore, Christ is known in two natures, being one and both. Chanting unto Him, we cry aloud: O ye works of the Lord, praise ye the Lord and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`It is impossible for mankind to see God * upon Whom the orders of angels dare not gaze; * but through thee, O all-pure one, * did the Word Incarnate become a man * and with the heavenly Hosts * Him we magnify and thee we call blessed.`,tier:2,src:{file:`11-14.pdf`,locus:`p11 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having now been deemed worthy of ineffable glory and the unwaning light, where the gladness is unutterable, and the joy unending, among the congregations of the firstborn, where the habitations of the righteous are, O Philip all-wise, pray thou for all Christians.`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 9 troparion 1`},label:`plain`},{text:`Invested with the comeliness of noetic splendor, adorned with a crown of the Kingdom and with radiant brilliance, enlightened with outpourings of supra-natural light, O divinely wise Philip, thou dost stand, rejoicing, before the throne of the Master, O blessed one.`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 9 troparion 2`},label:`plain`},{text:`With all the honored apostles, the prophets and passion-bearers, the venerable, the hierarchs and the righteous, and with the Theotokos, O Philip, ask that remission of many sins and the cleansing of transgressions be given to those who faithfully celebrate thy radiant and divine memory.`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 9 troparion 3`},label:`plain`},{text:`O Virgin Mother, thou didst give birth unto the incarnate Word, Who before was incorporeal. Wherefore, we all piously glorify thee as the Theotokos, ascribing to thee that most true of titles, O pure one, for thou ever remainest the root of the salvation of the faithful.`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`Truly thou hast been shown to be a spiritual rain-laden cloud for those on earth, mystically watering our hearts as though they were fields. Having passed over the earth with the word, thou dost water the ends thereof, pouring forth a rain of myrrh from thy shrine. Wherefore, having breathed the fragrance of the Spirit upon the hearts of unbelievers, thou didst lay up treasures therein, O apostle Philip. Entreat Christ God to grant remission of sins unto those who celebrate thy holy memory with love.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode III sessional`},label:`plain`,sourceLabel:`Sessional Hymn of the holy apostle, in Tone VIII`,spec_mel:`Of Wisdom ...`,tone:8},{text:`Aspiring to the sufferings of the Savior, thou didst set the delusion of idolatry at naught, O glorious Philip; thou didst appear to the world pouring forth heavenly wonders upon all, having become an apostle to the Gentiles, O all-blessed one. Wherefore, we honor thy memory as is meet, chanting: O apostle of Christ, entreat Christ God to grant remission of sins unto those who celebrate thy holy memory with love.`,tier:1,src:{file:`11-14.pdf`,locus:`p8 Ode III sessional Glory`},label:`glory`,sourceLabel:`Glory ..., in the same melody`},{text:`From the snares of enemies visible and invisible, * we have been overcome by the storms of our uncountable sins, * and fleeing unto the safe harbor of thy goodness O pure one, * we have thee as our rampart and sure protection. * Wherefore we thy servants beseech thee * to ceaselessly make fervent supplication, O most pure one, * unto Him who seedlessly became incarnate from thee, * that those who worthily hymn thee ** may be granted the remission of their sins.`,tier:2,src:{file:`11-14.pdf`,locus:`p8 Ode III sessional Theotokion`},type:`theotokion`,label:[`both_now`,`theotokion`],sourceLabel:`Both now ..., Theotokion, in Tone VIII`,tone:8}],exapostilarion:{text:`Turning the course of thy beautiful feet, O Philip, thou didst mount the path to heaven, rejoicing; and, standing before the Trinity, thou dost behold the Son and the divine Spirit in the Father. Wherefore, we celebrate thy most sacred and divine memory with faith.`,tier:1,src:{file:`11-14.pdf`,locus:`p11 Exapostilarion`},label:`plain`,repeat:2,sourceLabel:`Exapostilarion of the holy apostle`,spec_mel:`By the Spirit in the sanctuary ...`},exapostilarion_closer:{text:`I call to mind the dreadful hour of testing, for the multitude of mine evil deeds doth terrify and frighten me. Yet take pity on me in thy fervent prayer, O most pure one, and grant me salvation. For whatsoever thou desirest, thou canst do, in that thou hast given birth unto God, O blessed Mary.`,tier:1,src:{file:`11-14.pdf`,locus:`p12 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion`},praises_rubric:{text:`On the Praises, 4 Stichera, 3 in Tone VIII:`,tier:1,src:{file:`11-14.pdf`,locus:`p12 Praises rubric`}},praises:[{text:`O most glorious wonder! * The apostle who once cast his nets for fish * hath become a fisher of men, * appointed by God. * He fished for the nations with the net of his discourse * and brought up the world with the rod of the Cross. * O what a draught * the divine worker hath brought unto God, ** he whose memory we now celebrate.`,tier:2,src:{file:`11-14.pdf`,locus:`p12 Praises 1`},label:`plain`,tone:8,spec_mel:`O most glorious wonder ...`},{text:`O most glorious wonder! * Sent by God like a lamb amongst wolves, * the apostle Philip fearlessly strode forth * and, through faith, showed forth wild beasts to be lambs, * divinely transforming the world. * O, his works of faith! * O, his most excellent powers! * By his prayers, O Christ, save Thou our souls, ** in that Thou alone art compassionate.`,tier:2,src:{file:`11-14.pdf`,locus:`p12 Praises 2`},label:`plain`,spec_mel:`O most glorious wonder ...`},{text:`O most glorious wonder! * The apostle Philip * hath, through the outpouring of wisdom, * become a wellspring gushing forth life * upon those who are in the world. * Therefrom do streams of dogmas proceed * and we drink of the torrents of the wonders thereof. * O, how many awesome miracles the divine worker hath wrought, ** whose memory we glorify with faith!`,tier:2,src:{file:`11-14.pdf`,locus:`p12 Praises 3`},label:`plain`,spec_mel:`O most glorious wonder ...`},{text:`Thou wast revealed as a heavenly chalice of wisdom, for thou wast revealed to be a beauteous habitation of the Spirit, and didst recount the truth of the virtues, fishing for mortals with the noetic rod of the wisdom of God. Wherefore, we beseech thee, O apostle Philip: Pray thou on behalf of our souls.`,tier:1,src:{file:`11-14.pdf`,locus:`p12 Praises 4`},label:`plain`,sourceLabel:`And this, in Tone II`,label_inline:!0,tone:2}],praises_glory:{text:`Having exchanged the catching of fish for the fishing of men, with the net of thy mysteries thou hast drawn in those who are in the depths of deception, O apostle Philip. Thou didst pursue the whole world and didst bring it to Christ, thy Teacher. Wherefore, we entreat thee: Beseech Him unceasingly, that He save the souls of us who faithfully keep thy most honored memory.`,tier:1,src:{file:`11-14.pdf`,locus:`p12 Praises Glory`},sourceLabel:`Glory ..., in Tone III`,tone:3},praises_closer:{text:`O Theotokos, intercessor for all who pray to thee, in thee do we boast, in thee do we embolden ourselves; in thee do we place all our hope. Beseech Him Who was born from thee on behalf of thine unprofitable servants.`,tier:1,src:{file:`11-14.pdf`,locus:`p12 Praises Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion`},closing_rubric:{text:`Great Doxology, Troparion and Theotokion, Dismissal. First Hour`,tier:1,src:{file:`11-14.pdf`,locus:`p12 Matins closing rubric`}}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`liturgy_troparion`,`troparion_alternate_rubric`,`troparion_alternate`,`kontakion`,`prokeimenon`,`prokeimenon_verse`,`epistle`,`alleluia`,`alleluia_verse`,`gospel`,`communion_verse`],beatitudes_rubric:{text:`On the Beatitudes, 8 Troparia, 4 from ODE III and 4 from ODE VI of the canon of the holy apostle.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitudes rubric`}},beatitudes:[{text:`Full of the light of active vision, thou wast deemed worthy to serve Christ, the great Light, Who hath been with us, O divinely eloquent Philip.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 1`},label:`plain`,repeat:2},{text:`Thine explication of the mysteries hath been shown to be a ladder of divine dogmas whereby we have come to know the Son, Who is consubstantial and united with the Father.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 2`},label:`plain`},{text:`Thou wast a golden lamp shining forth the ever-existing Light upon mankind and thereby manifestly enlightening the whole world with knowledge, O most eminent Philip.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 3`},label:`plain`},{text:`Beholding the deception of the enemy which doth surround and destroy the human race, taking aim, Thou didst loose Thy sharpened arrows, the apostles, and didst lay open the serpent's mouth of clay, O Savior, healing all who had been harmed by his wounding corruption.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 4`},label:`plain`},{text:`Shining with exalted splendor, thou didst appear as lightning illumining the whole world, as a mountain which sheddeth sweetness like a divine rose given by heaven, as an elect apostle completing the twelve-man host of the disciples of Christ, O all-blessed one.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 5`},label:`plain`},{text:`The godly disciple, having learned the depth of Thy mystery, loudly proclaimed Thee the Glory of the nations, Who, like a river of the world and like a flooding wave, gave rise to streams of delight; and he announced the glad tidings of Thy glorious condescension for us, O good One.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 6`},label:`plain`},{text:`Having given birth unto Christ, the incorrupt Immortality, thou hast called all mankind, who are mortal and perishing, unto eternal life, enlightening and freeing the darkened, and loosing the bonds of our captivity.`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Beatitude 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}],liturgy_troparion:{text:`O holy apostle Philip, * entreat the Merciful God * that He grant remission of sins ** unto our souls`,tier:2,src:{file:`11-14.pdf`,locus:`p13 Troparion at Liturgy`},sourceLabel:`Troparion of the holy apostle, in Tone III`,tone:3},troparion_alternate_rubric:{text:`Or this Troparion, in the same tone:`,tier:1,src:{file:`11-14.pdf`,locus:`p13 Or this Troparion rubric (Liturgy)`}},troparion_alternate:{text:`The whole world is splendidly adorned; * Ethiopia doth dance, graced as with a crown, * having been enlightened by thee, * and she doth radiantly celebrate thy memory, O divinely eloquent Philip, * for thou didst teach all to believe in Christ * and didst fittingly finish the course of the Gospel; * wherefore, the land of Ethiopia doth boldly entreat God. ** Beseech Him to grant us great mercy.`,tier:2,src:{file:`11-14.pdf`,locus:`p13 Or this Troparion (Liturgy)`},sourceLabel:`Or this Troparion, in the same tone`},prokeimenon:{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-14.pdf`,locus:`p14 Liturgy Prokeimenon`},sourceLabel:`Prokeimenon, in Tone VIII`,label_inline:!0,tone:8},prokeimenon_verse:{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-14.pdf`,locus:`p14 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle:{heading:`THE FIRST EPISTLE OF ST. PAUL TO THE CORINTHIANS`,src:{file:`11-14.pdf`,locus:`p14 Epistle`},citation_verbatim:`(4:9-16)`,citation:{book:`1 Corinthians`,chapter:4,verses:`9-16`},citation_basis:`printed`},alleluia:{text:`The heavens shall confess Thy wonders, O Lord, and Thy truth in the congregation of the saints.`,tier:1,src:{file:`11-14.pdf`,locus:`p14 Alleluia`},sourceLabel:`Alleluia, in Tone I`,label_inline:!0,tone:1},alleluia_verse:{text:`God Who is glorified in the council of the saints.`,tier:1,src:{file:`11-14.pdf`,locus:`p14 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel:{heading:`THE GOSPEL ACCORDING TO ST. JOHN`,src:{file:`11-14.pdf`,locus:`p14 Gospel`},citation_verbatim:`(1:43-51)`,citation:{book:`John`,chapter:1,verses:`43-51`},citation_basis:`printed`},communion_verse:{text:`Their sound hath gone forth into all the earth, and their words unto the ends of the world.`,tier:1,src:{file:`11-14.pdf`,locus:`p14 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}}},{kind:`saint`,title:{text:`COMMEMORATION OF OUR FATHER AMONG THE SAINTS GREGORY PALAMAS, ARCHBISHOP OF THESSALONICA, THE WONDERWORKER`,tier:1,src:{file:`11-14A.pdf`,locus:`p1 title`},sourceLabel:`THE 14th DAY OF THE MONTH OF NOVEMBER`},rank:`polyeleos`,fekula_section:`2E`,oca_primary:!1,source_file:`11-14A.pdf`,note:`Rank by the encoding_rule_v2.md 1.1 waterfall (ODS vol. III has no 11-14 entry): the heading is AT GREAT VESPERS, no Little Vespers is printed, and Matins appoints the Polyeleos with a magnification. PROVISIONAL, see open question Q-0002: the page prints the blessing of the Loaves and then "But if a vigil is not served", so the book itself treats a Vigil as the expected form. Second commemoration of the day; OCA lists Apostle Philip first. Matins prints its closing stichera under "On the Aposticha" although the service ends with the Great Doxology (Q-0003).`,troparion:{text:`O wonderworker Gregory, instructor in Orthodoxy, * adornment of holy hierarchs, invincible champion of theologians, * great boast of Thessalonica, and preacher of grace: ** entreat Christ God, that our souls be saved.`,tier:2,src:{file:`11-14A.pdf`,locus:`p5 Troparion of the holy hierarch`},sourceLabel:`At the blessing of the Loaves, the Troparion of the holy hierarch, in Tone VIII`,tone:8,verified_sites:[{locus:`p5 blessing of the Loaves`,tone:8,repeat:2},{locus:`p6 God is the Lord`,tone:8,repeat:2},{locus:`p15 AT LITURGY`,tone:8}]},kontakion:{text:`O divinely eloquent Gregory, together we hymn thee, * the sacred and divine instrument of wisdom, the brilliant trumpet of theology. * And as a mind standing before the primal Mind, O father, guide thou our mind unto Him, ** that we may cry: Rejoice, O preacher of grace!`,tier:2,src:{file:`11-14A.pdf`,locus:`p11 Kontakion of the holy hierarch`},verified_sites:[{locus:`p11 after Ode VI`,tone:8},{locus:`p15 AT LITURGY`,tone:8}],sourceLabel:`Kontakion of the holy hierarch, in Tone VIII`,spec_mel:`To thee, the champion leader ...`,tone:8},ikos:{text:`Thou didst appear on earth as an angel, proclaiming the divine tidings of ineffable things unto corruptible men; for, living with the mind and body of a man but with the voice of the incorporeal beings, O divinely eloquent one, thou didst amaze and cause them to cry out to thee such things as these: Rejoice, thou for whose sake the Light was proclaimed; Rejoice, thou for whose sake the darkness was dispelled! Rejoice, herald of the uncreated Godhead; Rejoice, thou who truly denounced the foolish teaching that the Essence of God is created! Rejoice, surpassing height who spake of the Essence of God; Rejoice, depth which the eyes cannot easily plumb, who told of spiritual activity! Rejoice, for thy words concerning the glory of God were good; Rejoice, for thou didst reject the reasoning of the wicked! Rejoice, luminary who hast shown us the Sun; Rejoice, vessel and receptacle of the divine Food! Rejoice, thou through whom the truth shineth forth; Rejoice, thou by whom delusion hath been cast into darkness! Rejoice, O preacher of grace!`,tier:1,src:{file:`11-14A.pdf`,locus:`p11 Ikos`},sourceLabel:`Ikos`,label_inline:!0},great_vespers:{order:[`rubric`,`lic_rubric`,`lic`,`lic_glory`,`dogmatikon`,`entrance_rubric`,`readings`,`aposticha_rubric`,`aposticha`,`aposticha_glory`,`aposticha_closer`,`troparion_rubric`,`troparion`,`virgin_theotokos_rubric`,`no_vigil_rubric`,`troparion_closer`,`closing_rubric`],rubric:{text:`After the Introductory Psalm, we chant “Blessed is the man ...,” the first antiphon.`,tier:1,src:{file:`11-14A.pdf`,locus:`p1 Great Vespers rubric`}},lic_rubric:{text:`On “Lord, I have cried ...,” 6 Stichera of the holy hierarch: 3 in Tone V:`,tier:1,src:{file:`11-14A.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`O venerable father, sacred Gregory, thou didst spring forth as a branch from a God -loving and splendid root, and wast seen to be like a tree planted well by streams of divine waters, which of old poured forth the fruits of immortality, amazing every ear with thy divine activity, discourse and character, an orator among orators, most wise in the knowledge of God, entreating Christ, ever thirsting for Christ, ascending from divine glory to glory and from power to truly incorrupt power.`,tier:1,src:{file:`11-14A.pdf`,locus:`p1 LIC 1`},label:`plain`,tone:5,spec_mel:`O venerable father ...`},{text:`O venerable father, right wondrous Gregory, having forsaken those things that are transitory and drag one down, and loving those things which are incorrupt and heavenly, thou didst leave behind fleeting riches, O wise one, holding poverty to be lasting wealth; and having purified the eyes of thy soul with abstinence, tears and much weeping, thou wast shown to be a splendid vessel of the Spirit, wholly full of His grace. Ask thou that He grant that effulgence and that glory to those who worship the one God, the almighty Trinity.`,tier:1,src:{file:`11-14A.pdf`,locus:`p1 LIC 2`},label:`plain`,spec_mel:`O venerable father ...`},{text:`O venerable father, most sacred Gregory, having sharpened the sword of thy discourse with the Spirit, thou didst become as fire for the ranks of those who waged war upon God, felling and burning down their blasphemies like lightning falling from on high, but guiding all the faithful to the divine radiance of the threefold Sun, enlightened by Whom thou wast shown to be a secondary luminary co-enthroned and numbered with the preeminent theologians, with whom thou art praised and with whom thou abidest. And now pray that unity, peace and great mercy be granted to the Church.`,tier:1,src:{file:`11-14A.pdf`,locus:`p1 LIC 3`},label:`plain`,spec_mel:`O venerable father ...`},{text:`Assembling together, * with songs we hymn thee as is meet: * the inextinguishable lamp, * the never-waning effulgence * which saveth those who sail the seas, * the calm and tranquil haven of grace; * and we pray: from noetic tempests deliver the Church * by thy supplications, ** for thou didst manfully contend on its behalf.`,tier:2,src:{file:`11-14A.pdf`,locus:`p1 LIC 4`},label:`plain`,sourceLabel:`And 3 Stichera, in Tone IV`,spec_mel:`As one valiant among the martyrs ...`,tone:4},{text:`O Gregory, thou spiritual breath of the voice of the Word, * unquenchable and fiery tongue of theology, * who by grace hath splendidly consumed * the vile assembly of the heretics: * we pray that we who hymn thee * in Orthodox manner * may by thine entreaties * be delivered from the imposition ** of the enemies' commands.`,tier:2,src:{file:`11-14A.pdf`,locus:`p1 LIC 5`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`},{text:`O father Gregory, Christ hath placed thee * as a radiant lamp for the Church, * as one who first shone forth in labors and inner stillness, * and with the Spirit thundered forth * readily understandable and profound writings, * and by thy supplications, * discourses and the power of miracles * hast illumined the whole world, ** making firm those who were not steadfast.`,tier:2,src:{file:`11-14A.pdf`,locus:`p2 LIC 6`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`}],lic_glory:{text:`Having adorned thy discourse with wisdom and blameless virtue, O most wise Gregory, in both thou wast wholly beautiful, noetically adorning and gladdening the people with thy God proclaiming words, extending to them the one Godhead of the Trinity; wherefore, having trampled alien heresy underfoot with Thine exceedingly glorious teachings, thou didst raise up the might of the Faith in the end. Standing before Christ with His immaterial ministers, ask thou peace and great mercy for our souls.`,tier:1,src:{file:`11-14A.pdf`,locus:`p2 LIC Glory`},sourceLabel:`Glory ..., in Tone IV`,tone:4},dogmatikon:{text:`Prophet David, the ancestor of God, * spoke of thee in psalmody unto Him Who hath accomplished great things in thee. * For God was well pleased without father to become a man from thee, * the Queen who standeth at His right hand, * and He - the source of life - showed thee to be His mother, * that He might renew His own image, corrupted by the passions. * Having found the lost sheep wandering on the mountain * He hath laid it upon His shoulders, * that He may bring it to his Father; * and in accordance with His own will * unite it to the heavenly powers * and thus, O Theotokos, save the world, ** Christ, Who is richly and abundantly merciful.`,tier:2,src:{file:`11-14A.pdf`,locus:`p2 LIC Both now, Dogmatic Theotokion`},type:`dogmatic_theotokion`,sourceLabel:`Both now ..., Dogmatic Theotokion, in Tone IV`,tone:4},entrance_rubric:{text:`Entrance. Prokeimenon of the day. Three lessons:`,tier:1,src:{file:`11-14A.pdf`,locus:`p2 Entrance`}},readings:[{heading:`A READING FROM PROVERBS`,src:{file:`11-14A.pdf`,locus:`p2 Lesson 1`},citation:{book:`Proverbs`,chapter:10,verses:`10:7, 3:13-16, 8:6`},citation_basis:`identified`,provenance_note:`No reference printed. The body opens "The memory of the just is praised" (Proverbs 10:7) and moves to "Blessed is the man who hath found wisdom" (3:13-16), then the Wisdom-speech of chapter 8: the composite hierarch lesson general.Heirarch.vespers.readings[0] identifies and Heirarchs.pdf prints as "(3, 13-16; 8, 6)". The body here runs on past 8:6. Identified by correspondence; confirm the span against the page.`},{heading:`A READING FROM PROVERBS`,src:{file:`11-14A.pdf`,locus:`p3 Lesson 2`},citation:{book:`Proverbs`,chapter:10,verses:`10:31-32, 11:1-12`},citation_basis:`identified`,provenance_note:`No reference printed. Opens "The mouth of the righteous droppeth wisdom" (Proverbs 10:31), the lesson Heirarchs.pdf cites "(10, 31-32 ; 11, 1-10)". The body here continues two verses further, to "a sensible man is quiet" (11:12). Identified; confirm against the page.`},{heading:`READING FROM THE WISDOM OF SOLOMON.`,src:{file:`11-14A.pdf`,locus:`p3 Lesson 3`},citation:{book:`Wisdom of Solomon`,chapter:4,verses:`4:1, 6:11-12, 17-21`},citation_basis:`identified`,provenance_note:`Heading prints no article and a full stop: "READING FROM THE WISDOM OF SOLOMON." No reference printed. Opens "When the righteous is praised", as general.Heirarch.vespers.readings[2]; composite, and it runs on into the "Let us oppress the righteous man" material of Wisdom 2. Identified by correspondence only; the span is NOT settled. Confirm against the page.`}],aposticha_rubric:{text:`On the Aposticha, in Tone V:`,tier:1,src:{file:`11-14A.pdf`,locus:`p4 Aposticha rubric`}},aposticha:[{text:`Rejoice, O father, thou beacon of Orthodoxy, radiant sun of the Church, boast of monastics and standard of the Church, excellent teacher of goodly works, holy hierarch Gregory, abode of wisdom and understanding, instrument of the Spirit for those near and far away, inspired composer of hymnody, mouth of the Lord, who led the worthy away from unworthiness! Entreat Christ, that He send down upon our souls peace and great mercy.`,tier:1,src:{file:`11-14A.pdf`,locus:`p4 Aposticha 1`},label:`plain`,tone:5,spec_mel:`Rejoice ...`},{text:`Precious in the sight of the Lord * is the death of His saints.`,tier:2,src:{file:`11-14A.pdf`,locus:`p4 Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Rejoice, O Gregory, thou exalted intelligence, beholder of mysteries, vessel of the Spirit bestowed upon us, radiant lamp, splendor of divine effulgence, mighty and honorable abode of love, who art truly meek, simple and guileless, revelation and manifestation of the Scriptures, sea of divine understandings, unfathomable abyss of the teaching of the Word of God! Entreat Christ, that He send down upon our souls peace and great mercy.`,tier:1,src:{file:`11-14A.pdf`,locus:`p4 Aposticha 2`},label:`plain`,spec_mel:`Rejoice ...`},{text:`Blessed is the man that feareth the Lord; * in His commandments shall he greatly delight.`,tier:2,src:{file:`11-14A.pdf`,locus:`p4 Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Rejoice, O holy hierarch Gregory, thou abyss of theology, steadfast rule of Orthodoxy for exalting the one exalted essence of the Trinity in a single will and activity, the simple, omnipotent and uncreated Godhead, thou who by the timeless grace of the Spirit didst put to shame those who reject deification, O mouth of theologians, glory of the divine fathers who art numbered among them, beacon of the Church, who by thy supplications dost grant us great mercy!`,tier:1,src:{file:`11-14A.pdf`,locus:`p4 Aposticha 3`},label:`plain`,spec_mel:`Rejoice ...`}],aposticha_glory:{text:`Having set thy life aright in godly manner, O divinely revealed Gregory, thou didst adorn thine activity with vision; for having loved wisdom with divine desire, thou wast enriched with grace by the mouth of the Spirit, exuding the sweetness of thy words like honey from-the honeycomb, and ever gladdening the Church of Christ with divine understanding. Wherefore, dwelling in the heavens with the holy hierarchs, pray thou unceasingly for us who celebrate thy memory.`,tier:1,src:{file:`11-14A.pdf`,locus:`p5 Aposticha Glory`},sourceLabel:`Glory ..., in Tone IV`,tone:4},aposticha_closer:{text:`Mercifully regard the supplications of thy servants, * O all-immaculate one, * quelling the cruel uprisings of the demons against us, * delivering us from every sorrow; * for thee alone do we have as a steadfast and sure confirmation, * and having acquired thine intercession; * let not us who call upon thee be put to shame, * O Lady. * Hasten thou to answer the entreaties of those who cry out to thee with faith: * Rejoice, thou help, joy and protection of all, ** and the salvation of our souls!`,tier:2,src:{file:`11-14A.pdf`,locus:`p5 Aposticha Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion, in Tone IV`,tone:4},troparion_rubric:{text:`At the blessing of the Loaves, the Troparion of the holy hierarch, in Tone VIII:`,tier:1,src:{file:`11-14A.pdf`,locus:`p5 Blessing of the Loaves rubric`}},virgin_theotokos_rubric:{text:`And “Virgin Theotokos, rejoice ...,” (Once).`,tier:1,src:{file:`11-14A.pdf`,locus:`p5 Virgin Theotokos rejoice rubric`}},no_vigil_rubric:{text:`But if a vigil is not served, then after the Troparion:`,tier:1,src:{file:`11-14A.pdf`,locus:`p5 If a vigil is not served`}},troparion_closer:{text:`O good One, Who for our sake wast born of the Virgin * and, having endured crucifixion, cast down death by death, * and as God revealed the Resurrection: * disdain not that which Thou hast fashioned with Thine own hand. * Show forth Thy love for mankind, O merciful One; * Accept the supplications of the Theotokos who bore Thee, ** and save Thy despairing people, O our Savior!`,tier:2,src:{file:`11-14A.pdf`,locus:`p5 Dismissal Theotokion (no vigil)`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion, in the same tone`},closing_rubric:{text:`The dismissal.`,tier:1,src:{file:`11-14A.pdf`,locus:`p5 The dismissal`}}},matins:{order:`god_is_lord_rubric.troparion.troparion_closer.sessional_1.sessional_2.megalynarion_rubric.megalynarion.megalynarion_verse_rubric.megalynarion_verse.megalynarion_closing_rubric.sessional_polyeleos.anabathmoi_rubric.prokeimenon.prokeimenon_verse.gospel_rubric.gospel.psalm50_sticheron.canon_rubric.canons.sessional_ode3.kontakion.ikos.exapostilarion.exapostilarion_closer.aposticha_rubric.aposticha.aposticha_glory.aposticha_closer.closing_rubric`.split(`.`),god_is_lord_rubric:{text:`On “God is the Lord ...,” the Troparion of the holy hierarch, in Tone VIII:`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 God is the Lord rubric`}},troparion_closer:{text:`O good One, Who for our sake wast born of the Virgin * and, having endured crucifixion, cast down death by death, * and as God revealed the Resurrection: * disdain not that which Thou hast fashioned with Thine own hand. * Show forth Thy love for mankind, O merciful One; * Accept the supplications of the Theotokos who bore Thee, ** and save Thy despairing people, O our Savior!`,tier:2,src:{file:`11-14A.pdf`,locus:`p6 God is the Lord Theotokion`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion`},sessional_1:[{text:`Let us hymn the great Gregory, the godly hierarch of Christ, the pillar of fire and cloud of light who in the Spirit goeth before the new Israel by day and leadeth them to the noetic land of peace, to the city of the firstborn in Christ.`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Sessional 1`},label:`plain`,sourceLabel:`After the 1st chanting of the Psalter, the Sessional hymn, in Tone I`,spec_mel:`Thy tomb, O Savior ...`,tone:1},{text:`All the fullness of the Godhead dwelt within thee, O pure Lady, and, as Paul hath said, deified all the nature of corruptible mankind. Thou wast the beginning of such grace, and art the saving guidance of those who honor thee with faith and love.`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Sessional 1 Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone I`,tone:1}],sessional_2:[{text:`Having cleansed thy spirit well with torrents of thy tears, thou didst noetically receive divine grace, O right wondrous one. And in a manner transcending nature was deemed worthy to participate in the divinity of the Word Whom thou didst preach as one and uncreated, O divinely wise Gregory.`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Sessional 2`},label:`plain`,sourceLabel:`After the 2nd chanting of the Psalter, Sessional hymn, in the same melody`},{text:`O most splendid vessel of the noetic Light, dispel the darkness of my heart and ease the most burdensome yoke of the passions, I pray, guiding me to the paths of repentance, and vouchsafing me the light which is to come, O all-blessed Lady.`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Sessional 2 Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone I`,tone:1}],megalynarion_rubric:{text:`Polyeleos, and this magnification:`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 magnification rubric`}},megalynarion:{text:`We magnify thee, O holy hierarch Gregory, and we rumor thy holy memory; for thou dost entreat Christ God on our behalf.`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Magnification`},label_inline:!0},megalynarion_verse_rubric:{text:`Selected Psalm verse:`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Selected Psalm verse rubric`}},megalynarion_verse:{text:`Hear this, all ye nations; give ear, all ye that inhabit the world.`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 Selected Psalm verse`},label:`refrain`,sourceLabel:`A`,label_inline:!0},megalynarion_closing_rubric:{text:`Glory ..., Both now ..., Alleluia ..., Glory to Thee, O God. (Thrice)`,tier:1,src:{file:`11-14A.pdf`,locus:`p6 after the selected verses`}},sessional_polyeleos:[{text:`Forsaking transitory things - the royal court, thy friends and kinsmen, O most wise father Gregory, thou didst acquire those things which are abiding and constant, O blessed one; and brought all thy household and kin to the Master of all as an honorable whole burnt offering; and guided thus thou didst dedicate thy soul, mind and body to God. O Gregory, earnestly pray to Him with vision and activity, that He grant remission of offenses unto those who with love celebrate thy holy memory.`,tier:1,src:{file:`11-14A.pdf`,locus:`p7 Polyeleos sessional`},label:`plain`,sourceLabel:`After the Polyeleos, the Sessional hymn, in Tone VIII`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`Having put on thy flesh, in that He is good, O Lady, the Master deified the servant's guise which He had assumed, and, uniting Himself to its substance and filling all of its nature with the Spirit, He made the assemblies of the saints by grace. Wherefore, we cry out to thee, accepting thee, who wast filled with the Spirit, as the first cause of ineffable works, and we hymn thee with all our soul: Rejoice, O beginning of our salvation! Rejoice, O release from offenses for those who with faith worship thine Offspring!`,tier:1,src:{file:`11-14A.pdf`,locus:`p7 Polyeleos sessional Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone VIII`,tone:8}],anabathmoi_rubric:{text:`Song of ascents, the first antiphon of Tone IV:`,tier:1,src:{file:`11-14A.pdf`,locus:`p7 Song of ascents rubric`}},prokeimenon:{text:`Precious in the sight of the Lord * is the death of His saints.`,tier:2,src:{file:`11-14A.pdf`,locus:`p7 Prokeimenon`},sourceLabel:`Prokeimenon, in Tone IV`,label_inline:!0,tone:4},prokeimenon_verse:{text:`What shall I render unto the Lord for all that He hath rendered unto me?`,tier:1,src:{file:`11-14A.pdf`,locus:`p7 Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel_rubric:{text:`Let every breath praise the Lord.`,tier:1,src:{file:`11-14A.pdf`,locus:`p7 Let every breath`}},gospel:{heading:`GOSPEL ACCORDING TO JOHN,`,src:{file:`11-14A.pdf`,locus:`p7 Matins Gospel`},citation_verbatim:`§ 35(JN. 9: 39-10: 9)`,citation:{book:`John`,chapter:9,verses:`9:39-10:9`,pericope_number:35},citation_basis:`printed`},psalm50_sticheron:{text:`With hymns of praise let us honor the preacher of true piety, the most radiant star of the Church, the splendid luminary of Thessalonica, the disciple of the Light and friend of Christ, who soweth the divine word of piety in the hearts of all the faithful, who granteth salvation unto all and prayeth earnestly unto the Lord, that our souls find mercy.`,tier:1,src:{file:`11-14A.pdf`,locus:`p7 After Psalm 50 sticheron`},sourceLabel:`After Psalm 50, this Sticheron, in Tone VI`,tone:6},canon_rubric:{text:`Canon of supplication to the Theotokos, with 6 Troparia, including the Irmos; and that of the holy hierarch, the composition of Patriarch Philotheus, in Tone I:`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Canon rubric`}},canons:[{title:`Canon of supplication to the Theotokos, with 6 Troparia, including the Irmos; and that of the holy hierarch, the composition of Patriarch Philotheus, in Tone I:`,composer:`Patriarch Philotheus`,tone:1,odes:{1:{irmos:{text:`Thy victorious right arm, * in a manner befitting God, * hath been glorified in strength, O Immortal One; * for in its infinite strength it shattered the enemy, * fashioning anew a path for the Israelites through the deep.`,tier:2,src:{file:`11-14A.pdf`,locus:`p8 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having set thy mouth and mind on the Wellspring of gifts and spiritual wisdom, O most glorious one, thou wast revealed to be an abyss of grace. Grant thou a drop thereof unto me who hymn thee, O father.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 1 troparion 1`},label:`plain`},{text:`Thou wast beyond nature a rule and law for monastic life, the divine mouth of theologians, holy hierarchs and teachers; wherefore, assembling together, we weave hymnody for thee.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 1 troparion 2`},label:`plain`},{text:`Thou wast revealed to be another Jeremiah, from his mother's womb, known to be wholly inclined toward the Creator, wholly sanctified, O God-bearer; wherefore, thy mouth received the words of God.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 1 troparion 3`},label:`plain`},{text:`Standing before the throne of God with the angels, O God-seer Gregory, thou dost now manifestly receive the unapproachable radiance. Pray that we may be released from the darkness of sin, we beseech thee.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 1 troparion 4`},label:`plain`},{text:`Desiring to behold the Light Who shone forth from thy womb, O Birthgiver of God, Gregory set thee before the Creator as his advocate, and through thee hath received the grace he desired.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`Thou alone knowest the weakness of human nature * and in compassion hast assumed its form; * do Thou gird me with power from on high, * that I may cry unto Thee: * Holy is the animate temple of Thine ineffable glory, O Lover of mankind!`,tier:2,src:{file:`11-14A.pdf`,locus:`p8 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou didst consider worldly wisdom to be foolishness, O most wise one, and didst love the foolishness of the Cross; and taking it upon thy shoulder, thou didst show, as Paul said, that by foolishness the wisdom of this world is overcome.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 3 troparion 1`},label:`plain`},{text:`Fleeing men, O father, with all thy soul thou didst love poverty, humility, want and un-acquisitiveness; wherefore, thou wast driven into the wilderness, and ever, in the fragrance of thy peace, thou didst cry out unto Christ: I hasten after Thee!`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 3 troparion 2`},label:`plain`},{text:`With all manner of ascetic feats and weeping thou didst mortify the old, corruptible man, O most wise one, cleansing thyself thoroughly with fountains of tears; and by thy manner of life receiving again thine ancient beauty in Christ, and clothing thyself in the new man.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 3 troparion 3`},label:`plain`},{text:`O ye multitudes of monks, together with those standing here today, all ye priests and benefactors, with beauteous voices and divine words let us praise Gregory, our common teacher, who hath adorned us with his works and discourses.`,tier:1,src:{file:`11-14A.pdf`,locus:`p8 Ode 3 troparion 4`},label:`plain`},{text:`Having through the intercession of the Mother of God beheld the radiance of the Spirit which thou desired, thou art now thereby more brilliantly illumined. Pray thou that the darkness of the passions within us may be replaced with the light of grace.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Perceiving thee with prophetic eyes * as the mountain overshadowed by the grace of God, * Habbakuk proclaimed that the Holy One of Israel * would come forth from thee, * for our salvation and restoration.`,tier:2,src:{file:`11-14A.pdf`,locus:`p9 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having wounded the moonless night and darkness of the passions with the staff of prayer, as Moses did to Egypt, thou didst hasten supra-naturally to divine vision, and became for us a law-giver.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode 4 troparion 1`},label:`plain`},{text:`Having ascended the divine heights of the virtues, as the friends and disciples of Christ on Tabor, O father Gregory, thou didst behold Him revealing His natural and divine glory; and, deified, thou wast shown to be like another sun.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode 4 troparion 2`},label:`plain`},{text:`O God-seer Gregory, having become an initiate of the mysteries of the Godhead and a partaker of ineffable things, thou dost articulate the mystery of theology, declaring God to be One and uncreated in power and nature, and composed of three Hypostases.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode 4 troparion 3`},label:`plain`},{text:`With sacred discourses thou didst hymn her who gave birth to the ineffable Word of God and with splendor proclaimed the mystery of the incarnation. And the Church doth now beg her to preserve it un-beset by storms.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Hou hast shone upon us with the radiance * of Thy coming O Christ, * and illumined the ends of the world with Thy Cross, * enlighten with the light of thine understanding * the hearts of those who with right worship hymn Thee.`,tier:2,src:{file:`11-14A.pdf`,locus:`p10 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The great Mind, the ineffable Abyss of wisdom, found thee, O God-bearer, to be an abode of intelligence friendly toward Him; and He hath given thee to the Church as an instrument of understanding and wisdom.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 5 troparion 1`},label:`plain`},{text:`Shining thee forth as a brilliant ray first on Athos, O Gregory, God bestowed thee upon the splendid city, sanctifying and paternally setting thee forth through the divine activity of His light.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 5 troparion 2`},label:`plain`},{text:`Having found thee to be a divine gift from God and an inexhaustible treasure, the mighty capital of Thessaly calleth its neighbors to partake of thy words and miracles, O blessed one.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 5 troparion 3`},label:`plain`},{text:`O ye who desire Gregory's struggle and his words of grace, offering hymnody now unto him let us beseech him through whose prayer the Creator and Master is moved to mercy for all.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 5 troparion 4`},label:`plain`},{text:`He Who enlightened the vast expanse of the earth with the radiance of the sun hath been revealed to be a never-setting Sun amid the darkness, O Virgin. Him do thou entreat, that He deliver us from the darkness of evil and sin, O Lady.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`The sea monster spat forth Jonah as it had received him, * like a babe from the womb: * while the Word, having dwelt in the Virgin and taken flesh, * came forth from her yet kept her incorrupt. * For being Himself not subject to decay. * He preserved His Mother free from all harm.`,tier:2,src:{file:`11-14A.pdf`,locus:`p10 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O Gregory, thy deified life hath truly been seen by the faithful as a rule of virtue, thy discourse and precepts as a guide to piety, whereby they judge their own fruitfulness or barrenness, proclaiming the one almighty and uncreated God.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 6 troparion 1`},label:`plain`},{text:`Thou hast been shown to us as great, O Gregory, piously preaching the one Godhead in three Hypostases but a single Essence and power, in all ways simple and uncreated; and thou didst mightily put to shame all who foolishly say that the Godhead is created.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 6 troparion 2`},label:`plain`},{text:`Thou dost denounce the thought of the mindless Acindynus, as thou didst that of Barlaam before; for, enamored of the myths of the ancient Greeks, they made the Godhead into a creature, and like the Jews dishonored the dignity of the Son of God.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 6 troparion 3`},label:`plain`},{text:`Having produced rules of precepts and brilliant discourses, whereby thou didst open the minds of the honored theologians to the Spirit, O Gregory, by thy supplications preserve the Church of Christ unshaken, and deliver it from all heresy.`,tier:1,src:{file:`11-14A.pdf`,locus:`p10 Ode 6 troparion 4`},label:`plain`},{text:`Thou hast been shown to be more exalted than the throne of the cherubim and all the celestial hosts, and every rank of heaven, O Lady, for thou wast the ineffable throne of the divine Being of God. In that He is thy Son, move Him to have mercy on me who hymn thee with faith.`,tier:1,src:{file:`11-14A.pdf`,locus:`p11 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`We the faithful perceive thee, O Theotokos, * to be a noetic furnace; * for as He, the supremely exalted One, * saved the three children, * so hath He wholly refashioned fallen humanity, in thy womb, * O Thou praised and supremely glorified God of our fathers.`,tier:2,src:{file:`11-14A.pdf`,locus:`p11 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Those held captive by deception are unable to gaze directly upon the bright lightning of thy precepts and divine and awesome words, for these are like the voice of thunder, O father, and like blind men the mindless ones, wandering about, now sense them to be walls, as it is written.`,tier:1,src:{file:`11-14A.pdf`,locus:`p11 Ode 7 troparion 1`},label:`plain`},{text:`Night is void of light for the disobedient; but now the one Light hath dawned, the kingdom of the glory of God, which the Lover of mankind revealed on Tabor to the initiates of His mysteries, O Gregory. And having partaken sufficiently thereof, thou dost now join in fellowship with those who have pleased God.`,tier:1,src:{file:`11-14A.pdf`,locus:`p11 Ode 7 troparion 2`},label:`plain`},{text:`Having put to shame those who impiously blaspheme against grace, divine inner stillness and prayer, and who vilely mock ineffable deification, thou didst drive them far from the divine fold, which thou dost ever preserve by thine entreaties.`,tier:1,src:{file:`11-14A.pdf`,locus:`p11 Ode 7 troparion 3`},label:`plain`},{text:`Come thou now unto our aid, O Lady, our common salvation, accepting the supplications of Gregory, lulling to sleep the passions of our souls and bodies, and speedily releasing us from general tumult and corruption.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`In the furnace as in a fiery smelter * the Israelite children shone more brightly than gold * with the beauty of godliness, * as they exclaimed: Bless the Lord all ye works of the Lord, * hymn and supremely exalt Him throughout all ages.`,tier:2,src:{file:`11-14A.pdf`,locus:`p12 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O father, thou hast been shown to be wholly radiant, sweet, upright, and meek, pouring forth for those who approach thee with faith the sweet and divine beverage of thy discourses, which gladdeneth the hearts of all the pious, giving drink to the senses of the souls of the infirm.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 8 troparion 1`},label:`plain`},{text:`Finding thy mind and tongue to be truly noble, and thine instruction, words and heart purified, the Wisdom of God made His abode within thee, O father, which having became united, revealed thee to be wondrous to all the world.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 8 troparion 2`},label:`plain`},{text:`The might of piety showed forth the Hebrew children as unharmed in the furnace, O most wise one; and emulating them, thou didst restrain the flame of impiety in the midst of the furnace of temptations, valiantly hymning the Master and utterly consuming those who persecuted thee.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 8 troparion 3`},label:`plain`},{text:`Thou didst drown the noetic Pharaoh in the torrents of thy tears and engulfed the whole noetic army of Egypt; ascending the mountain of dispassion, and driving from there the hordes of the enemy by the power of the Spirit, as did Moses the great.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 8 troparion 4`},label:`plain`},{text:`The splendid preacher of grace, the theologian of the Spirit given through thee to the world, O pure Theotokos, celebrating now with discourses, as a faithful servant assembleth all choirs to chant hymns and songs unto thee, glorifying thy memory.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`The Bush, which burnt without being consumed, * prefigured thy pure birthgiving, O Theotokos. * Wherefore we now entreat Thee: * quench the raging furnace of temptations that beset us, * that we may unceasingly magnify Thee.`,tier:2,src:{file:`11-14A.pdf`,locus:`p12 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Standing before the throne of the beginningless and three-Sunned Godhead, and filled to sufficiency through spiritual activity with the grace which thou didst hymn, as a fellow laborer be thou mindful of thy friends, who now commemorate thee.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 9 troparion 1`},label:`plain`},{text:`Thou didst find the reward for thine efforts, O father - the beginingless kingdom of God - which thou didst piously preach on earth; and thou didst receive the three-stranded wreath of divine confession, priesthood and inner stillness.`,tier:1,src:{file:`11-14A.pdf`,locus:`p12 Ode 9 troparion 2`},label:`plain`},{text:`Thou hast been revealed to be the boast of monastics, a godly theologian and a renowned standard for the priesthood; wherefore, divine grace hath bestowed miracles upon thee, confirming thy words.`,tier:1,src:{file:`11-14A.pdf`,locus:`p13 Ode 9 troparion 3`},label:`plain`},{text:`Having departed O most glorious one, thou hast left behind the laws of praise and the struggle of thy discourses, both while living on earth and after departing the body, yet do thou most especially accept this meager hymnody, and by thy supplications grant the petitions of those who desire thee.`,tier:1,src:{file:`11-14A.pdf`,locus:`p13 Ode 9 troparion 4`},label:`plain`},{text:`Thine honored servant Gregory was the tongue of theology, for the word of thy dread Offspring, the Deity Who appeared for our sake and took flesh from thee, was well-pleased to make His abode in him.`,tier:1,src:{file:`11-14A.pdf`,locus:`p13 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`By abstinence, weeping and prayer, by spiritual activity, poverty and thorough washing with tears, thou didst purify thy heart, O Gregory; and, wholly caught up, thou wast united to Christ in spirit. Wherefore, like Paul, having heard ineffable things and become a chosen vessel, thou didst bear the name of Christ, and didst exaltedly preach the one, simple and uncreated Godhead, to Whom do thou never cease to pray, that thy flock may be saved.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode III sessional`},label:`plain`,sourceLabel:`Sessional Hymn of the holy hierarch, in Tone VIII`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`O compassionate Word of God, Who in the beginning brought the things of nature into being out of non-existence, and Who by Thy hand honored with thine image mankind who corrupted it through the deception of the serpent, but Thou didst set it aright by Thy precious Cross, and by assuming the flesh sanctifying all nature by Thy Holy Spirit. O Master Christ our God, through the supplications of Thy Mother, grant remission of offenses unto those who with faith worship Thy might.`,tier:1,src:{file:`11-14A.pdf`,locus:`p9 Ode III sessional Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone VIII`,tone:8}],exapostilarion:{text:`Rejoice, glory of the fathers, voice of theologians, tabernacle of inward stillness, dwelling-place of wisdom, greatest of teachers, deep ocean of the Word. Rejoice, thou who hast practiced virtues of the active life and ascended to the heights of contemplation; Rejoice, healer of man’s sickness. Rejoice, shrine of the Spirit; Rejoice, father who though dead art still alive.`,tier:1,src:{file:`11-14A.pdf`,locus:`p13 Exapostilarion`},label:`plain`,sourceLabel:`Exapostilarion of the holy hierarch`,spec_mel:`With the disciples ...`},exapostilarion_closer:{text:`O Lady, Queen of all and above all, higher than all the heavenly hosts, stretch out thy regal hand and preserve the world; bless the priests that liturgize in thine honor and forgive those monastics who entreat thy prayers. Grant peace to all people who dwell in thy courts. Strengthen those in war during the time of battle. Protect this thy holy city. Deem us worthy to see the heavenly Kingdom and the gates of Paradise, when at the Second Coming the Judge shall sit on His dread throne to judge all the earth, O Queen of the angels.`,tier:1,src:{file:`11-14A.pdf`,locus:`p13 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion`},aposticha_rubric:{text:`On the Aposticha, 4 Stichera of the holy hierarch, in Tone I:`,tier:1,src:{file:`11-14A.pdf`,locus:`p13 Matins Aposticha rubric`}},aposticha:[{text:`In the world thou hast lived a life of blessedness, * and now in heaven thou dost rejoice in the assembly of the blessed; * because thou wast meek, thou dwellest in the land * that the meek inherit, O Bishop Gregory. * God has made thee rich in the grace of working miracles, ** which thou dost bestow on those who honor thee.`,tier:2,src:{file:`11-14A.pdf`,locus:`p13 Matins Aposticha 1`},label:`plain`,tone:1,repeat:2,spec_mel:`Joy of the heavenly hosts ...`},{text:`O blessed saint, thou hast planted the dogmas of Orthodoxy * and cut down the thorns of heresy. * With thy words thou hast watered the seed of the Faith, * making it grow, * and as an active husbandman thou hast brought to God ** ears of wheat increased an hundredfold.`,tier:2,src:{file:`11-14A.pdf`,locus:`p13 Matins Aposticha 2`},label:`plain`,spec_mel:`Joy of the heavenly hosts ...`},{text:`The glory of thy blameless life, O blessed saint, * amazed both angels and mankind. * With steadfast purpose thou hast labored in the ascetic life, * and shown thyself to be a worthy hierarch * and minister of God, ** and His true friend.`,tier:2,src:{file:`11-14A.pdf`,locus:`p14 Matins Aposticha 3`},label:`plain`,spec_mel:`Joy of the heavenly hosts ...`}],aposticha_glory:{text:`Having adorned thy discourse with wisdom and blameless virtue, O most wise Gregory, in both thou wast wholly beautiful, noetically adorning and gladdening the people with thy God proclaiming words, extending to them the(doctrine of the) one Godhead of the Trinity; where· fore, having trampled alien heresy underfoot with Thine exceedingly glorious teachings, thou didst raise up the might of the Faith in the end. Standing before Christ with His immaterial ministers, ask thou peace and great mercy for our souls.`,tier:1,src:{file:`11-14A.pdf`,locus:`p14 Matins Aposticha Glory`},sourceLabel:`Glory ..., in Tone IV`,tone:4},aposticha_closer:{text:`The Son and Word of God, begotten of the Father before the ages without a mother, hast thou borne in these later days, incarnate of thy pure blood, without the aid of a man. Him do thou entreat O Birthgiver of God, that we be granted the remission of sins before the end.`,tier:1,src:{file:`11-14A.pdf`,locus:`p14 Matins Aposticha Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion, in Tone IV`,tone:4},closing_rubric:{text:`Great Doxology, Troparion, Litanies, and the Dismissal. First Hour`,tier:1,src:{file:`11-14A.pdf`,locus:`p14 Matins closing rubric`}}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`troparion`,`kontakion`,`prokeimenon`,`prokeimenon_verse`,`epistle`,`alleluia`,`alleluia_verse`,`gospel`,`communion_verse`],beatitudes_rubric:{text:`On the Beatitudes, 8 Troparia: 4 from ODE III and 4 from ODE VI of the canon of the holy hierarch.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitudes rubric`}},beatitudes:[{text:`Thou didst consider worldly wisdom to be foolishness, O most wise one, and didst love the foolishness of the Cross; and taking it upon thy shoulder, thou didst show, as Paul said, that by foolishness the wisdom of this world is overcome.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 1`},label:`plain`},{text:`Fleeing men, O father, with all thy soul thou didst love poverty, humility, want and un-acquisitiveness; wherefore, thou wast driven into the wilderness, and ever, in the fragrance of thy peace, thou didst cry out unto Christ: I hasten after Thee!`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 2`},label:`plain`},{text:`With all manner of ascetic feats and weeping thou didst mortify the old, corruptible man, O most wise one, cleansing thyself thoroughly with fountains of tears; and by thy manner of life receiving again thine ancient beauty in Christ, and clothing thyself in the new man.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 3`},label:`plain`},{text:`O ye multitudes of monks, together with those standing here today, all ye priests and benefactors, with beauteous voices and divine words let us praise Gregory, our common teacher, who hath adorned us with his works and discourses.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 4`},label:`plain`},{text:`O Gregory, thy deified life hath truly been seen by the faithful as a rule of virtue, thy discourse and precepts as a guide to piety, whereby they judge their own fruitfulness or barrenness, proclaiming the one almighty and uncreated God.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 5`},label:`plain`},{text:`Thou hast been shown to us as great, O Gregory, piously preaching the one Godhead in three Hypostases but a single Essence and power, in all ways simple and uncreated; and thou didst mightily put to shame all who foolishly say that the Godhead is created.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 6`},label:`plain`},{text:`Thou dost denounce the thought of the mindless Acindynus, as thou didst that of Barlaam before; for, enamored of the myths of the ancient Greeks, they made the Godhead into a creature, and like the Jews dishonored the dignity of the Son of God.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 7`},label:`plain`},{text:`Thou hast been shown to be more exalted than the throne of the cherubim and all the celestial hosts, and every rank of heaven, O Lady, for thou wast the ineffable throne of the divine Being of God. In that He is thy Son, move Him to have mercy on me who hymn thee with faith.`,tier:1,src:{file:`11-14A.pdf`,locus:`p15 Beatitude 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}],prokeimenon:{text:`My mouth shall speak wisdom, * and the meditation of my heart shall be of understanding.`,tier:2,src:{file:`11-14A.pdf`,locus:`p16 Liturgy Prokeimenon`},sourceLabel:`Prokeimenon, in Tone I`,label_inline:!0,tone:1},prokeimenon_verse:{text:`Hear this, all ye nations; give ear, all ye that inhabit the world.`,tier:1,src:{file:`11-14A.pdf`,locus:`p16 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle:{heading:`THE FIRST EPISTLE TO THE CORINTHIANS`,src:{file:`11-14A.pdf`,locus:`p16 Epistle`},citation_verbatim:`§151(12: 7-11)`,citation:{book:`1 Corinthians`,chapter:12,verses:`7-11`,pericope_number:151},citation_basis:`printed`},alleluia:{text:`The mouth of the righteous shall meditate wisdom, and his tongue shall speak of judgment.`,tier:1,src:{file:`11-14A.pdf`,locus:`p16 Alleluia`},sourceLabel:`Alleluia, in Tone II`,label_inline:!0,tone:2},alleluia_verse:{text:`The law of his God is in his heart, and his steps shall not be tripped.`,tier:1,src:{file:`11-14A.pdf`,locus:`p16 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel:{heading:`GOSPEL ACCORDING TO ST. JOHN`,src:{file:`11-14A.pdf`,locus:`p16 Gospel`},citation_verbatim:`§36(10:9-16)`,citation:{book:`John`,chapter:10,verses:`9-16`,pericope_number:36},citation_basis:`printed`},communion_verse:{text:`In everlasting remembrance shall the righteous be; he shall not be afraid of evil tidings.`,tier:1,src:{file:`11-14A.pdf`,locus:`p16 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}}}]},"11-15":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`saint`,title:{text:`COMMEMORATION OF THE HOLY MARTYRS; GURIAS, SAMONAS & ABIBUS`,tier:1,src:{file:`11-15.pdf`,locus:`p1 title`},sourceLabel:`THE 15th DAY OF THE MONTH OF NOVEMBER`},preface_rubric:{text:`Be it known: if this, the first day of the Nativity Fast, fall on a Saturday, on Friday evening, on “Lord, I have cried ...,” we chant 6 Stichera of the martyrs. But if it fall on Sunday, we chant first the seven Stichera from the Oktoechos, and three for the martyrs; then Glory ..., for the martyrs; Both now ..., Dogmaticon. On the Aposticha, Glory ..., of the martyrs; Both now ..., Theotokion. At vespers, and at matins On “God is the Lord ...,” we chant the Troparion of the martyrs; Glory ..., Both now ..., Theotokion. But on any other day, from Monday through Friday, we chant Alleluia instead of “God is the Lord ...” because of the beginning of the holy fast. On “Lord, I have cried ...,” we chant first three Stichera of the Theotokos and then three Stichera of the mar-tyrs; Glory ..., Both now ..., Theotokion, or Stavrotheotokion. Instead of the Prokeimenon, we chant Alleluia, in Tone VI. On the Aposticha: Glory ..., Both now ..., Theotokion, or Stavrotheotokion. At matins, instead of “God is the Lord ...,” we chant Alleluia and the Trinitarian hymns. After Ode VI, we chant the Kontakion of the martyrs.`,tier:1,src:{file:`11-15.pdf`,locus:`p1 Be it known`}},rank:`simple`,fekula_section:`2A`,oca_primary:!0,source_file:`11-15.pdf`,note:`Rank by the encoding_rule_v2.md 1.1 waterfall: 3 stichera of the martyrs at Lord I have cried, no Polyeleos, no Great Doxology appointed. The "Be it known" rubric makes the form of the service depend on the weekday (God is the Lord on Saturday and Sunday, Alleluia Monday through Friday); it is stored verbatim and every branch the page prints is captured. Nothing is printed at Matins before the canon, and no Praises or Matins aposticha are printed. Fekula ch. 5 has its own section for this date ("The 15th Day of the Month of November", p. 214) which is NOT in the delivered chapter text (open question Q-0004).`,troparion:{text:`O Christ God, Thou hast given us an impregnable rampart * in the miracles of Thy holy martyrs. * Through their supplications destroy Thou the councils of the heathen * and strengthen the scepters of kingdoms, ** in that Thou art good and the Lover of mankind.`,tier:2,src:{file:`11-15.pdf`,locus:`p3 Troparion of the holy martyrs`},verified_sites:[{locus:`p3 end of Vespers`,tone:5},{locus:`p9 AT LITURGY`,tone:5}],sourceLabel:`Troparion of the holy martyrs, in Tone V`,tone:5},kontakion:{text:`Having received grace from on high, * O all-praised martyrs, * ye intercede for those amid temptations; * wherefore, ye delivered the maiden from a bitter death, O holy ones: ** for ye are truly the glory of Edessa and the joy of the world.`,tier:2,src:{file:`11-15.pdf`,locus:`p6 Kontakion of the holy martyrs`},verified_sites:[{locus:`p6 after Ode VI`,tone:2},{locus:`p9 AT LITURGY`,tone:2}],sourceLabel:`Kontakion of the holy martyrs, in Tone II`,spec_mel:`Seeking the highest ...`,tone:2},ikos:{text:`Entreated by the supplications of Thy spiritual athletes, deliver me from bondage to the enemy, O Jesus, Bestower of life, that, acquiring a soul and body unenslaved by the passions, I may praise their speedy assistance: for they quickly delivered from death the maiden enclosed in a tomb by the wickedness of her husband, anticipating her need, and she cried: Ye are the glory of Edessa and the joy of the world!`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ikos`},sourceLabel:`Ikos`,label_inline:!0},vespers:{order:[`lic_rubric`,`lic`,`theotokos_stichera_rubric`,`theotokos_stichera`,`lic_closer`,`lic_stavrotheotokion`,`lic_glory_rubric`,`lic_glory`,`lic_glory_closer_rubric`,`aposticha_rubric`,`aposticha`,`aposticha_glory`,`aposticha_closer_rubric`,`troparion`],lic_rubric:{text:`On “Lord, I have cried ...,” 3 Stichera of the holy martyrs, in Tone IV:`,tier:1,src:{file:`11-15.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`The all-wise Abibus, * the wondrous Samonas * and the glorious Gurias, * the passion-bearers * who have formed a common choir for the faithful, * now join chorus with us in joy and are gladdened, * for it hath been granted by God * to the souls of the martyrs ** to noetically behold things that are taking place.`,tier:2,src:{file:`11-15.pdf`,locus:`p1 LIC 1`},label:`plain`,spec_mel:`Thou hast given a sign ...`,tone:4,provenance_note:`The Spec. Mel. line prints its opening quotation mark before the label: “Spec. Mel.: Thou hast given a sign ...”: (p1). The melody name is stored without it.`},{text:`Having endured pangs * and unbearable torments, * and suffered valiantly, * O ye who are equal in number to the Trinity, * the divinely wise Samonas, Abibus, and Gurias, * ye now enjoy eternal and beautiful delight, * Christ presenting to you the reward for your labors. * Him do ye fervently entreat, ** that our souls be saved.`,tier:2,src:{file:`11-15.pdf`,locus:`p1 LIC 2`},label:`plain`,spec_mel:`Thou hast given a sign ...`},{text:`Having put in at the calm haven, * life untroubled * and right tranquil serenity, * O blessed passion-bearing martyrs, * ye have now exchanged * that which is below * for an abiding sojourn in dispassion, * receiving honors from God, as is meet, ** as reward for your labors and pangs.`,tier:2,src:{file:`11-15.pdf`,locus:`p1 LIC 3`},label:`plain`,spec_mel:`Thou hast given a sign ...`}],theotokos_stichera_rubric:{text:`But if Alleluia is to be chanted at Matins instead of “God is the Lord ...,” we sing first the following Stichera of the Theotokos, in the same melody:`,tier:1,src:{file:`11-15.pdf`,locus:`p1 Stichera of the Theotokos rubric (Alleluia days)`}},theotokos_stichera:[{text:`Rain down upon me, O Lady, * the abyss of thy mercy, * and as thou art merciful, O maiden, * water thou my heart, * which is consumed by the heat of the passions, I pray, * and cause it to pour forth unceasingly * drops of compunction, * whereby, O pure one, I may be deemed worthy of consolation ** which those who shed tears of sincerity receive.`,tier:2,src:{file:`11-15.pdf`,locus:`p1 Sticheron of the Theotokos 1`},label:`plain`},{text:`O Lady, take pity upon me * who am shaken by the demons' assaults * and am thrust into the pit of perdition, * and establish me upon the rock of the virtues; * and, destroying the councils of the enemy, * grant that I may follow the precepts * of thy Son and our God, * that I may receive remission ** on the day of judgment.`,tier:2,src:{file:`11-15.pdf`,locus:`p2 Sticheron of the Theotokos 2`},label:`plain`},{text:`Wash away the defilement * of my wretched heart, * O all-hymned Theotokos; * cleanse my wounds and sores, * which are the result of sin, O pure one, * and calm the inconstancy of my heart, * that I, thy passion-plagued and useless servant, * may magnify thy power ** and thy great protection.`,tier:2,src:{file:`11-15.pdf`,locus:`p2 Sticheron of the Theotokos 3`},label:`plain`}],lic_closer:{text:`Transform into health and power, * the weakness and despondency of my soul * O all-immaculate Virgin Mother, * that with fear and love * I may work and do those things that are justified before Christ, * that I may escape the unbearable fire, * and, ever rejoicing, through thee may receive * the portion of heaven ** and life which passeth not away.`,tier:2,src:{file:`11-15.pdf`,locus:`p2 LIC Glory/Both now Theotokion`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion in Tone IV`,spec_mel:`As one valiant among the martyrs ...`,tone:4},lic_stavrotheotokion:{text:`The most pure one, * beholding Christ, the lover of mankind, crucified, * His side pierced by a lance, * cried out, lamenting: * “What is this, O my Son? * How have these thankless people rewarded Thee * for the good things Thou hast done for them? * Dost Thou hasten to leave me childless, O most Beloved? ** I marvel, O compassionate One, at Thy voluntary crucifixion!”`,tier:2,src:{file:`11-15.pdf`,locus:`p2 LIC Stavrotheotokion`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`,label_inline:!0},lic_glory_rubric:{text:`But if “God is the Lord ...” be chanted, we sing:`,tier:1,src:{file:`11-15.pdf`,locus:`p2 If God is the Lord be chanted`}},lic_glory:{text:`Edessa rejoiceth, for it hath been enriched by the shrine of the holy Gurias, Samonas and Abibus, and, summoning the Christ-loving flock, it crieth out: Come, ye who love the martyrs, and illumine yourselves on their splendid memorial! Come and rejoice, ye who love the feasts of the Church! Come and behold the heavenly luminaries who lived on earth! Come and hear what a bitter death the valiant and steadfast ones endured for the sake of everlasting life! Wherefore, as guarantors of the Truth, they saved the virgin cast alive into the grave, and committed to damnation, as a pitiless murderer, the vile one who reviled them. And they pray earnestly to the Holy Trinity, that those who with faith celebrate their memory be delivered from corruption and temptations, and from all manner of tribulations.`,tier:1,src:{file:`11-15.pdf`,locus:`p2 LIC Glory`},sourceLabel:`Glory ..., in Tone II`,tone:2},lic_glory_closer_rubric:{text:`Both now ..., Theotokion.`,tier:1,src:{file:`11-15.pdf`,locus:`p2 LIC Both now rubric`}},aposticha_rubric:{text:`On the Aposticha, the Stichera from the Oktoechos; and Glory ..., in Tone II:`,tier:1,src:{file:`11-15.pdf`,locus:`p2 Aposticha rubric`}},aposticha:{absent:!0,reason:`governed_by_octoechos`,basis:`close_reading`,note:`The rubric appoints "the Stichera from the Oktoechos"; none are printed here.`,book:`octoechos`},aposticha_glory:{text:`Come, all ye who love the martyrs, let us honor with hymns the warriors of Christ, Gurias, Samonas and Abibus, who most gloriously work miracles; for they refused not to respond to the oath of the maiden, but, fulfilling her petition, saved the virgin, wreaking vengeance upon the all-iniquitous Goth. Through their supplications, O Christ God, save us, in that Thou art good and the Lover of mankind.`,tier:1,src:{file:`11-15.pdf`,locus:`p2 Aposticha Glory`},sourceLabel:`Glory ..., in Tone II`,tone:2},aposticha_closer_rubric:{text:`Both now ..., Theotokion, or Stavrotheotokion.`,tier:1,src:{file:`11-15.pdf`,locus:`p2 Aposticha Both now rubric`}}},matins:{order:[`canon_rubric`,`canons`,`sessional_ode3`,`kontakion`,`ikos`,`exapostilarion`,`exapostilarion_closer`],canon_rubric:{text:`Both canons from the Oktoechos; and that of the martyrs, with 4 Troparia, the acrostic whereof is: “I praise the three who speak most wisely together”, the composition of Theophanes, in Tone IV:`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Canon rubric`}},canons:[{title:`Both canons from the Oktoechos; and that of the martyrs, with 4 Troparia, the acrostic whereof is: “I praise the three who speak most wisely together”, the composition of Theophanes, in Tone IV:`,composer:`Theophanes`,acrostic:`I praise the three who speak most wisely together`,tone:4,odes:{1:{irmos:{text:`Through the deep of the Red Sea, * marched dry shod Israel of old, * and by Moses’ outstretched hands, * raised in the form of a cross, * the power of Amalek was routed in the wilderness.`,tier:2,src:{file:`11-15.pdf`,locus:`p4 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Theologizing worshipfully concerning the lordship of the Trinity, O saints, ye easily destroyed the inconstant darkness of polytheism, shining forth like stars of great radiance from the East.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 1 troparion 1`},label:`plain`},{text:`O ye three confessors who are manifestly illumined by the grace of the ruling Trinity, showing forth your opposition with endurance ye destroyed the falsehood of polytheism.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 1 troparion 2`},label:`plain`},{text:`Making you sons by adoption through love, O glorious ones, He Who is the essential Son hath shown you forth as co-heirs to the inheritance now manifestly given Him, and sharers in His kingdom, in that He is compassionate.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 1 troparion 3`},label:`plain`},{text:`Thou wast the tabernacle of the most wise Wisdom, O all-immaculate one; for it was His good pleasure to make for Himself a temple of thy most pure blood, O pure one, for the salvation of our souls.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`Thy Church, O Christ, rejoiceth in Thee crying aloud: * Thou, O Lord, art my strength, * my refuge and foundation.`,tier:2,src:{file:`11-15.pdf`,locus:`p4 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The confessors and favorites of Christ willingly gave their bodies over to tortures and cruel wounds.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 3 troparion 1`},label:`plain`},{text:`O holy ones, pray ye that those who celebrate your memory with faith may be delivered from evil thoughts of sin.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 3 troparion 2`},label:`plain`},{text:`Suspended upon a tree, with endurance the honored witnesses most piously preserved inviolate their confession.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`He Who entered into thy womb hath shown thee to be a well-spring of healings, O most pure Mother of God; wherefore, heal thou my soul.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Beholding Thee, the Sun of righteousness, * lifted up upon the Cross, * the Church now standeth arrayed and doth worthily cry aloud: * Glory be to Thy power, O Lord!`,tier:2,src:{file:`11-15.pdf`,locus:`p5 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The crowned ones, equal in number to the Trinity, illumined with thrice-radiant light those who now celebrate their most sacred memory, granting healing unto them all.`,tier:1,src:{file:`11-15.pdf`,locus:`p5 Ode 4 troparion 1`},label:`plain`},{text:`O ye divinely wise, let us hasten with reverence to the radiant and splendid shrine of the martyrs; for it poureth forth healings upon those who cry out with faith: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-15.pdf`,locus:`p5 Ode 4 troparion 2`},label:`plain`},{text:`Confessing the divine dispensation and the mystery which transcendeth understanding, with tongues of theology, the godly and all-wise confessors trampled underfoot all the ungodliness of the tyrants.`,tier:1,src:{file:`11-15.pdf`,locus:`p5 Ode 4 troparion 3`},label:`plain`},{text:`In a manner transcending understanding, O Virgin, thou wast shown to be a virgin even after giving birth. Wherefore, with unwavering faith, O Lady, we unceasingly cry out: Rejoice!`,tier:1,src:{file:`11-15.pdf`,locus:`p5 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`Thou, O Lord, who camest into the world, * art my light, * a holy Light turning from the darkness of ignorance * those who sing Thy praises in faith.`,tier:2,src:{file:`11-15.pdf`,locus:`p6 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Shining manifestly with the radiance of their struggles, the champions of the Faith put to shame the savage character of the tyrants.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 5 troparion 1`},label:`plain`},{text:`The miracles of the martyrs have been manifestly proclaimed unto all the ends of the world, and have made all steadfast through faith.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 5 troparion 2`},label:`plain`},{text:`Receiving the seed of grace like good earth, the blessed ones industriously produced riches by their manner of life.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 5 troparion 3`},label:`plain`},{text:`He Who alone is good, Who sustaineth all things by the depths of His goodness, O Mother of God, deigned to be held in thine arms.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`The Church crieth out unto Thee O Lord, * ‘I will sacrifice unto Thee with a voice of praise * having been cleansed of the blood of the demons' * by the blood that for mercy's sake flowed from Thy side.`,tier:2,src:{file:`11-15.pdf`,locus:`p6 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having withstood all torments lawfully and manifestly preserved the faith, as valiant warriors, O divinely wise ones, ye have received crowns of divine righteousness.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 6 troparion 1`},label:`plain`},{text:`Of old Habbakuk was lifted up on high at the command of God; and through you, O divinely eloquent ones, the tortured maiden was returned to her mother.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 6 troparion 2`},label:`plain`},{text:`The shrine of the martyrs shineth with miracles and poureth forth rivers of healing upon all who approach it with faith and marvel at their endurance.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 6 troparion 3`},label:`plain`},{text:`Finding thee alone among the thorns as a most pure rose and a lily of the valley, O Mother of God, the noetic Bridegroom made His abode within thee.`,tier:1,src:{file:`11-15.pdf`,locus:`p6 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`In the Persian furnace the youths and descendants of Abraham, * burning with a love of piety * rather than by a flame of fire, * cried aloud saying: * Blessed art Thou in the temple of Thy glory, O Lord.`,tier:2,src:{file:`11-15.pdf`,locus:`p6 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`He Who delivered the children of Abraham in the furnace hath now also saved the foreign maiden from cruel peril by the mediation of His holy favorites, in that He is compassionate.`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 7 troparion 1`},label:`plain`},{text:`O Word, Wisdom and Power of God, the infamous murderer who inflicted torment of most savage inhumanity was straightway tried for all his evils by Thy righteous judgment.`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 7 troparion 2`},label:`plain`},{text:`Strengthened by her trust in you, O glorious ones, the maiden who had been enclosed with the dead in a tomb was not mistaken in her hope, crying: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 7 troparion 3`},label:`plain`},{text:`Like a newly cast and lustrous mirror reflecting the radiance of divine effulgence, O Virgin, thou didst receive it as it came upon thee. Blessed art Thou among women, O all-immaculate Lady!`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`Having spread his hands, Daniel closed the lions’ jaws * in their den; * while the zealously pious youths, * girded with virtue, * quenched the power of the fire and cried aloud: * Bless ye the Lord, all ye works of the Lord.`,tier:2,src:{file:`11-15.pdf`,locus:`p7 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Today the universal festival of the martyrs of Christ hath dawned for us, illumining with the grace of miracles those who approach with faith and spiritual joy, and who cry out with love: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 8 troparion 1`},label:`plain`},{text:`The confessors of Thy divinity, O Master, easily abolished all the ungodliness of the tyrants, undaunted by the threats of the evil-minded; and, strengthened by faith, they cried aloud: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 8 troparion 2`},label:`plain`},{text:`The all-wise confessors, standing up for the divine dogmas, vanquishing hordes of the enemy, and slain by the sword, manifestly and most gloriously have shown themselves to be all-splendidly victorious; for being felled, they triumphed over the adversary.`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 8 troparion 3`},label:`plain`},{text:`Thou hast given birth to Christ Who is seen to be in two natures, manifestly bearing a single hypostasis composed of both divinity and manhood, truly essentially joined together in a unity. Wherefore, we bless thee, O Mary, Bride of God.`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`A cornerstone not cut by hand O Virgin, * was cut from thee the unhewn mountain: * even Christ, Who hath joined together the disparate natures; * therefore rejoicing we magnify thee, * O Theotokos.`,tier:2,src:{file:`11-15.pdf`,locus:`p7 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Following the godly and divinely inspired words of Christ, O divinely radiant confessors, rejoicing, ye took the cross upon your shoulders, following in the steps of the Bestower of life, O right glorious ones.`,tier:1,src:{file:`11-15.pdf`,locus:`p7 Ode 9 troparion 1`},label:`plain`},{text:`Entering with gladness into the whole light of the Trinity, the valiant confessors receive honors for their struggles, being deemed worthy to dwell with the ranks of the incorporeal ones.`,tier:1,src:{file:`11-15.pdf`,locus:`p8 Ode 9 troparion 2`},label:`plain`},{text:`Not in a mirror do ye now behold your hopes of things divine, O confessors of Christ: rather, O most honored and most wise crown-bearers, ye behold the beauty of truth.`,tier:1,src:{file:`11-15.pdf`,locus:`p8 Ode 9 troparion 3`},label:`plain`},{text:`Manifestly shown to be equal in number with the supremely divine Trinity, O confessors of godly eloquence, ye are illumined with the radiance thereof, for, having suffered for the Trinity's sake, ye have now received life incorruptible.`,tier:1,src:{file:`11-15.pdf`,locus:`p8 Ode 9 troparion 4`},label:`plain`},{text:`O Virgin Mother, The Word Who hath adorned all things, and Who desired to come in the flesh, made His abode within Thee, and He found thee alone to be more holy than all others, and truly revealed thee to be the Theotokos.`,tier:1,src:{file:`11-15.pdf`,locus:`p8 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`Armed with the Cross of Christ, as champions of the Faith ye manfully cast down all the might of the tyrants, and denounced all the ungodliness of the idols, O holy ones, fervently confessing the Trinity. Wherefore, ye have worthily received crowns of victory, in that ye suffered lawfully, O all-glorious spiritual athletes. Entreat Christ God, that He grant remission of sins unto those who with love celebrate your holy memory.`,tier:1,src:{file:`11-15.pdf`,locus:`p4 Ode III sessional`},label:`plain`,sourceLabel:`Sessional Hymn of the holy martyrs, in Tone VIII`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`Serving Christ in martyrdom, possessed of an unenslaved soul and wisdom ye enslaved the delusion of the tyrants; for, wounded by faith in the Trinity, O all-praised ones, ye denounced the inglorious fame of polytheism. Wherefore, like stars ye shine forth radiantly in the world with the brilliance of miracles, O blessed and all-praised spiritual athletes. Entreat Christ God, that He grant remission of sins unto those who with love honor your holy memory.`,tier:1,src:{file:`11-15.pdf`,locus:`p5 Ode III another sessional`},label:`glory`,sourceLabel:`Glory ..., Another Sessional Hymn, in the same melody`},{text:`All we, the generations of mankind, * call thee blessed, * in that thou art the Virgin who alone among women * hast given birth without seed unto God in the flesh; * for the fire of the Godhead made its abode within thee, * and thou didst feed the Creator and Lord * with milk as an infant. * Wherefore, we, the race of mankind and of angels, * glorify thy birthgiving, * and together we cry out to thee: * Entreat Christ God to grant forgiveness of sins ** unto those who with faith worship thy most holy Offspring.`,tier:2,src:{file:`11-15.pdf`,locus:`p5 Ode III sessional Theotokion`},type:`theotokion`,label:[`both_now`,`theotokion`],sourceLabel:`Both now ..., Theotokion, in Tone VIII`,tone:8},{text:`Upon beholding the Lamb, Shepherd and Redeemer * upon the Cross, * the ewe-lamb exclaimed weeping, bitterly lamenting, and crying aloud: * “The world rejoiceth, having received deliverance through Thee, * but my womb doth burn, beholding Thy crucifixion, * which Thou hast endured in Thy merciful loving-kindness. * O long-suffering Lord, * Thou abyss and inexhaustible well-spring of mercy, * take pity, and grant forgiveness of sins ** unto those who hymn Thy divine sufferings with faith!”`,tier:2,src:{file:`11-15.pdf`,locus:`p5 Ode III sessional Stavrotheotokion`},type:`stavrotheotokion`,label:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`,label_inline:!0}],exapostilarion:{text:`O Gurias, Samonas and Abibus, ye martyrs of Christ, who of old delivered the maiden from the tomb: anticipate our needs, delivering us from our transgressions, as from a tomb.`,tier:1,src:{file:`11-15.pdf`,locus:`p8 Exapostilarion`},label:`plain`,sourceLabel:`Exapostilarion of the holy martyrs`,spec_mel:`Heaven with stars ...`},exapostilarion_closer:{text:`With thy mighty protection, O pure one, preserve thy servants unharmed by the assaults of the enemy, for thee alone have we acquired as our refuge amid tribulations.`,tier:1,src:{file:`11-15.pdf`,locus:`p8 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}},liturgy:{order:[`troparion`,`kontakion`,`prokeimenon`,`prokeimenon_verse`,`epistle`,`alleluia`,`alleluia_verse`,`gospel`,`communion_verse`],prokeimenon:{text:`In the saints that are in His earth hath the Lord been wondrous; * He hath wrought all His desires in them.`,tier:2,src:{file:`11-15.pdf`,locus:`p9 Liturgy Prokeimenon`},sourceLabel:`Prokeimenon, in Tone IV`,label_inline:!0,tone:4},prokeimenon_verse:{text:`I beheld the Lord ever before me, for He is at my right hand, that I might not be shaken.`,tier:1,src:{file:`11-15.pdf`,locus:`p9 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle:{heading:`EPISTLE TO THE EPHESIANS,`,src:{file:`11-15.pdf`,locus:`p9 Epistle`},citation_verbatim:`§233(EPH. 6: 10-17)`,citation:{book:`Ephesians`,chapter:6,verses:`10-17`,pericope_number:233},citation_basis:`printed`},alleluia:{text:`The righteous cried, and the Lord heard them, and He delivered them out of all their tribulations.`,tier:1,src:{file:`11-15.pdf`,locus:`p9 Alleluia`},sourceLabel:`Alleluia, in Tone IV`,label_inline:!0,tone:4},alleluia_verse:{text:`Many are the tribulations of the righteous, but the Lord shall deliver them out of them all.`,tier:1,src:{file:`11-15.pdf`,locus:`p9 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel:{heading:`GOSPEL ACCORDING TO LUKE,`,src:{file:`11-15.pdf`,locus:`p9 Gospel`},citation_verbatim:`§ 64(LK. 12: 8-12)`,citation:{book:`Luke`,chapter:12,verses:`8-12`,pericope_number:64},citation_basis:`printed`},communion_verse:{text:`Rejoice in the Lord, O ye righteous; praise is meet for the upright.`,tier:1,src:{file:`11-15.pdf`,locus:`p10 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}}}]},"11-16":{_encoded:[`c0.identity`,`c0.great_vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`saint`,title:{text:`COMMEMORATION OF THE HOLY APOSTLE & EVANGELIST MATTHEW`,tier:1,src:{file:`11-16.pdf`,locus:`p1 title`},sourceLabel:`THE 16th DAY OF THE MONTH OF NOVEMBER`},rank:`polyeleos`,fekula_section:`2E`,oca_primary:!0,source_file:`11-16.pdf`,note:`Rank by the encoding_rule_v2.md 1.1 waterfall (ODS vol. III has no 11-16 entry): headed AT GREAT VESPERS, no Little Vespers, Polyeleos with a magnification. PROVISIONAL on the same ground as the Apostle Philip (open question Q-0001): 8 stichera, a Litiya, the blessing of the Loaves, and "But if a vigil is not served". Two troparia are printed, as for Philip (the class of Q-0005). The "Or this Troparion" is pointed differently at its two print sites, and the troparion loses its final period at the Liturgy, exactly as on 11-14.`,troparion:{text:`O holy apostle and evangelist Matthew, * entreat the Merciful God * that He grant remission of sins ** unto our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p5 Troparion of the holy evangelist`},sourceLabel:`At the blessing of the Loaves, the Troparion of the holy evangelist, in Tone III`,tone:3,verified_sites:[{locus:`p5 blessing of the Loaves`,tone:3,repeat:2},{locus:`p6 God is the Lord`,tone:3,repeat:2}]},kontakion:{text:`Casting off the yoke of the office of a publican, * thou didst shoulder the yoke of righteousness * and wast shown to be a most excellent merchant, * bringing in the wisdom from on high as riches. * Wherefore, thou didst preach the Word of truth * uplifting the souls of the despondent, ** describing the hour of judgment.`,tier:2,src:{file:`11-16.pdf`,locus:`p11 Kontakion of the holy evangelist`},verified_sites:[{locus:`p11 after Ode VI`,tone:4},{locus:`p15 AT LITURGY`,tone:4}],sourceLabel:`Kontakion of the holy evangelist, in Tone IV`,spec_mel:`Having been lifted up ...`,tone:4},ikos:{text:`The tyranny of the enemy oppresseth me constantly and seizeth all the seed of my soul, O Matthew, friend of Christ; yet, providing me with the seed of thy prayers, render me fruitful to serve thee, and show me to be the least of those who hymn thee and a recounter of thy many and great corrections, for without hesitation, forsaking all things for the love of Christ, thou didst ardently follow after Him Who called thee, being the first evangelist in the world, describing the hour of judgment.`,tier:1,src:{file:`11-16.pdf`,locus:`p11 Ikos`},sourceLabel:`Ikos`,label_inline:!0},great_vespers:{order:[`rubric`,`lic_rubric`,`lic`,`lic_glory`,`dogmatikon`,`entrance_rubric`,`readings`,`litiya`,`aposticha_rubric`,`aposticha`,`aposticha_glory`,`aposticha_closer`,`troparion_rubric`,`troparion`,`troparion_alternate_rubric`,`troparion_alternate`,`virgin_theotokos_rubric`,`no_vigil_rubric`,`troparion_closer`],rubric:{text:`After the Introductory Psalm, we chant “Blessed is the man ...,” the first antiphon.`,tier:1,src:{file:`11-16.pdf`,locus:`p1 Great Vespers rubric`}},lic_rubric:{text:`On “Lord, I have cried ...,” 8 Stichera of the holy evangelist, in Tone IV:`,tier:1,src:{file:`11-16.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`When He who trieth our hearts * perceived thy godly mind, O apostle, * with His divine foreknowledge, * He delivered thee from injustice and the world; * then, making thee a universal light, * and commanding thee to illumine and shine upon * the ends of the whole world, * He manifestly deemed thee worthy * to write His divine Gospel. * Him do thou entreat, ** that He save and enlighten our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p1 LIC 1`},label:`plain`,tone:4,repeat:2,spec_mel:`Called from on high ...`},{text:`When the beginningless Word * Called thee away from thy tax-booth * to be His disciple, * He cried out to thee, * commanding thee to follow Him * and promising thee a share in His kingdom; * then, O all-blessed one, forsaking all things * and abandoning the tumult of the crowd, * thou didst steadfastly follow after him. * And now, O God-seer, * thou art manifestly full of the ineffable vision of Him. * Him do thou beseech, ** that He save and enlighten our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p1 LIC 2`},label:`plain`,repeat:2,spec_mel:`Called from on high ...`},{text:`Of old the prophets' clear vision * perceived thee to be a holy stone, * rolling upon the earth * and crushing the snares of the deceiver; * and the hypostatic Wisdom, O all-wise one, * made thee a light unto the world * and a preacher of righteousness and truth, * radiant with the beams * of the three-sunned Light, O all-honored one. * Him do thou entreat, ** that He save and enlighten our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p1 LIC 3`},label:`plain`,repeat:2,spec_mel:`Called from on high ...`},{text:`O servant of the supremely divine Wisdom, * when the unapproachable Light came in the flesh * as was His will, * dispelling the gloom of ignorance, * He summoned thee, and thou didst follow * His life-bearing commands, * observing them in a manner transcending understanding, * O Matthew, thou beacon of the Church, * and dwelling-place of Christ. * Him do thou beseech, ** that He save and enlighten our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p1 LIC 4`},label:`plain`,spec_mel:`Called from on high ...`},{text:`Thou wast revealed * burning up delusion * with a tongue of fire, * O Matthew all-praised and most wise, * receiving the advent of the Comforter, * Who made thee radiant by His essence; * hence, thou hast astonished every thought * of those who listen to thy words, * relating to mankind the mighty works of the almighty One. * And now thy sound hath gone forth into all the earth, * O divinely inspired one. * Him do thou entreat, ** that He take pity on all who hymn thee.`,tier:2,src:{file:`11-16.pdf`,locus:`p1 LIC 5`},label:`plain`,spec_mel:`Called from on high ...`}],lic_glory:{text:`When Christ called thee to heavenly discipleship, thou didst diligently follow Him, O God-pleaser, casting aside without hesitation every exercise of earthly care; for, receiving with goodly submission an understanding worthy of the heavenly kingdom, thou didst put aside a base life and vain glory. And having been made an evangelist from that of a publican, thou wast revealed to be a light to those in darkness and a guide to salvation for the lost. And now thou art a most fervent intercessor for the whole world and the saving protector of those who honor thee, O Matthew.`,tier:1,src:{file:`11-16.pdf`,locus:`p2 LIC Glory`},sourceLabel:`Glory ..., in Tone IV`,tone:4},dogmatikon:{text:`Prophet David, the ancestor of God, * spoke of thee in psalmody unto Him Who hath accomplished great things in thee. * For God was well pleased without father to become a man from thee, * the Queen who standeth at His right hand, * and He - the source of life - showed thee to be His mother, * that He might renew His own image, corrupted by the passions. * Having found the lost sheep wandering on the mountain * He hath laid it upon His shoulders, * that He may bring it to his Father; * and in accordance with His own will * unite it to the heavenly powers * and thus, O Theotokos, save the world, ** Christ, Who is richly and abundantly merciful.`,tier:2,src:{file:`11-16.pdf`,locus:`p2 LIC Both now, Dogmatic Theotokion`},type:`dogmatic_theotokion`,sourceLabel:`Both now ..., Dogmatic Theotokion, in Tone IV`,tone:4},entrance_rubric:{text:`Entrance. Prokeimenon of the day. Three Lessons:`,tier:1,src:{file:`11-16.pdf`,locus:`p2 Entrance`}},readings:[{heading:`A READING FROM THE GENERAL EPISTLE OF JOHN`,src:{file:`11-16.pdf`,locus:`p2 Lesson 1`},citation_verbatim:`(I JN. 3: 21-4: 6)`,citation:{book:`1 John`,chapter:3,verses:`3:21-4:6`},citation_basis:`printed`},{heading:`A READING FROM THE GENERAL EPISTLE OF JOHN`,src:{file:`11-16.pdf`,locus:`p2 Lesson 2`},citation_verbatim:`(I JN. 4: 11-16)`,citation:{book:`1 John`,chapter:4,verses:`11-16`},citation_basis:`printed`},{heading:`A READING FROM THE GENERAL EPISTLE OF JOHN`,src:{file:`11-16.pdf`,locus:`p3 Lesson 3`},citation_verbatim:`(I JN. 4: 20-5: 5)`,citation:{book:`1 John`,chapter:4,verses:`4:20-5:5`},citation_basis:`printed`}],litiya:{rubric:{text:`At the Litiya: the Sticheron of the temple, and these Stichera, in Tone IV:`,tier:1,src:{file:`11-16.pdf`,locus:`p3 Litiya rubric`}},stichera:[{text:`With the rod of grace, * O right wondrous one, * thou didst draw all from the abyss of vanity, * submitting to the order of thy Teacher, * Who wholly enlightened thine understanding * and showed thee to be an honored apostle * and a divine proclaimer * of His unapproachable Divinity, ** O all-blessed Matthew.`,tier:2,src:{file:`11-16.pdf`,locus:`p3 Litiya 1`},label:`plain`,tone:4,spec_mel:`As one valiant among the martyrs ...`},{text:`The radiance of the Spirit * descended upon thee in the guise of fire, * and made of thee a divine dwelling, O blessed one, * who quickly drivest off the gloom of godlessness, * and enlightenest the world * with the splendor of thine all-wise words, * O proclaimer of the mysteries of God, * adornment of the apostles ** and beholder of Christ, O blessed one.`,tier:2,src:{file:`11-16.pdf`,locus:`p3 Litiya 2`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`},{text:`Having illumined with the lightning flashes of thy preaching * those who sit in the darkness of unbelief, * O glorious one, * thou didst show them to be sons of our God and Master * through their faith. * Thou didst emulate His sufferings and death * and didst become an heir to His glory, * in that thou art a wise proclaimer of God, ** a disciple of Truth.`,tier:2,src:{file:`11-16.pdf`,locus:`p3 Litiya 3`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`}],glory:{text:`Having forsaken earthly things, thou didst follow after Christ, signed with the inspiration of the Holy Spirit and sent by Him to the Gentiles which were perishing, to turn mankind to the light of the knowledge of God, O apostle Matthew. And, having completed the struggles of thy divine suffering and divers torments, thou didst commit thy soul to Christ. Him do thou entreat, O all-blessed one, that He grant us great mercy.`,tier:1,src:{file:`11-16.pdf`,locus:`p3 Litiya Glory`},sourceLabel:`Glory ..., in Tone II`,tone:2},both_now:{text:`All my hope do I place in thee, O Mother of God; keep me under thy protection.`,tier:1,src:{file:`11-16.pdf`,locus:`p4 Litiya Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion, in Tone II`,tone:2}},aposticha_rubric:{text:`On the Aposticha, these Stichera, in Tone IV:`,tier:1,src:{file:`11-16.pdf`,locus:`p4 Aposticha rubric`}},aposticha:[{text:`With the trumpet of thy words * thou didst summon all * to the knowledge of God, O ever-praised one; * and, having driven the assemblies of the deceived from the earth, * thou didst guide the faithful to one unity of mind. * and prayest now * that those who ever celebrate * thine honored memory with faith ** may be delivered from corruption and misfortunes.`,tier:2,src:{file:`11-16.pdf`,locus:`p4 Aposticha 1`},label:`plain`,tone:4,spec_mel:`Thou hast given a sign ...`},{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-16.pdf`,locus:`p4 Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Christ our God, * Who armed thee with the fiery tongue * of the Holy Spirit * showed thee forth, O apostle, * as a mighty opponent of delusion, * wherewith thou hast received the splendid honors of grace. * Him do thou entreat, * that those who with faith ever celebrate thine honored memory ** may be delivered from corruption and misfortunes.`,tier:2,src:{file:`11-16.pdf`,locus:`p4 Aposticha 2`},label:`plain`,spec_mel:`Thou hast given a sign ...`},{text:`The heavens declare the glory of God, * and the firmament proclaimeth the work of His hands.`,tier:2,src:{file:`11-16.pdf`,locus:`p4 Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Penetrating the depths of the Spirit, O apostle, * thou didst grasp inexhaustible riches, * and drawing forth abundant grace therefrom, * thou hast evangelically bestowed it upon all of us. * And now thou prayest, * that those who with faith ever celebrate * thine honored memory * may be delivered from corruption ** and misfortune.`,tier:2,src:{file:`11-16.pdf`,locus:`p4 Aposticha 3`},label:`plain`,spec_mel:`Thou hast given a sign ...`}],aposticha_glory:{text:`Like a high-flying eagle thou didst most gloriously soar from the depths of evil to the uttermost heights, O all-praised Matthew; for thou didst follow in the steps of Christ Who hath covered the heavens with virtue and filled the whole earth with His knowledge. Thou didst show thyself to be an ardent emulator of Him, proclaiming His glad tidings that peace, life and salvation be granted to those who piously submit to the precepts of God. Do thou likewise guide thereto us who please the Creator and call thee blessed.`,tier:1,src:{file:`11-16.pdf`,locus:`p4 Aposticha Glory`},sourceLabel:`Glory ..., in Tone VI`,tone:6},aposticha_closer:{text:`Christ the Lord, my Creator and Redeemer, * Who came forth from thy womb, O all-pure one, * and clothed Himself in my nature, * hath freed Adam from the primal curse. * Wherefore, like the angel * we unceasingly cry out to thee, * O most pure one, * who art truly the Mother of God and Virgin: * Rejoice!, O Lady, ** the intercession, protection and salvation of our souls!`,tier:2,src:{file:`11-16.pdf`,locus:`p4 Aposticha Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion, in Tone VI`,tone:6},troparion_rubric:{text:`At the blessing of the Loaves, the Troparion of the holy evangelist, in Tone III:`,tier:1,src:{file:`11-16.pdf`,locus:`p5 Blessing of the Loaves rubric`}},troparion_alternate_rubric:{text:`Or this Troparion, in the same tone:`,tier:1,src:{file:`11-16.pdf`,locus:`p5 Or this Troparion rubric`}},troparion_alternate:{text:`Zealously following Christ the Master, * Who in His goodness appeared to mankind on the earth, and called thee from thy tax-booth, * thou wast shown to be a chosen apostle * and a trumpet-voiced proclaimer of the Gospel to the whole world. * Wherefore, we honor thy precious memory, O divinely eloquent Matthew. * Entreat the merciful God, ** that He granteth remission of sins unto our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p5 Or this Troparion`},sourceLabel:`Or this Troparion, in the same tone`},virgin_theotokos_rubric:{text:`And “Virgin Theotokos, rejoice ...,” (Once).`,tier:1,src:{file:`11-16.pdf`,locus:`p5 Virgin Theotokos rejoice rubric`}},no_vigil_rubric:{text:`But if a vigil is not served, then after the Troparion:`,tier:1,src:{file:`11-16.pdf`,locus:`p5 If a vigil is not served`}},troparion_closer:{text:`We hymn thee who hast mediated the salvation of our race, * O Virgin Theotokos; * for thy Son and our God, * accepting suffering on the Cross in the flesh * He had received of thee, * hath delivered us from corruption, ** in that He is the Lover of mankind.`,tier:2,src:{file:`11-16.pdf`,locus:`p5 Dismissal Theotokion (no vigil)`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone III`,tone:3}},matins:{order:`god_is_lord_rubric.troparion.troparion_closer.sessional_1.sessional_2.megalynarion_rubric.megalynarion.megalynarion_verse_rubric.megalynarion_verse.megalynarion_closing_rubric.sessional_polyeleos.anabathmoi_rubric.prokeimenon.prokeimenon_verse.gospel_rubric.gospel.psalm50_sticheron.canon_rubric.canons.sessional_ode3.kontakion.ikos.exapostilarion.exapostilarion_glory.exapostilarion_closer.praises_rubric.praises.praises_glory.praises_closer.closing_rubric`.split(`.`),god_is_lord_rubric:{text:`On “God is the Lord ...,” the Troparion of the holy evangelist, in Tone III:`,tier:1,src:{file:`11-16.pdf`,locus:`p6 God is the Lord rubric`}},troparion_closer:{text:`We hymn thee who hast mediated the salvation of our race, * O Virgin Theotokos; * for thy Son and our God, * accepting suffering on the Cross in the flesh * He had received of thee, * hath delivered us from corruption, ** in that He is the Lover of mankind.`,tier:2,src:{file:`11-16.pdf`,locus:`p6 God is the Lord Theotokion`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., the Theotokion, in Tone III`,tone:3},sessional_1:[{text:`The exceedingly wise Matthew, who was first to record the Gospel of Christ illumining all creation under the heavens, the excellent initiate of the mysteries of Christ, who is now honored with sacred hymns, doth beg forgiveness of sins on behalf of those who honor him with love.`,tier:1,src:{file:`11-16.pdf`,locus:`p6 Sessional 1`},label:`plain`,repeat:2,sourceLabel:`After the 1st chanting of the Psalter, the Sessional Hymn, in Tone I`,spec_mel:`Thy tomb, O Savior ...`,tone:1},{text:`All we who with love flee for refuge to thy goodness * know thee to be the Mother of God * and after childbirth still truly Virgin; * for we sinners have thee as our protection; * we have thee as our salvation in misfortunes, ** as the only All-blameless one.`,tier:2,src:{file:`11-16.pdf`,locus:`p6 Sessional 1 Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone I`,tone:1}],sessional_2:[{text:`Resplendent with works of the right Faith, thou didst extinguish all false religion; and as an insuperable victor thou hast proclaimed the Gospel unto all, richly adorning all the Churches, O apostle Matthew, entreat Christ God, that He grant us great mercy.`,tier:1,src:{file:`11-16.pdf`,locus:`p6 Sessional 2`},label:`plain`,repeat:2,sourceLabel:`After the 2nd chanting of the Psalter, the Sessional Hymn, in Tone III`,spec_mel:`Of the divine Faith ...`,tone:3},{text:`Without separating Himself from the divine Essence when He took flesh in thy womb, the one Lord remained God though He had become a man; and even after thy birthgiving He preserved thee, His Virgin Mother, as immaculate as thou wast before giving birth. Him do thou earnestly beseech, that He grant us great mercy.`,tier:1,src:{file:`11-16.pdf`,locus:`p6 Sessional 2 Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone III`,tone:3}],megalynarion_rubric:{text:`After the Polyeleos, this magnification:`,tier:1,src:{file:`11-16.pdf`,locus:`p6 magnification rubric`}},megalynarion:{text:`We magnify thee, O apostle of Christ and evangelist Matthew, and we honor thy pangs and labors, wherewith thou didst struggle in the proclamation of the Gospel of Christ.`,tier:1,src:{file:`11-16.pdf`,locus:`p6 Magnification`},label_inline:!0},megalynarion_verse_rubric:{text:`Selected verse:`,tier:1,src:{file:`11-16.pdf`,locus:`p6 Selected verse rubric`}},megalynarion_verse:{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-16.pdf`,locus:`p6 Selected Psalm verse`},label:`refrain`,sourceLabel:`A`,label_inline:!0},megalynarion_closing_rubric:{text:`Glory ..., Both now ..., Alleluia ..., Glory to Thee, O God. (Thrice)`,tier:1,src:{file:`11-16.pdf`,locus:`p7 after the selected verses`}},sessional_polyeleos:[{text:`Truly the sound of thy wise words hath gone forth to all the ends of the earth, O all-praised apostle of the Lord, for thou didst manifestly preach to all the vision of God, bringing the nations from ignorance to understanding. Wherefore, having dispelled the darkness of idolatry, thou hast shone forth the light of knowledge upon those who sit in darkness, O all-praised Matthew. Entreat Christ God, that He grant remission of sins unto those who honor thy holy memory with love.`,tier:1,src:{file:`11-16.pdf`,locus:`p7 Polyeleos sessional`},label:`plain`,repeat:2,sourceLabel:`After the Polyeleos, the Sessional Hymn, in Tone VIII`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`All we, the generations of mankind, * call thee blessed, * in that thou art the Virgin who alone among women * hast given birth without seed unto God in the flesh; * for the fire of the Godhead made its abode within thee, * and thou didst feed the Creator and Lord * with milk as an infant. * Wherefore, we, the race of mankind and of angels, * glorify thy birthgiving, * and together we cry out to thee: * Entreat Christ God to grant forgiveness of sins ** unto those who with faith worship thy most holy Offspring.`,tier:2,src:{file:`11-16.pdf`,locus:`p7 Polyeleos sessional Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone VIII`,tone:8}],anabathmoi_rubric:{text:`Song of Ascents, the first Antiphon of Tone IV:`,tier:1,src:{file:`11-16.pdf`,locus:`p7 Song of Ascents rubric`}},prokeimenon:{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-16.pdf`,locus:`p7 Prokeimenon`},sourceLabel:`Prokeimenon, in Tone IV`,label_inline:!0,tone:4},prokeimenon_verse:{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-16.pdf`,locus:`p7 Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel_rubric:{text:`Let every breath praise the Lord.`,tier:1,src:{file:`11-16.pdf`,locus:`p7 Let every breath`}},gospel:{heading:`THE GOSPEL ACCORDING TO ST. JOHN`,src:{file:`11-16.pdf`,locus:`p7 Matins Gospel`},citation_verbatim:`(21:15-25)`,citation:{book:`John`,chapter:21,verses:`15-25`},citation_basis:`printed`},psalm50_sticheron:{text:`Let us clap our hands in hymnody, O ye faithful, in memory of the honored apostle and Evangelist Matthew; for, casting away the yoke and gold of his publican's booth, he followed after Christ and becameth a preacher of the divine Gospel. Hence, as the prophet saith, his sound hath gone forth into all the world, and he prayeth that our souls be saved.`,tier:1,src:{file:`11-16.pdf`,locus:`p8 After Psalm 50 sticheron`},sourceLabel:`After Psalm 50, this Sticheron, in Tone VI`,tone:6},canon_rubric:{text:`Canon of supplication to the Theotokos (the Paraklisis), with 6 Troparia; and that of the holy apostle, with 8 Troparia, the composition of Theophanes, in Tone IV`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Canon rubric`}},canons:[{title:`Canon of supplication to the Theotokos (the Paraklisis), with 6 Troparia; and that of the holy apostle, with 8 Troparia, the composition of Theophanes, in Tone IV`,composer:`Theophanes`,tone:4,odes:{1:{irmos:{text:`I shall open my mouth, * and be filled with the Spirit, * and utter discourse to the Queen and Mother; * and be seen radiantly keeping festival, * joyfully praising her wonders.`,tier:2,src:{file:`11-16.pdf`,locus:`p8 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O all-glorious Matthew, servant of Christ, richly bestow upon me the grace witch abideth within thee, that I may cry aloud, splendidly proclaiming, and, rejoicing hymn thy wonders.`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Ode 1 troparion 1`},label:`plain`},{text:`Thou didst utterly abandon the tumult of earthly things; for, having hearkened to the voice of the incarnate Word, thou wast revealed to be a steward and God-pleasing herald of His grace.`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Ode 1 troparion 2`},label:`plain`},{text:`As an eye-witness and servant of the radiant Word of the pre-eternal Father, O apostle, thou didst go forth, proclaiming the glad tidings of His coming unto all the nations.`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Ode 1 troparion 3`},label:`plain`},{text:`Thou didst announce the glad tidings of the destruction of death, the abolishment of corruption and the manifestation of life, O wise one; for, having conceived the Unapproachable One in her womb, the Virgin hath restored the world.`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}],katavasia:{text:`I shall open my mouth ...`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Ode 1 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},3:{irmos:{text:`O Theotokos, thou living and plentiful fount, * establish in spiritual fellowship those who sing hymns to thee, * and in thy divine glory * grant them crowns of glory.`,tier:2,src:{file:`11-16.pdf`,locus:`p8 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O Word of God, thou hast shown forth Thine apostles as beacons of life which drive away the gloom of ungodliness, illumining the whole world with Thy divine glory, O Master.`,tier:1,src:{file:`11-16.pdf`,locus:`p8 Ode 3 troparion 1`},label:`plain`},{text:`Having armed the most valiant Matthew with Thine armor, O Savior, thou hast made him mightier than the tormenters and revealed him to be the destroyer of the deception of idolatry, O Master and Lover of mankind.`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode 3 troparion 2`},label:`plain`},{text:`The sound of thy fiery tongue consumed the temples of the demons, O divinely inspired Matthew, thou instrument of the Comforter, through whom Christ, the hypostatic Life of all, hath been proclaimed.`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode 3 troparion 3`},label:`plain`},{text:`The trumpet of theology which soundeth forth mightily hath illumined the divinely wise Matthew to proclaim to the peoples, the Effulgence of the Trinity and the incarnation of the Word from thee, O most pure one, in a manner transcending understanding.`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Perceiving the profound counsel of God, * that the incarnation of Thee the Most High, * will be from a Virgin, * the prophet Habbakuk cried aloud: * Glory to Thy power, O Lord!`,tier:2,src:{file:`11-16.pdf`,locus:`p9 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Taught by Thy hypostatic Word, O God, the God-seeing disciple destroyed worldly wisdom, crying aloud unto Thee: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode 4 troparion 1`},label:`plain`},{text:`What manner of praise can we offer unto thee who wast blessed by Christ, O divinely eloquent one? For no man is able to describe in words, the grace which hath blossomed forth in thee, O right wondrous one.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 4 troparion 2`},label:`plain`},{text:`Looking upon thine undefiled and pure mind as a lamp placed on a lofty stand, shining upon those in darkness, O divinely manifest one, the Most High hath set thee before all.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 4 troparion 3`},label:`plain`},{text:`O blessed and all-praised maiden, thou hast elevated slain human nature, in that, in a manner surpassing nature, thou hast given birth to the might of the Most High, as Matthew hath taught.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`All creation stands in awe of thy divine glory; * for thou, O Virgin who hast not known wedlock, * didst contain within thy womb the God of all, * and gave birth to the timeless Son, * bestowing peace, upon all who hymn thee.`,tier:2,src:{file:`11-16.pdf`,locus:`p10 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Receiving the grace of the all-holy Spirit, thou wast shown to be a divine habitation, having taught the light of divine knowledge in a godly manner, wherefore thou wast entrusted with the task of committing to writing the dogmas of Christ, as a chosen eye-witness of God.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 5 troparion 1`},label:`plain`},{text:`Thy tongue was the pen of the Paraclete, Who grants speedy deliverance unto those who acknowledge His dominion and breathes heavenly understanding into the souls of the wise, O most honored Matthew.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 5 troparion 2`},label:`plain`},{text:`Christ sent thee unto the world shining with miracles and the grace of healing, trampling upon the might of the demons and enlightening the souls of all the faithful who hymn thee, the preacher of the world.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 5 troparion 3`},label:`plain`},{text:`O Virgin, thou hast given birth to the pre-eternal son Who clothed Himself in human nature and saved it from corruption in His absolute goodness, as as the divinely eloquent one said in his teaching; thou didst remain a Virgin.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`I have reached the depths of the sea * and the tempest of my many sins hath engulfed me; * but do Thou raise up my life from the abyss * O Greatly-merciful One.`,tier:2,src:{file:`11-16.pdf`,locus:`p10 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`By Thine omnipotent might, O Maker of all, the divinely eloquent and most excellent Matthew was transformed from a publican into an evangelist, in that he followed Thee.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 6 troparion 1`},label:`plain`},{text:`By the spiritually nourishing words of thy glad tidings, O all-blessed Matthew, a multitude of the gentiles have been lifted up and directed to the lofty summit of the virtues.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 6 troparion 2`},label:`plain`},{text:`With the divinely woven nets of the disciple Matthew the assemblies of the faithful are ever drawn up, guided to the knowledge of Thee, O our Benefactor.`,tier:1,src:{file:`11-16.pdf`,locus:`p10 Ode 6 troparion 3`},label:`plain`},{text:`O all-immaculate one, the most excellent Matthew announceth glad tidings, describing thee as the Virgin who gaveth birth without seed and corruption unto Him Who fashioned all things.`,tier:1,src:{file:`11-16.pdf`,locus:`p11 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`Refusing to worship created things * in place of the Creator, * the divinely wise youths bravely trampled down the threatening fire * and rejoicing they sang aloud: * O supremely hymned Lord and God of our Fathers, Blessed art Thou.`,tier:2,src:{file:`11-16.pdf`,locus:`p11 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou wast a divine image of the primal effulgence, as a disciple set afire by His splendors; and, chanting to Him, thou didst say: Blessed and supremely praised art Thou, O Lord God of our Fathers!`,tier:1,src:{file:`11-16.pdf`,locus:`p11 Ode 7 troparion 1`},label:`plain`},{text:`As servant of the Word, O all-blessed one, thou hast made thine abode in the divine mansions where Christ abideth, as the one supremely divine Lord and God of all the fathers promised thee.`,tier:1,src:{file:`11-16.pdf`,locus:`p11 Ode 7 troparion 2`},label:`plain`},{text:`Infirmities are banished and a multitude of demons are forced to flee by the gifts of the divine Spirit which are in thee, wherein thou didst chant: Blessed and supremely praised art Thou, O Lord God of our Fathers!`,tier:1,src:{file:`11-16.pdf`,locus:`p11 Ode 7 troparion 3`},label:`plain`},{text:`With thy divine words, O apostle, thou didst describe the all-hymned Virgin who hath given birth to the Creator. To Him do we all chant: Blessed and supremely praised art Thou, O Lord God of our Fathers!`,tier:1,src:{file:`11-16.pdf`,locus:`p11 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`The Offspring of the Theotokos * saved the holy children in the furnace. * He who was then prefigured hath now been born on earth, * and He gathereth all creation to hymn thee: * all ye works praise ye the Lord * and supremely exalt Him throughout all ages.`,tier:2,src:{file:`11-16.pdf`,locus:`p11 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Deified by the mighty forces within Thee and by Thine ordination and nature, O Master, the most sacred Matthew prevailed upon the whole world to chant to Thee: Hymn the Lord, O ye works, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 8 troparion 1`},label:`plain`},{text:`The Word sent the theologian forth like lightning to the whole world, driving away the darkness and enlightening the nations with the dogmas of theology. Wherefore, he chanted: Hymn the Lord, O ye works, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 8 troparion 2`},label:`plain`},{text:`With pure discourse and mind God conversed with thee; for having rid thyself of mire, thou didst draw nigh and associate with Him, O glorious one. Wherefore, thou dost chant: Hymn the Lord, O ye works, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 8 troparion 3`},label:`plain`},{text:`The Word willed to become incarnate for the good of mankind; for the Lord passed through the portal of virginity and showed her forth as the Theotokos. Wherefore, we cry aloud: Hymn the Lord, O ye works, and supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`Let every mortal born on earth, * radiant with light, in spirit leap for joy; * and let the host of the angelic powers * celebrate and honor the holy feast of the Mother of God, * and let them cry aloud: * Rejoice! O all-blessed Theotokos, * thou pure Ever-virgin.`,tier:2,src:{file:`11-16.pdf`,locus:`p12 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou didst receive the divine diadem of noetic beauty, O apostle, and wast adorned with the most magnificent crown of the kingdom by the right hand of the Almighty, O wise one. And thou dost shine, standing with the angels before the throne of Christ the Master, O all-blessed one.`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 9 troparion 1`},label:`plain`},{text:`Thou didst receive the tree of life as is meet, O preacher of the living God, having spread the glad tidings of life, the visitation of God to the world; for thou didst not permit thy mind to become corrupt through the tree of knowledge, remaining an unshaken and immovable foundation of the Church, O all-blessed one.`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 9 troparion 2`},label:`plain`},{text:`In a godly manner thou didst adorn the Church, the Bride of Christ, with thy Gospel as with a diadem, O divinely blessed one, and now it splendidly celebrateth thy divine memory, pray thou, O apostle Matthew, that it be delivered from every evil circumstance and cruel misfortune.`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 9 troparion 3`},label:`plain`},{text:`Without leaving the bosom of the beginningless Father, the beginningless Word became incarnate from thee, O pure and all-praised one, wholly clothing Himself in human nature and accepting its traits, as Matthew writeth, proclaiming the glad tidings.`,tier:1,src:{file:`11-16.pdf`,locus:`p12 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`Truly the sound of thy wise words hath gone forth to all the ends of the earth, O all-praised apostle of the Lord, for thou, manifestly preaching to all the vision of God, didst draw the nations from ignorance unto understanding. Wherefore, having dispelled the darkness of idolatry, thou hast shone forth the light of knowledge upon those who sit in darkness, O all-praised Matthew. Entreat Christ God, that He grant remission of sins unto those who honor thy holy memory with love.`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode III sessional`},label:`plain`,sourceLabel:`Sessional Hymn of the holy evangelist, in Tone VIII`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`O apostle of the Lord, we all praise thee as the lamp and disciple of the Light, an eyewitness of the divine Word; for, spreading thy nets of grace, by thy command thou didst ensnare reason-endowed souls like fish. Wherefore having entrapped the nations through the power of the Spirit, they are now manifestly guided by faith, O all-praised initiate of the mysteries of heaven. Entreat Christ God, that He grant remission of sins unto those who honor thy holy memory with love.`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode III sessional Glory`},label:`glory`,sourceLabel:`Glory ..., in the same melody`},{text:`In that thou art the most immaculate Bride of the Creator, the Mother of the Redeemer who knewest not wedlock, the receptacle of the Comforter, O all-hymned one, haste thou to deliver me, who am the vile abode of iniquity and in mind am the plaything of the demons, from their wickedness, and make of me a radiant dwelling-place of the virtues, O luminous and incorrupt one. Drive from me the cloud of the passions and grant that I may partake of the never-waning light of the Most High, through thy supplications.`,tier:1,src:{file:`11-16.pdf`,locus:`p9 Ode III sessional Theotokion`},type:`theotokion`,label:[`both_now`,`theotokion`],sourceLabel:`Both now ..., Theotokion, in Tone VIII`,tone:8}],exapostilarion:{text:`The God-pleasing Matthew, the glorious recorder of the Gospel of Christ, hath related divine wonders unto us. Honoring him with love, let us chant unto him with godly melodies.`,tier:1,src:{file:`11-16.pdf`,locus:`p13 Exapostilarion`},label:`plain`,sourceLabel:`Exapostilarion of the holy evangelist`,spec_mel:`He hath visited us ...`},exapostilarion_glory:{text:`Having wisely cast off the yoke of thy publican's office, thou didst follow Christ, O divinely wise Matthew; and following wondrously in His steps, thou didst obtain a share of His kingdom and glory through communion with Him, being an initiate of ineffable mysteries.`,tier:1,src:{file:`11-16.pdf`,locus:`p13 Another Exapostilarion`},label:`glory`,sourceLabel:`Glory ..., another Exapostilarion`},exapostilarion_closer:{text:`O Virgin Theotokos, lift up thine all-holy hands, wherewith thou didst hold the Creator, in supplication to Him for us, that He deliver us from all the temptations of the evil one and grant that we may receive His good things in the world to come, O all-hymned one.`,tier:1,src:{file:`11-16.pdf`,locus:`p13 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion`},praises_rubric:{text:`On the Praises; 4 Stichera of the holy evangelist, in Tone IV:`,tier:1,src:{file:`11-16.pdf`,locus:`p13 Praises rubric`}},praises:[{text:`Thou didst shine forth, O apostle, * as luminous as the sun, with the rays of the Spirit, * and hast illumined the whole world * with the knowledge of God, O blessed one. * And thou hast dispelled the gloom of polytheism, * O all-wise Matthew.” * Wherefore, we celebrate today, * thy most radiant and right wondrous solemnity ** as a well-spring of sanctification.`,tier:2,src:{file:`11-16.pdf`,locus:`p13 Praises 1`},label:`plain`,tone:4,spec_mel:`Thou hast given a sign ...`,repeat:2,provenance_note:`The repeat device is printed bare, "Twice", with no parentheses (p13).`},{text:`Seated on the heights of divine knowledge, O apostle, * thou didst receive the effulgence of the Spirit, * which appeared to thee * in the guise of a tongue of fire; * and thou didst manifestly consume * all the tinder of the impiety of ungodliness. * Wherefore, we honor thee * as an apostle and herald of God, ** celebrating thy holy festival today.`,tier:2,src:{file:`11-16.pdf`,locus:`p13 Praises 2`},label:`plain`,spec_mel:`Thou hast given a sign ...`},{text:`Thou didst thunder forth * sacred and saving teachings * unto the whole world, O all-wise Matthew, * cleansing all creation of the madness of idolatry, * and illumining the people * with the splendors of the Gospel. * and, having destroyed the pagan temples * by means of grace, ** thou didst. raise up churches to the glory of God.`,tier:2,src:{file:`11-16.pdf`,locus:`p13 Praises 3`},label:`plain`,spec_mel:`Thou hast given a sign ...`}],praises_glory:{text:`Abandoning the yoke of injustice and casting away the gold of usury, thou didst make haste to the yoke of righteousness and dost grasp inexhaustible wealth like an able merchant, trading transitory things for what is everlasting and corruptible things for what abideth. For, having acquired the divinely lustrous pearl of great price, thou didst wisely leave to Caesar the things which keep men below; and having obediently followed after Christ, the King of all, thou didst enrich all creation with the divine words of the Gospel, O wise one. O all-excellent Matthew, ask thou now that salvation and great mercy be granted to those who honor thee.`,tier:1,src:{file:`11-16.pdf`,locus:`p13 Praises Glory`},composer:`Byzantius`,sourceLabel:`Glory ..., the composition of Byzantius, in Tone II`,tone:2},praises_closer:{text:`Save from misfortunes, * thy servants O Virgin Theotokos, * for after God * it is to thee that we flee, ** as to an impregnable rampart and protection.`,tier:2,src:{file:`11-16.pdf`,locus:`p14 Praises Both now`},type:`theotokion`,sourceLabel:`Both now ..., Theotokion, in Tone II`,tone:2},closing_rubric:{text:`Great Doxology, Troparia, Litanies, Dismissal. First Hour.`,tier:1,src:{file:`11-16.pdf`,locus:`p14 Matins closing rubric`}}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`liturgy_troparion`,`troparion_alternate_rubric`,`troparion_alternate`,`kontakion`,`prokeimenon`,`prokeimenon_verse`,`epistle`,`alleluia`,`alleluia_verse`,`gospel`,`communion_verse`],beatitudes_rubric:{text:`On the Beatitudes, 8 Troparia: 4 from ODE III, and 4 from ODE VI of the canon of the holy evangelist.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitudes rubric`}},beatitudes:[{text:`O Word of God, thou hast shown forth Thine apostles as beacons of life which drive away the gloom of ungodliness, illumining the whole world with Thy divine glory, O Master.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 1`},label:`plain`,repeat:2},{text:`Having armed the most valiant Matthew with Thine armor, O Savior, thou hast made him mightier than the tormenters and revealed him to be the destroyer of the deception of idolatry, O Master and Lover of mankind.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 2`},label:`plain`},{text:`The sound of thy fiery tongue consumed the temples of the demons, O divinely inspired Matthew, thou instrument of the Comforter, through whom Christ, the hypostatic Life of all, hath been proclaimed.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 3`},label:`plain`},{text:`By Thine omnipotent might, O Maker of all, the divinely eloquent and most excellent Matthew was transformed from a publican into an evangelist, in that he followed Thee.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 4`},label:`plain`},{text:`By the spiritually nourishing words of thy glad tidings, O all-blessed Matthew, a multitude of the gentiles have been lifted up and directed to the lofty summit of the virtues.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 5`},label:`plain`},{text:`With the divinely woven nets of the disciple Matthew the assemblies of the faithful are ever drawn up, guided to the knowledge of Thee, O our Benefactor.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 6`},label:`plain`},{text:`O all-immaculate one, the most excellent Matthew announceth glad tidings, describing thee as the Virgin who gaveth birth without seed and corruption unto Him Who fashioned all things.`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Beatitude 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}],liturgy_troparion:{text:`O holy apostle and evangelist Matthew, * entreat the Merciful God * that He grant remission of sins ** unto our souls`,tier:2,src:{file:`11-16.pdf`,locus:`p15 Troparion at Liturgy`},sourceLabel:`Troparion of the holy evangelist, in Tone III`,tone:3},troparion_alternate_rubric:{text:`Or this Troparion, in the same tone:`,tier:1,src:{file:`11-16.pdf`,locus:`p15 Or this Troparion rubric (Liturgy)`}},troparion_alternate:{text:`Zealously following Christ the Master, * Who in His goodness appeared to mankind on the earth, * and called thee from thy tax-booth, * thou wast shown to be a chosen apostle * and a trumpet-voiced proclaimer of the Gospel to the whole world. * Wherefore, we honor thy precious memory, O divinely eloquent Matthew. * Entreat the merciful God, ** that He granteth remission of sins unto our souls.`,tier:2,src:{file:`11-16.pdf`,locus:`p15 Or this Troparion (Liturgy)`},sourceLabel:`Or this Troparion, in the same tone`},prokeimenon:{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-16.pdf`,locus:`p16 Liturgy Prokeimenon`},sourceLabel:`Prokeimenon, in Tone VIII`,label_inline:!0,tone:8},prokeimenon_verse:{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-16.pdf`,locus:`p16 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle:{heading:`EPISTLE TO THE CORINTHIANS,`,src:{file:`11-16.pdf`,locus:`p16 Epistle`},citation_verbatim:`§111(I COR. 4: 9-16)`,citation:{book:`1 Corinthians`,chapter:4,verses:`9-16`,pericope_number:111},citation_basis:`printed`},alleluia:{text:`The heavens shall confess Thy wonders, O Lord, and Thy truth in the congregation of saints.`,tier:1,src:{file:`11-16.pdf`,locus:`p16 Alleluia`},sourceLabel:`Alleluia, in Tone I`,label_inline:!0,tone:1},alleluia_verse:{text:`God Who is glorified in the council of the saints.`,tier:1,src:{file:`11-16.pdf`,locus:`p16 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel:{heading:`GOSPEL ACCORDING TO MATTHEW,`,src:{file:`11-16.pdf`,locus:`p16 Gospel`},citation_verbatim:`§30(9: 9-13)`,citation:{book:`Matthew`,chapter:9,verses:`9-13`,pericope_number:30},citation_basis:`printed`},communion_verse:{text:`Their sound hath gone forth into all the earth, and their words unto the ends of the world.`,tier:1,src:{file:`11-16.pdf`,locus:`p16 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}}}]},"11-17":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`saint`,title:{text:`COMMEMORATION OF OUR FATHER AMONG THE SAINTS, GREGORY THE WONDERWORKER, BISHOP OF NEO-CAESAREA`,tier:1,src:{file:`11-17.pdf`,locus:`p1 title`},sourceLabel:`THE 17th DAY OF THE MONTH OF NOVEMBER`},rank:`six_stichera`,fekula_section:`2C`,oca_primary:!0,source_file:`11-17.pdf`,note:`Rank by the encoding_rule_v2.md 1.1 waterfall (ODS vol. III has no 11-17 entry): 6 stichera of one saint at Lord I have cried (four printed, two "(Twice)"), no Polyeleos, no Great Doxology; the aposticha at both Vespers and Matins are appointed from the Oktoechos. Nothing is printed at Matins before the canon. The Both-now closers print only the Stavrotheotokion; the Theotokion is named and not printed. The Beatitudes take three troparia of Ode III and its theotokion, passing over the third.`,troparion:{text:`By vigilance in prayer and continuance in the working of miracles, * thou didst acquire the name of thy worthy deeds. * Yet pray thou to Christ God, O father Gregory, ** that He enlighten our souls, lest we sleep unto death.`,tier:2,src:{file:`11-17.pdf`,locus:`p2 Troparion of the holy hierarch`},verified_sites:[{locus:`p2 end of Vespers`,tone:8},{locus:`p9 AT LITURGY`,tone:8}],sourceLabel:`Troparion of the holy hierarch, in Tone VIII`,tone:8},kontakion:{text:`Receiving the power to work many miracles, * thou didst terrify the demons with awesome signs, * and dispelled the diseases of men, O all-wise Gregory. * And thou wast called the wonderworker, ** receiving this title from thy works.`,tier:2,src:{file:`11-17.pdf`,locus:`p6 Kontakion of the holy hierarch`},verified_sites:[{locus:`p6 after Ode VI`,tone:2},{locus:`p9 AT LITURGY`,tone:2}],sourceLabel:`Kontakion of the holy hierarch, in Tone II`,spec_mel:`Seeking the highest ...`,tone:2},ikos:{text:`Where shall I, wretched as I am, begin to weave praises, beholding so many and most wondrous things? If I begin with the life of the venerable one, I will not in any way be able to proceed; for his divine life surpasseth comprehension. And if I begin with his miracles, I shall be ashamed to try to proceed any further, for they are more numerous than the sands of the sea. For this cause he is called the wonder-worker, receiving this title because of his works.`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ikos`},sourceLabel:`Ikos`,label_inline:!0},vespers:{order:[`lic_rubric`,`lic`,`lic_glory`,`lic_closer_rubric`,`lic_stavrotheotokion`,`aposticha_rubric`,`aposticha`,`aposticha_glory`,`aposticha_closer_rubric`,`aposticha_stavrotheotokion`,`troparion`,`troparion_closer_rubric`],lic_rubric:{text:`On “Lord, I have cried ...,” 6 Stichera of the holy hierarch, in Tone VIII:`,tier:1,src:{file:`11-17.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`What shall we call thee, O Gregory? * Master, for thou didst subject the passions to thy mind! * Husbandman, for thou didst reap the fruit of wisdom! * One who hath been deemed worthy of divine vision, * and hath been catechized with heavenly theology; * a most sacred performer of the mysteries * and most wondrous worker of miracles. ** Pray thou that our souls be saved.`,tier:2,src:{file:`11-17.pdf`,locus:`p1 LIC 1`},label:`plain`,tone:8,repeat:2,spec_mel:`What shall we call thee ...`},{text:`What shall I call thee now, O Gregory? * Mighty destroyer of godless impiety, * one that setteth the laws of piety, wise teacher, * and bestower of invincible peace, * unvanquished overthrower of armies, * thou who ever abidest in the mountains * and lookest down upon those who are in the cities. ** Pray thou that our souls be saved.`,tier:2,src:{file:`11-17.pdf`,locus:`p1 LIC 2`},label:`plain`,repeat:2,spec_mel:`What shall we call thee ...`},{text:`What now shall I proclaim thee, O venerable one? * Emulator of the apostles, * as a worker of miracles, * who didst restrain the river by the invocation of Christ * and dried up the lake which was the cause of contention between brethren, * who dispersed the synagogue opposed to God, * and increased and enlightened Christian assemblies. ** Pray thou that our souls be saved.`,tier:2,src:{file:`11-17.pdf`,locus:`p1 LIC 3`},label:`plain`,spec_mel:`What shall we call thee ...`},{text:`What now shall I proclaim thee, O venerable one? * Guide of those who are astray * and physician of the ailing, * bestower of an abundance of necessities upon those who ask, * most mighty persecutor of demons, * one who urged the struggle of martyrdom, * and was prophetically illumined with graces, O right glorious one. ** Pray thou that our souls be saved.`,tier:2,src:{file:`11-17.pdf`,locus:`p1 LIC 4`},label:`plain`,spec_mel:`What shall we call thee ...`}],lic_glory:{text:`Having all-wisely entered the depths of knowledge, O hierarch of Christ, thou didst acquire the vision of the Trinity; foreseeing unwaveringly in the Spirit Christ our God, thou dost pour forth upon us an abyss of miracles, having made the watery nature of the sea solid and changed the pagan priest's dark delusion into belief, thou didst persuade the persecutors to believe truly and show thyself to them to be a pillar of the virtues of piety; and through thy miracles wast called a prophet. Wherefore, we beseech thee, cease thou never to entreat the Savior on our behalf, that our souls be saved.`,tier:1,src:{file:`11-17.pdf`,locus:`p1 LIC Glory`},sourceLabel:`Glory ..., in Tone VI`,tone:6},lic_closer_rubric:{text:`Both now ..., Theotokion, or this Stavrotheotokion, in Tone VI:`,tier:1,src:{file:`11-17.pdf`,locus:`p1 LIC Both now rubric`}},lic_stavrotheotokion:{text:`Upon seeing Thee crucified, O Christ, * she who gaveth birth to Thee cried aloud: * “What is this strange mystery that I see, * O my Son How is it that Thou diest?, * suspended upon the Tree, ** O Bestower of life?”`,tier:2,src:{file:`11-17.pdf`,locus:`p1 LIC Stavrotheotokion`},type:`stavrotheotokion`,tone:6,sourceLabel:`Stavrotheotokion`,label_inline:!0,spec_mel:`On the third day ...`},aposticha_rubric:{text:`On the Aposticha, the Stichera from the Oktoechos.`,tier:1,src:{file:`11-17.pdf`,locus:`p2 Aposticha rubric`}},aposticha:{absent:!0,reason:`governed_by_octoechos`,basis:`close_reading`,note:`The rubric appoints "the Stichera from the Oktoechos"; none are printed here.`,book:`octoechos`},aposticha_glory:{text:`The wakefulness of God was given thee, O wise one, as it had been given to Daniel; for, as a dream was revealed to him, so was the mystery of the Faith disclosed to thee. Wherefore, O venerable father, pray thou that our souls be saved.`,tier:1,src:{file:`11-17.pdf`,locus:`p2 Aposticha Glory`},sourceLabel:`Glory ..., in Tone VI`,tone:6},aposticha_closer_rubric:{text:`Both now ..., Theotokion, or this Stavrotheotokion, in Tone VI:`,tier:1,src:{file:`11-17.pdf`,locus:`p2 Aposticha Both now rubric`}},aposticha_stavrotheotokion:{text:`Upon seeing Thee hanging upon the Cross * the all-pure one weeping, cried aloud with a mother’s grief: * ‘O my Son and my God, O my sweetest Child, ** how dost Thou endure this shameful suffering?’`,tier:2,src:{file:`11-17.pdf`,locus:`p2 Aposticha Stavrotheotokion`},type:`stavrotheotokion`,tone:6,sourceLabel:`Stavrotheotokion`,label_inline:!0},troparion_closer_rubric:{text:`Glory ..., Both now ..., Theotokion, or Stavrotheotokion.`,tier:1,src:{file:`11-17.pdf`,locus:`p2 Troparion Theotokion rubric`}}},matins:{order:[`canon_rubric`,`canons`,`sessional_ode3`,`kontakion`,`ikos`,`exapostilarion`,`exapostilarion_closer`,`aposticha_rubric`,`aposticha`,`aposticha_glory`,`aposticha_closer_rubric`,`aposticha_stavrotheotokion`],canon_rubric:{text:`Both canons from the Oktoechos, and that of the saint, with 6 Troparia, the acrostic whereof is: “I shall weave praise for Gregory the Wonderworker,” the composition of Theophanes, in Tone VIII:`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Canon rubric`}},canons:[{title:`Both canons from the Oktoechos, and that of the saint, with 6 Troparia, the acrostic whereof is: “I shall weave praise for Gregory the Wonderworker,” the composition of Theophanes, in Tone VIII:`,composer:`Theophanes`,acrostic:`I shall weave praise for Gregory the Wonderworker`,tone:8,odes:{1:{irmos:{text:`The wonderworking staff of Moses, * striking and dividing the sea in the figure of a cross, * once drowned pharaoh the pursuing charioteer, * while it saved the fleeing people of Israel * as they fled on foot, * chanting a hymn unto God.`,tier:2,src:{file:`11-17.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O father Gregory, do thou now splendidly show forth the divine activity of thy wonders in me, delivering me from the abyss of my transgressions and enlightening me with thy radiance, that I may hymn thee as is meet, O blessed one.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`As one who is skillful, sensible and wise, thou didst prefer nobility of soul to the passions of the flesh, O blessed one, industriously assembling the dogmas of wisdom whereby the soul that draweth nigh to God is nourished, O Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 1 troparion 2`},label:`plain`},{text:`When thou hadst acquired chastity as a sister, as a good companion, O Gregory, the wicked serpent, beholding thee, raised up hatred against thee. But thou didst put him to shame, O father, by thy longsuffering, healing the woman who was held fast in the clutches of passion.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 1 troparion 3`},label:`plain`},{text:`Residing in a strange land, O venerable one, in thy virtue thou wast manifest to all as honorable, pious and God-loving, having received the gift of working wonders from God, whereby thou hast been known, O divinely eloquent one, shining forth in the world like the sun.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 1 troparion 4`},label:`plain`},{text:`Thou wast put forth as a shoot from a royal root, O pure one, and, in a manner surpassing comprehension and thought, thou didst give birth from thy pure blood unto Christ the King, the incarnate Word of God, Who is of two natures, yet a single hypostasis.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`O Christ fortify me on the rock of Thy commandments, * Thou who in the beginning didst establish the heavens with understanding * and didst establish the earth upon the waters, * for there is none holy save Thee, O only Lover of mankind.`,tier:2,src:{file:`11-17.pdf`,locus:`p3 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having cleansed thy mind of the turbulence of the passions, and being full of the love of wisdom and vision, thou wast shown to be magnificent, an abode of wisdom, enriched with the gift of prophecy, O Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 3 troparion 1`},label:`plain`},{text:`Being conversant in the divinely inspired Scriptures, O all-blessed one, and having clearly chosen a different way of life, thou didst establish within thyself the single image of virtue, O divinely wise Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p3 Ode 3 troparion 2`},label:`plain`},{text:`O divinely revealed one, having obtained the mystery of theology through divine initiation, enlighten us, that we may honor the consubstantial Trinity, one in essence, uncreated and equally everlasting.`,tier:1,src:{file:`11-17.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`Instructed by God, in that thou didst seek Him with love, thou didst have the pure Theotokos Mary and the son of thunder as instructors in the mysteries, guiding thee to the light of the Trinity, O divinely eloquent one.`,tier:1,src:{file:`11-17.pdf`,locus:`p4 Ode 3 troparion 4`},label:`plain`},{text:`O pure maiden, we all know thee to be the staff which budded forth Christ, the Flower of incorruption, and the golden censer who held in thine arms the Burning Coal of the divine Essence, O divinely blessed one.`,tier:1,src:{file:`11-17.pdf`,locus:`p4 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Thou, O Lord, art my strength and Thou art my power, * Thou art my God and Thou art my joy, * Thou Who, while never leaving the bosom of Thy Father, * hast visited our poverty. * Therefore with the prophet Habbakuk I cry unto Thee, * “Glory to Thy power, O Lover of mankind!”`,tier:2,src:{file:`11-17.pdf`,locus:`p4 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having ploughed the good earth, O divinely wise father, and sown the seed of the Word, thou dost ever now evangelically increase thy yield an hundredfold, O Gregory, by thy teachings bringing to God those who chant: Glory to Thy power, O Lover of mankind!`,tier:1,src:{file:`11-17.pdf`,locus:`p4 Ode 4 troparion 1`},label:`plain`},{text:`Thy life, shining forth like lightning, O father, hath dispelled the falsehood of the demons; for their darkness could not withstand the light of thy virtues. Wherefore, the minister of spiritually pernicious deception, moved like the stone he beheld, was enlightened.`,tier:1,src:{file:`11-17.pdf`,locus:`p4 Ode 4 troparion 2`},label:`plain`},{text:`Thou wast deemed worthy to behold the darkness of the most divine Light, O father, and, having received the divinely written law like Moses, thou didst obtain precision in theology. Hence, thou hast been shown to be a law-giver of the Church of Christ, O divinely wise Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 4 troparion 3`},label:`plain`},{text:`Having turned away from the foolish talk of the rhetors and being enlightened by the word of grace, O father, thou didst truly receive the apostles' power over the demons, for the prince of darkness fled before thy brilliant splendor.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 4 troparion 4`},label:`plain`},{text:`From of old the ark prefigured thee, O all-immaculate one, who received within thy womb the divinely written Law, ineffably conceiving the life-creating Word, Who doth richly nourish the souls of those who cry aloud: Glory to Thy power, O Lover of mankind!`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Light never-waning, * why hast Thou turned Thy face from me * and why hath the alien darkness surrounded me, * wretched though I be? * But do Thou guide my steps I implore Thee * and turn me back towards the light of Thy commandments.`,tier:2,src:{file:`11-17.pdf`,locus:`p5 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having loosened hardened hearts with the husbandry of thy words, thou didst cast upon them the divine seed, O hierarch, bringing forth an abundant harvest, the salvation of the faithful, unto the Redeemer, O divinely eloquent one.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 5 troparion 1`},label:`plain`},{text:`Phaedimus, the servant of God, aflame with zeal, piously trusting in God, Who knoweth all things, and in thine honorable life, O divinely eloquent father Gregory, ordained thee even though thou hadst not come to him.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 5 troparion 2`},label:`plain`},{text:`With the streams of thy precepts thou didst quench idolatrous immolations, and established the faithful through thy teachings, O all-wise one, having, like Samuel, ascended the mountain through visions, and being also like an oak in thy steadfastness.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 5 troparion 3`},label:`plain`},{text:`O divinely wise and holy hierarch, by thy prayers deliver me from evil and grievous circumstances, and rend asunder the handwriting of my transgressions, O father, for thou art a priest who hast received from God the power to loose transgressions.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 5 troparion 4`},label:`plain`},{text:`O Virgin, thou wast adorned with the most pure beauties of thy virginity, covering the misshapen shame of the first Eve, having given birth to Christ, Who bestoweth upon those who honor thee the garment of immortality.`,tier:1,src:{file:`11-17.pdf`,locus:`p5 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`Cleanse me, O Savior, * for many are mine iniquities; * lead me up from the abyss of evils I pray Thee, * for unto Thee have I cried, * and Thou hast hearkened unto me, * O God of my salvation.`,tier:2,src:{file:`11-17.pdf`,locus:`p5 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The lake which was the cause of contention between two brethren didst thou dry up in a miraculous fashion; and thou didst cause the rushing of the river to cease, O all-wise one, and when thou didst plant thy staff, it took root and grew at thy divine command, O Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 6 troparion 1`},label:`plain`},{text:`Godly zeal consumed thee, O spiritually rich hierarch, for unable to endure the sight of an insult to God, O divinely eloquent one, thou didst destroy the vain-minded one by thy prayers.`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 6 troparion 2`},label:`plain`},{text:`The wretched and impious Jew, who wished to destroy thee, himself died, showing thee forth as a fulfiller of the dogmas of God, Who doth glorify thee, O divinely wise Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 6 troparion 3`},label:`plain`},{text:`The Spirit, Who worketh all things, came down upon thee, O all-immaculate one, and the Word of God made His abode within thee, ineffably becoming flesh, yet remaining unchanged.`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`Once in Babylon the fire stood in awe * of God's condescension; * for which sake the youths in the furnace, * dancing with joyous steps as in a meadow, chanted: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`11-17.pdf`,locus:`p6 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The boast of the fathers and the pride of the holy instructors, the luminary of the Church and immovable pillar of piety hast thou been revealed to be, O Gregory, who dost cry aloud: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 7 troparion 1`},label:`plain`},{text:`Shining forth in miracles, thou didst enlighten the whole world, O divinely wise Gregory; wherefore, having assembled together, we bless thee, nurtured by thy words and chanting: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 7 troparion 2`},label:`plain`},{text:`O divinely wise one, thou hast poured forth healing upon all the infirm; for most abundant and wonderworking grace was poured forth through thy mouth, whereby thou didst cry: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-17.pdf`,locus:`p6 Ode 7 troparion 3`},label:`plain`},{text:`Now all things are filled with divine light through thee, O most pure one; for thou hast been revealed to be the door through which God hath communed with the world, enlightening those who cry with faith: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`In his wrath the Chaldean tyrant made the furnace blaze, * with heat fanned sevenfold for the servants of God; * but when he perceived that they had been saved by a greater power * he cried aloud to the Creator and Redeemer; * “Ye children bless, ye priests praise, * ye people, supremely exalt Him throughout all ages”.`,tier:2,src:{file:`11-17.pdf`,locus:`p7 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Enriched by thee with the radiance of the consubstantial and honored Trinity and celebrating now thy festival, O Gregory, we ask that we may be illumined with wonderworking grace, crying aloud to the Master: Ye children bless; ye priests hymn; ye people supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 8 troparion 1`},label:`plain`},{text:`Receiving the radiance of the sovereign Godhead like a newly revealed mirror, O spiritually rich hierarch, thou hast illumined the world with rays of light, beaming down Orthodoxy upon those who melodiously chant: Ye children bless; ye priests hymn; ye people supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 8 troparion 2`},label:`plain`},{text:`Protected by God, O all-wise one, thou wast preserved in hiding on the mountain for those who honor God, as a source of piety, like another Moses the law-giver; and thou didst teach them to hymn the Creator and Redeemer, singing: Ye children bless; ye priests hymn; ye people supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 8 troparion 3`},label:`plain`},{text:`Thou wast the abode of the unwaning Light, O most pure one, shining with the beauties of virginity and illumining all who from the depths of their souls confess thee to be the true Theotokos and who chant: Ye children bless; ye priests hymn; ye people supremely exalt Him throughout all ages!`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`Heaven was stricken with awe, * and the ends of the earth were filled with amazement, * for God hath appeared in the flesh, * and thy womb was rendered more spacious than the heavens. * Wherefore, the ranks of men and of angels * magnify thee as the Theotokos.`,tier:2,src:{file:`11-17.pdf`,locus:`p7 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Shining with the light of thy most exemplary life, thou dost now stand before the great Light, crowned as a victor with divinely wrought miracles, O divinely wise wonderworker, venerable hierarch, father Gregory, thou beacon of the Church and adornment of the Orthodox.`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 9 troparion 1`},label:`plain`},{text:`In thy supplications do thou now ask that the royal elect and sanctified priesthood be guided aright, O wonderworker, and that those who now faithfully celebrate thy memory receive the Kingdom of heaven and be deemed worthy of divine gladness.`,tier:1,src:{file:`11-17.pdf`,locus:`p7 Ode 9 troparion 2`},label:`plain`},{text:`Having put down the attacks of the demons and subjected the reasoning of thy flesh, O wonderworker, as a venerable and guileless hierarch, arrayed in the garment of righteousness, thou dost stand before the throne of the King of all with boldness, O all-blessed one.`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Ode 9 troparion 3`},label:`plain`},{text:`O Virgin Mother of God, thou art revealed as she who, in a manner transcending nature, gaveth birth in the flesh to the good Word, Whom the Father poured forth from His heart before all ages, in that He is good. Him do we now know as more exalted than all beings, even though He hath been clothed in a body.`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`Thou wast a new Moses in thy works, receiving the tablets of faith on the mountain of mystical divine revelation, setting down as law for the people the piety of the mystery of the Trinity, O Gregory. Wherefore, all we, the faithful, honor thy memory, asking for great mercy through thee.`,tier:1,src:{file:`11-17.pdf`,locus:`p4 Ode III sessional`},label:`plain`,repeat:2,sourceLabel:`Sessional Hymn of the holy hierarch, in Tone III`,spec_mel:`Of the divine faith ...`,tone:3},{text:`Thou wast the divine tabernacle of the Word, * O only most pure Virgin Mother * who surpassed the angels in purity. * By the divine waters of thy supplications * cleanse me who, more than all others, * have become dust, defiled by carnal transgressions; ** and grant me great mercy, O pure one.`,tier:2,src:{file:`11-17.pdf`,locus:`p4 Ode III sessional Theotokion`},type:`theotokion`,label:[`glory`,`both_now`,`theotokion`],sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone III`,tone:3},{text:`The unblemished ewe-lamb of the Word, * the incorrupt Virgin Mother, * beholding Him Who sprang forth from her without pain * suspended upon the Cross, cried out, maternally lamenting: * “Woe is me, O my Child! * How is it that Thou dost suffer willingly, * desiring to redeem mankind ** from the indignity of the passions?”`,tier:2,src:{file:`11-17.pdf`,locus:`p4 Ode III sessional Stavrotheotokion`},type:`stavrotheotokion`,label:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`,label_inline:!0}],exapostilarion:{text:`Thou didst shine forth in miracles, O wonderworker Gregory, delivering the pagan priest from corruption and demonic deception by moving a stone at thy command; and, having dried up a lake, thou didst restrain a river. Wherefore, we all praise thee together, O thrice-blessed one.`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Exapostilarion`},label:`plain`,sourceLabel:`Exapostilarion of the holy hierarch`,spec_mel:`Hearken, ye women ...`},exapostilarion_closer:{text:`Rejoice, thou boast of the faithful, confirmation of the venerable! Rejoice, glory of the righteous! Rejoice, thou light of those who are in darkness! Rejoice, most holy temple! Rejoice, paradise of God! Rejoice, loosing of the curse, O blessed Mary!`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Theotokion, in the same melody`},aposticha_rubric:{text:`After the Aposticha from the Oktoechos, this Sticheron to the saint, in Tone IV:`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Matins Aposticha rubric`}},aposticha:[{text:`Thy priests shall be clothed with righteousness, * and Thy righteous shall rejoice.`,tier:2,src:{file:`11-17.pdf`,locus:`p8 Matins Aposticha verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Having received the election of the priesthood from God and been vested in a divine robe from on high, thou didst show forth those who before were children of unbelief to be children and heirs of the light; for the grace of the wisdom of God was poured forth in thy mouth, O Gregory, performer of most glorious deeds. Wherefore, now, on the day of thy commemoration, entreat Christ God on behalf of our souls.`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Matins Aposticha sticheron to the saint`},label:`plain`,tone:4}],aposticha_glory:{text:`Filled with awe by the hierarch renowned for his wonders, inanimate things were altered; for a lake which was the cause of dissension between two brethren dried up, and a staff grew, restraining a river; a stone moved at thy command, leading the unbelieving to knowledge of God. For his sake, O God, grant our souls great mercy.`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Matins Aposticha Glory`},sourceLabel:`Glory ..., in Tone VIII`,tone:8},aposticha_closer_rubric:{text:`Both now ..., Theotokion, or this Stavrotheotokion, in Tone VIII:`,tier:1,src:{file:`11-17.pdf`,locus:`p8 Matins Aposticha Both now rubric`}},aposticha_stavrotheotokion:{text:`“What is this sight which I see, * which mine eyes behold, O Master? * How is it that Thou Who dost sustain all creation, * art lifted up upon the Tree and diest, * granting life unto all? * thus said the Theotokos weeping, * upon seeing God and man * Who had shone forth ineffably from her ** hanging upon the Cross.`,tier:2,src:{file:`11-17.pdf`,locus:`p8 Matins Aposticha Stavrotheotokion`},type:`stavrotheotokion`,tone:8,sourceLabel:`Stavrotheotokion`,label_inline:!0,spec_mel:`O most glorious wonder ...`}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`troparion`,`kontakion`,`prokeimenon`,`prokeimenon_verse`,`epistle`,`alleluia`,`alleluia_verse`,`gospel`,`communion_verse`],beatitudes_rubric:{text:`On the Beatitudes, 4 Troparia from the Oktoechos, and 4 from ODE III of the canon of the holy hierarch.`,tier:1,src:{file:`11-17.pdf`,locus:`p9 Beatitudes rubric`}},beatitudes:[{text:`Having cleansed thy mind of the turbulence of the passions, and being full of the love of wisdom and vision, thou wast shown to be magnificent, an abode of wisdom, enriched with the gift of prophecy, O Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p9 Beatitude 1`},label:`plain`},{text:`Being conversant in the divinely inspired Scriptures, O all-blessed one, and having clearly chosen a different way of life, thou didst establish within thyself the single image of virtue, O divinely wise Gregory.`,tier:1,src:{file:`11-17.pdf`,locus:`p9 Beatitude 2`},label:`plain`},{text:`Instructed by God, in that thou didst seek Him with love, thou didst have the pure Theotokos Mary and the son of thunder as instructors in the mysteries, guiding thee to the light of the Trinity, O divinely eloquent one.`,tier:1,src:{file:`11-17.pdf`,locus:`p9 Beatitude 3`},label:`plain`},{text:`O pure maiden, we all know thee to be the staff which budded forth Christ, the Flower of incorruption, and the golden censer who held in thine arms the Burning Coal of the divine Essence, O divinely blessed one.`,tier:1,src:{file:`11-17.pdf`,locus:`p9 Beatitude 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}],prokeimenon:{text:`Precious in the sight of the Lord * is the death of His saints.`,tier:2,src:{file:`11-17.pdf`,locus:`p9 Liturgy Prokeimenon`},sourceLabel:`Prokeimenon, in Tone VII`,label_inline:!0,tone:7},prokeimenon_verse:{text:`What shall I render unto the Lord for all that He hath rendered unto me?`,tier:1,src:{file:`11-17.pdf`,locus:`p9 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle:{heading:`THE FIRST EPISTLE OF ST. PAUL TO THE CORINTHIANS`,src:{file:`11-17.pdf`,locus:`p9 Epistle`},citation_verbatim:`(12:7-11)`,citation:{book:`1 Corinthians`,chapter:12,verses:`7-11`},citation_basis:`printed`},alleluia:{text:`Thy priests shall be clothed with righteousness, and Thy righteous shall rejoice.`,tier:1,src:{file:`11-17.pdf`,locus:`p10 Alleluia`},sourceLabel:`Alleluia, in Tone II`,label_inline:!0,tone:2},alleluia_verse:{text:`For the Lord hath elected Zion, He hath chosen her to be a habitation for Himself.`,tier:1,src:{file:`11-17.pdf`,locus:`p10 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel:{heading:`THE GOSPEL ACCORDING TO ST. MATTHEW`,src:{file:`11-17.pdf`,locus:`p10 Gospel`},citation_verbatim:`(10:1, 5-8)`,citation:{book:`Matthew`,chapter:10,verses:`1, 5-8`},citation_basis:`printed`},communion_verse:{text:`In everlasting remembrance shall the righteous be; he shall not be afraid of evil tidings.`,tier:1,src:{file:`11-17.pdf`,locus:`p10 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}}}]},"11-18":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`saint`,title:{text:`COMMEMORATION OF THE HOLY MARTYRS PLATO & ROMANUS`,tier:1,src:{file:`11-18.pdf`,locus:`p1 title`},sourceLabel:`THE 18th DAY OF THE MONTH OF NOVEMBER`},rank:`simple`,fekula_section:`2B`,oca_primary:!0,source_file:`11-18.pdf`,note:`A double commemoration: 3 stichera of the martyr Plato and 3 of the martyr Romanus at Lord I have cried, so 6 printed for two saints, which the encoding_rule_v2.md 1.1 waterfall reads as Simple rank, double service (Fekula 2B). ODS vol. III has no 11-18 entry. No Polyeleos, no Great Doxology. TWO canons, printed interleaved ode by ode and stored whole. The Glory, the kontakion, the ikos and the exapostilarion are Plato's alone; Romanus has stichera, a canon and a sessional hymn. No aposticha and no aposticha Glory are printed at Vespers, not even a rubric. At Liturgy only the troparion and kontakion are printed: no prokeimenon, readings, alleluia or communion verse.`,troparion:{text:`In their sufferings, Thy martyrs O Lord, * received imperishable crowns from Thee, our God; * for, possessed of Thy might, * they set at naught the tyrants and crushed the feeble audacity of the demons. ** By their supplications save Thou our souls.`,tier:2,src:{file:`11-18.pdf`,locus:`p2 Troparion of the holy martyrs`},verified_sites:[{locus:`p2 end of Vespers`,tone:4},{locus:`p11 AT LITURGY`,tone:4}],sourceLabel:`Troparion of the holy martyrs, in Tone IV`,tone:4},kontakion:{text:`Thy holy memory doth gladden the whole world, * summoning all the faithful to thine all honorable temple, * where, assembled now with joy, we chant in hymns amid splendor. * Wherefore, O Plato, we cry out to thee: ** Deliver thy city from the invasion of the heathen, O holy one.`,tier:2,src:{file:`11-18.pdf`,locus:`p8 Kontakion of the holy martyr Plato`},saint:`Plato`,verified_sites:[{locus:`p8 after Ode VI`,tone:3},{locus:`p11 AT LITURGY`,tone:3}],sourceLabel:`Kontakion of the holy martyr Plato, in Tone III`,spec_mel:`Today the Virgin ...`,tone:3},ikos:{text:`Having abandoned all pagan superstition, the divinely wise Plato came to love the soul-saving teachings of the disciples of Christ. Wherefore, he appeared honorable to all, like an anchor of the Faith in his native land, and manifestly bore the title “Of Ancyra.” For, nurtured well, it found him to be an excellent protection against the enemy and a fervent helper in battle, crying aloud: Deliver thy city from the invasion of the heathen, O holy one!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ikos`},saint:`Plato`,sourceLabel:`Ikos`,label_inline:!0},vespers:{order:[`lic_rubric`,`lic`,`lic_glory`,`lic_closer_rubric`,`lic_stavrotheotokion`,`troparion`],lic_rubric:{text:`On “Lord, I have cried ...,” 6 Stichera: 3 of the martyr Plato, in Tone VIII:`,tier:1,src:{file:`11-18.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`Full of valiant wisdom, * with a most courageous resolve thou didst endure * the severing of thy limbs * and the dismemberment of thy body, * unbearable fire, * starvation and death, * in expectation of the glory which ageth not, * which lieth eternally before thee, ** and foreseeing everlasting blessedness.`,tier:2,src:{file:`11-18.pdf`,locus:`p1 LIC 1`},label:`plain`,saint:`Plato`,tone:8,spec_mel:`O most glorious wonder ...`},{text:`Having transcended every sense * and directed thy mind * toward life on high, * with divinely wise thought * and great wisdom of soul * thou didst spurn the baseness and lowliness * of visible things. * Wherefore, lacerated and burned with fire for Christ, O martyr, ** thou didst endure valiantly.`,tier:2,src:{file:`11-18.pdf`,locus:`p1 LIC 2`},label:`plain`,saint:`Plato`,spec_mel:`O most glorious wonder ...`},{text:`Every assault of the enemy * and the onslaughts of the persecutors * didst thou set at naught by grace; * and wast crowned with the wreath of victory, * O spiritually rich martyr, * being deemed worthy of incorruptible gladness * and ineffable and divine radiance. * And as thou art now in the midst thereof, ** ask remission of sins for those who praise thee as is meet.`,tier:2,src:{file:`11-18.pdf`,locus:`p1 LIC 3`},label:`plain`,saint:`Plato`,spec_mel:`O most glorious wonder ...`},{text:`Consumed by fasting, * hardened by ascetic endeavor, * and tormented with manifold tortures, * thou didst become a two-edged sword, * cutting down hordes of demons, O Romanus, * thou adornment of spiritual athletes, * divine boast, * precious ornament of the Church ** of those who died shedding their own blood, O all-praised one.`,tier:2,src:{file:`11-18.pdf`,locus:`p1 LIC 4`},label:`plain`,saint:`Romanus`,sourceLabel:`And 3 Stichera of the martyr Romanus, in Tone IV`,spec_mel:`As one valiant among the martyrs ...`,tone:4},{text:`Lacerated and rent asunder, * imprisoned in a dungeon, * thy tongue cut of, O glorious spiritual athlete, * thy jaw broken, * receiving a blessed end through violent suffocation, * thou wast shown to be * unshakable and steadfast * through the activity of the divine Spirit, O Romanus; ** wherefore, we praise thee with faith.`,tier:2,src:{file:`11-18.pdf`,locus:`p1 LIC 5`},label:`plain`,saint:`Romanus`,spec_mel:`As one valiant among the martyrs ...`},{text:`A child speaketh eloquently * and amazeth the mindless: * he is adorned with honorable opposition * and is illumined by his death; * he is enriched by the goodly fame of the holy spiritual athletes, * whose zeal he acquired. * O right wise Romanus, * pray thou with them, ** that remission of debts be sent down upon us all.`,tier:2,src:{file:`11-18.pdf`,locus:`p1 LIC 6`},label:`plain`,saint:`Romanus`,spec_mel:`As one valiant among the martyrs ...`}],lic_glory:{text:`Awesome and most glorious are the victories of Thy martyr, O Lord! For, emulating the boldness of the fishermen, by his words and deeds he rent asunder the mythology and historical blasphemy of Plato with the nets of theology; and when his skin was flayed and his head severed, he choked the enemy with the outpouring of his blood. O all-blessed wonderworker Plato, thou adornment of the martyrs, who preached the great name of Christ with boldness, ask that great mercy be given our souls.`,tier:1,src:{file:`11-18.pdf`,locus:`p2 LIC Glory`},saint:`Plato`,sourceLabel:`Glory ..., in Tone VI`,tone:6},lic_closer_rubric:{text:`Both now ..., Theotokion, or this Stavrotheotokion, in Tone VI:`,tier:1,src:{file:`11-18.pdf`,locus:`p2 LIC Both now rubric`}},lic_stavrotheotokion:{text:`Upon seeing Thee crucified, O Christ, * she who gaveth birth to Thee cried aloud: * “What is this strange mystery that I see, * O my Son How is it that Thou diest?, * suspended upon the Tree, ** O Bestower of life?”`,tier:2,src:{file:`11-18.pdf`,locus:`p2 LIC Stavrotheotokion`},type:`stavrotheotokion`,tone:6,sourceLabel:`Stavrotheotokion`,label_inline:!0,spec_mel:`On the third day ...`}},matins:{order:[`canon_rubric`,`canons`,`sessional_ode3`,`kontakion`,`ikos`,`exapostilarion`,`exapostilarion_closer`],canon_rubric:{text:`One canon from the Oktoechos, and two canons of the holy martyrs.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Canon rubric`}},canons:[{title:`Canon of the holy martyr Plato, the acrostic whereof is: “I hymn the expanse of thy praises, O Plato”, the composition of Theophanes, in Tone VIII:`,composer:`Theophanes`,acrostic:`I hymn the expanse of thy praises, O Plato`,tone:8,odes:{1:{irmos:{text:`The wonderworking staff of Moses, * striking and dividing the sea in the figure of a cross, * once drowned pharaoh the pursuing charioteer, * while it saved the fleeing people of Israel * as they fled on foot, * chanting a hymn unto God.`,tier:2,src:{file:`11-18.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Traversing the most pure expanse of the eternal kingdom, O glorious one, from all tribulation and the dangers of imprisonment save those who hymn thee, leading to the path to heaven those who walk without turning back.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`Protected by the armor of piety, and having shown thyself to be an unshakable pillar, O Plato, thou didst endure all the savagery of wounds and accepted the pangs of imprisonment, exalted by divine grace.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 troparion 2`},label:`plain`},{text:`Showing forth the mettle of youth, in thy suffering thou didst cast off mortal and corruptible coarseness, O all-wise one, and, arrayed in the garment of incorruption, thou standest, rejoicing, before the Master.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 troparion 3`},label:`plain`},{text:`In a manner surpassing understanding thou hast given birth to the incarnate and only-begotten Word, Who is co-beginningless and everlasting with the Father, O blessed and most pure Theotokos. Wherefore, reasoning correctly, we proclaim and honorably glorify thee.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`O Christ fortify me on the rock of Thy commandments, * Thou who in the beginning didst establish the heavens with understanding * and didst establish the earth upon the waters, * for there is none holy save Thee, O only Lover of mankind.`,tier:2,src:{file:`11-18.pdf`,locus:`p4 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Manifestly aflame with the zeal of piety, and enlightened by the divine fire of the Faith, O all-blessed one, with endurance thou didst enter into the cruel flame like a spark of incorruption.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 troparion 1`},label:`plain`},{text:`Having supra-naturally vanquished the servants of the demons, and borne with patience the pain of mighty tortures, O blessed and divinely wise Plato, thou wast shown to be a dweller with the angels and a crown-bearer.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 troparion 2`},label:`plain`},{text:`Having struggled for Christ on earth, O all-blessed one, receiving from Him heavenly gifts and crowns which abide forever, thou dwellest in the pure land of paradise.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`O Mother of God, thou art the portal of the Light, adorned with the rays of the light of the Spirit; for through thee descended unto us the Word Who illumineth with divine light all who hymn thee.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Thou, O Lord, art my strength and Thou art my power, * Thou art my God and Thou art my joy, * Thou Who, while never leaving the bosom of Thy Father, * hast visited our poverty. * Therefore with the prophet Habbakuk I cry unto Thee, * “Glory to Thy power, O Lover of mankind!”`,tier:2,src:{file:`11-18.pdf`,locus:`p5 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Wholly transformed by the love of thy Creator, thou didst not feel the pain of thy body, having shed the skin garments of thy flesh from passions and mortality, and clothed thyself in the robe of chastity and salvation.`,tier:1,src:{file:`11-18.pdf`,locus:`p5 Ode 4 troparion 1`},label:`plain`},{text:`Thou wast revealed to be a true priest of God, offering thyself unto Christ the Redeemer Who was slain for all, as an unblemished lamb and a perfect sacrifice, O martyr; for, having set thy soul afire with love for the Master, thou didst pay no heed to thy burning flesh.`,tier:1,src:{file:`11-18.pdf`,locus:`p5 Ode 4 troparion 2`},label:`plain`},{text:`Emulating the three youths who were in Babylon, thou didst not fear the all-devouring fire, but mightily and youthfully endured the unbearable flame thereof. Wherefore, the Bestower of dew hath rightly taken thee with them into the chamber of glory.`,tier:1,src:{file:`11-18.pdf`,locus:`p5 Ode 4 troparion 3`},label:`plain`},{text:`In that thou art the royal root, thou hast given birth for us unto the Word of God Who reigneth over all, Who became flesh, yet remained unchanged. Wherefore, O all-holy Virgin, with truth and authority we glorify thee, the Theotokos.`,tier:1,src:{file:`11-18.pdf`,locus:`p5 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Light never-waning, * why hast Thou turned Thy face from me * and why hath the alien darkness surrounded me, * wretched though I be? * But do Thou guide my steps I implore Thee * and turn me back towards the light of Thy commandments.`,tier:2,src:{file:`11-18.pdf`,locus:`p6 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou gavest neither slumber to thine eyelids, nor sleep to thine eyes, O martyr, until, beheaded by the sword, thou didst sleep the sleep of the blessed like those who love God, O blessed one.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 5 troparion 1`},label:`plain`},{text:`Suffering, thou didst struggle as in another's body, O all-blessed one; thou didst suffer, viewing thy pangs as though another was experiencing them. For, set afire with divine zeal, thou didst not fear the future torments, O glorious one.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 5 troparion 2`},label:`plain`},{text:`Thou hast discovered riches which cannot be taken away, and unfading glory, joining chorus with the angels in the mansions of heaven, partaking of incorruptible immortality, O most eminent one.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 5 troparion 3`},label:`plain`},{text:`By thy supplications grant remission of sins to thy servants, delivering them from temptations, misfortunes and sorrows, and from enslavement to blasphemous heretics, O all-praised Virgin Theotokos.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`Cleanse me, O Savior, * for many are mine iniquities; * lead me up from the abyss of evils I pray Thee, * for unto Thee have I cried, * and Thou hast hearkened unto me, * O God of my salvation.`,tier:2,src:{file:`11-18.pdf`,locus:`p7 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Transcending sufferings and tortures, thou didst endure the cutting away of thy flesh, O glorious one; for thou didst have Christ as thy Helper, Assistant and Companion.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 troparion 1`},label:`plain`},{text:`Ever gazing upon the majesty of the Creator with spiritual understanding, and contemplating ineffable beauty, thou didst spurn the baseness of visible things.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 troparion 2`},label:`plain`},{text:`As an animate ark thou didst hold the Bestower of life, as a holy temple thou didst receive the Holy One Who had become a man, for the good of mankind, O all-blessed one.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`Once in Babylon the fire stood in awe * of God's condescension; * for which sake the youths in the furnace, * dancing with joyous steps as in a meadow, chanted: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`11-18.pdf`,locus:`p8 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`He Who set down the law hath crowned with a wreath of victory thee who suffered lawfully and trampled underfoot thine enemies, and who cried aloud, saying: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ode 7 troparion 1`},label:`plain`},{text:`Thou didst pass over, rejoicing, to Him Whom from of old thou didst desire, emulating His most pure sufferings, which were the cause of the salvation of mankind; and thou didst chant: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ode 7 troparion 2`},label:`plain`},{text:`All the hosts of heaven, and the people looking on, marveled at thy patient endurance of suffering; for thy severed tongue supra-naturally cried aloud: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ode 7 troparion 3`},label:`plain`},{text:`Delivered from the bonds of death and the curse of the first-formed Adam by the divine Offspring of thy virginity, O most pure one, mindful that thou art the Theotokos, we cry aloud: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`In his wrath the Chaldean tyrant made the furnace blaze, * with heat fanned sevenfold for the servants of God; * but when he perceived that they had been saved by a greater power * he cried aloud to the Creator and Redeemer; * “Ye children bless, ye priests praise, * ye people, supremely exalt Him throughout all ages”.`,tier:2,src:{file:`11-18.pdf`,locus:`p9 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou didst struggle in radiant feats, O all-praised one, and Christ bestowed upon thee the most splendid, blessed and ever-enduring fame, causing thee to dwell in the mansions of heaven, wherefore thou dost fervently chant: Ye priests hymn; ye people, supremely exalt Christ throughout the ages!`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 8 troparion 1`},label:`plain`},{text:`As a most faithful supplicant, as a most fervent intercessor for us, we now set thee before the King of all, the Author of creation. Pray thou for us, interceding in thy martyr's boldness on behalf of those who praise thee and chant with faith: Ye people, supremely exalt Christ throughout the ages!`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 8 troparion 2`},label:`plain`},{text:`Because of thine active faith thou wast deemed worthy to receive a kingship which cannot be taken away; for God, Who lieth not, promised to give it thee, and for Him thou didst commit thy body to fire and torture, crying aloud: Ye priests hymn; ye people, supremely exalt Christ throughout the ages!`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 8 troparion 3`},label:`plain`},{text:`In a manner most divine thou didst give birth to the Word of God, Who is co-beginningless and of equal honor with the Father, Who brought all things forth out of non-existence by the counsel of the Father, and assumed flesh for the sake of mankind. Wherefore, acknowledging thee, in an Orthodox fashion, to be the Theotokos, we supremely exalt Christ throughout the ages.`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`Every ear is awestruck at hearing of God's ineffable condescension, * for the Most High voluntarily descended and assumed flesh, * becoming man in the Virgin's womb; * wherefore we the faithful magnify the most pure Theotokos.`,tier:2,src:{file:`11-18.pdf`,locus:`p10 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O ye who love the martyrs, come, let us hymn the martyr, crowned by God, who extended the piety of his birth; for, as an offshoot of the branch of life, he bringeth forth fruit which poureth forth the wine of compunction for us.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 9 troparion 1`},label:`plain`},{text:`Precious in the sight of the Lord was the death of the martyr, for he hath become the mediator of the true life which is everlasting and imperishable, giving abundant recompense, incorruption and immortal glory.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 9 troparion 2`},label:`plain`},{text:`All thy life didst thou consecrate to God almighty, O martyr, and, rejoicing, thou didst offer thyself as a well-pleasing and living sacrifice. Wherefore, thou hast manifestly been deemed worthy of the sweetness which passeth understanding. Pray thou that those who hymn thee be delivered from temptations.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 9 troparion 3`},label:`plain`},{text:`Save me, O Mother of God who hast given birth to Christ my Savior, Who is both God and man, in two natures, but not in two hypostases, the Only-begotten of the Father and of thee, the first-born of all creation. Wherefore, all of us ever magnify thee.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}},{title:`Canon of the holy martyr Romanus, the acrostic whereof is: “With spiritual athletes' wreaths I crown thee, O Romanus”, in Tone IV:`,acrostic:`With spiritual athletes' wreaths I crown thee, O Romanus`,tone:4,odes:{1:{irmos:{text:`Through the deep of the Red Sea, * marched dry shod Israel of old, * and by Moses’ outstretched hands, * raised in the form of a cross, * the power of Amalek was routed in the wilderness.`,tier:2,src:{file:`11-18.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Shining brightly with the never-waning radiance of the Trinity, and enlightened with the choirs of spiritual athletes, O Romanus, send down enlightenment upon me, and drive away the darkness of the passions by thy supplications, which are acceptable to God.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`Unmoved by the raging waves of the sea of idolatry, in that thou wast set firmly upon Christ the rock, thou didst destroy the threefold billows of most seditious ungodliness with the calm of the divine Spirit.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 troparion 2`},label:`plain`},{text:`The Church of Christ, which aboundeth in every good thing, O Romanus, didst thou preserve untouched by the wolves, like a right-glorious and right-fruitful meadow, making it steadfast by thy teaching.`,tier:1,src:{file:`11-18.pdf`,locus:`p3 Ode 1 troparion 3`},label:`plain`},{text:`Truly, human nature hath found mercy through thee, O all-immaculate one; for the Creator, having become incarnate from thee in a manner past all telling and understanding, was led to death for us, delivering us from Hades.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`Thy Church, O Christ, rejoiceth in Thee crying aloud: * Thou, O Lord, art my strength, * my refuge and foundation.`,tier:2,src:{file:`11-18.pdf`,locus:`p4 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having slain the spiritual beast with the sling of thy words, O Romanus, thou didst preserve the flock of Christ uncorrupted by the evil of idolatry.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 troparion 1`},label:`plain`},{text:`Rendered mighty by the armor of the Cross, thou didst turn back the assaults of the enemy and denounced their impotence, O wise and right blessed Romanus.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 troparion 2`},label:`plain`},{text:`When thy cheek was lacerated for Christ, O glorious, blessed and ever-memorable Romanus, thou didst cast down the enemy, breaking their jaws.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`Clothed in the flesh He received from thee, He Who alone is God by nature, the Word of the Father, Who is one in essence with the Spirit, hath deified mortals, O Mother of God.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Beholding Thee, the Sun of righteousness, * lifted up upon the Cross, * the Church now standeth arrayed and doth worthily cry aloud: * Glory be to Thy power, O Lord!`,tier:2,src:{file:`11-18.pdf`,locus:`p6 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`With ineffable beauty thou didst ascend the tree, mounting it like a stairway, O blessed one, and attained unto the everlasting choir, O right glorious martyr Romanus.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 4 troparion 1`},label:`plain`},{text:`Having shed thy mortal garments amid thy tortures, O blessed one, thou didst array thyself splendidly in a garment of light, O all-glorious martyr Romanus.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 4 troparion 2`},label:`plain`},{text:`Made wise by the inspiration of the Comforter, the tongue of the boy proclaimed Thee to be the Lord of glory, the Creator of all and God Who art able to save, O Lover of mankind.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 4 troparion 3`},label:`plain`},{text:`Blessed is the Fruit of thy womb, O Virgin, whereby all peoples of the world have been delivered from the curse of death; and blessed by thee, we hymn thee as the mediatress of Life.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`Thou, O Lord, who camest into the world, * art my light, * a holy Light turning from the darkness of ignorance * those who sing Thy praises in faith.`,tier:2,src:{file:`11-18.pdf`,locus:`p6 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`With the martyric streams of thy blood thou didst engulf the sea of ungodliness; and thou hast poured forth rivers of healing, O Romanus.`,tier:1,src:{file:`11-18.pdf`,locus:`p6 Ode 5 troparion 1`},label:`plain`},{text:`O Romanus, thou didst offer to the Master as a choice gift, an unblemished sacrifice, the slain boy Varulus who proclaimed theological things.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 5 troparion 2`},label:`plain`},{text:`Thou didst wound the foolishness of the enemy with the wisdom of the Holy Spirit, as he inflicted wounds upon thy body, O all-glorious Romanus.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 5 troparion 3`},label:`plain`},{text:`In that thou hast given birth unto Joy, O Virgin Mary who knewest not wedlock, thou hast destroyed the curse and restored mankind through thy birthgiving.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`The Church crieth out unto Thee O Lord, * ‘I will sacrifice unto Thee with a voice of praise * having been cleansed of the blood of the demons' * by the blood that for mercy's sake flowed from Thy side.`,tier:2,src:{file:`11-18.pdf`,locus:`p7 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having with ease shed mortality and corruption and arrayed thyself in the beauty of life incorruptible, O Romanus, thou hast been adorned with never-diminishing spiritual splendors.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 troparion 1`},label:`plain`},{text:`Thy tongue was severed and poured forth torrents of blood like teachings, O passion-bearer, and thou didst thereby inherit the imperishable blessedness which is ever-abiding.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 troparion 2`},label:`plain`},{text:`Thirsting for a stream of wisdom, by the counsel of his mother thou didst pour drink into the mouth of the boy who uttered theology, and who entered into the endless life by means of the sword.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 troparion 3`},label:`plain`},{text:`Be thou a ready refuge for me, O most pure Mother of God, delivering me from violence, taking from me the shame of the passions and guiding me to the godly path.`,tier:1,src:{file:`11-18.pdf`,locus:`p7 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`In the Persian furnace the youths and descendants of Abraham, * burning with a love of piety * rather than by a flame of fire, * cried aloud saying: * Blessed art Thou in the temple of Thy glory, O Lord.`,tier:2,src:{file:`11-18.pdf`,locus:`p8 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`By being strangled, thou didst choke the serpent, O passion-bearer, and didst truly find life, O most glorious Romanus, ever crying aloud: Blessed art Thou in the temple of Thy glory, O Lord!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ode 7 troparion 1`},label:`plain`},{text:`Illumined with rays of never-waning light, O Romanus, thou didst quench the lofty flame, adorned with the gift of prophecy and numbered among the choirs of the martyrs, crying aloud: Blessed art Thou in the temple of Thy glory, O Lord!`,tier:1,src:{file:`11-18.pdf`,locus:`p8 Ode 7 troparion 2`},label:`plain`},{text:`A fragrant rose of tender growth, watered with his mother's teachings and the blood of martyrdom, hath been incorruptibly offered to Christ as from a garden of many flowers.`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 7 troparion 3`},label:`plain`},{text:`O all-hymned one who hast alone given birth to God without seed, lead us forth who have fallen into the abyss of sin, but who hymn thee, saying: Blessed art Thou among women, O all-immaculate Lady.`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`Having spread his hands, Daniel closed the lions’ jaws * in their den; * while the zealously pious youths, * girded with virtue, * quenched the power of the fire and cried aloud: * Bless ye the Lord, all ye works of the Lord.`,tier:2,src:{file:`11-18.pdf`,locus:`p9 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou wast obedient to the words of Christ, O glorious one, laying down thy life for thy flock, being strangled in thy zeal for it, tortured, lacerated and wounded; and thou didst cry aloud: Bless the Lord, all ye works of the Lord.`,tier:1,src:{file:`11-18.pdf`,locus:`p9 Ode 8 troparion 1`},label:`plain`},{text:`Truly thy mouth and tongue were full of joy and gladness, continually blessing God; for, cut out and dripping with blood, O Romanus, it setteth forth for us the law of faith, crying: Bless the Lord, all ye works of the Lord.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 8 troparion 2`},label:`plain`},{text:`Having given birth to the Word of the Father through the divine Spirit, thou didst remain a virgin, O Birthgiver of God, who knewest not a man, transcending the laws of nature in thy birthgiving. Wherefore, rejoicing, we chant: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`A cornerstone not cut by hand O Virgin, * was cut from thee the unhewn mountain: * even Christ, Who hath joined together the disparate natures; * therefore rejoicing we magnify thee, * O Theotokos.`,tier:2,src:{file:`11-18.pdf`,locus:`p10 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`All thy trust didst thou place in the Master, O glorious martyr Romanus, enduring many and varied wounds; wherefore thou hast received ineffable glory and divine delight.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 9 troparion 1`},label:`plain`},{text:`Behold, instead of pain a torrent of sweetness hath been granted thee, O martyr Romanus, bearing a crown and wearing a robe dyed red in thine own blood. Like a fragrant and never-fading rose thou wast slain as a child for Christ's sake.`,tier:1,src:{file:`11-18.pdf`,locus:`p10 Ode 9 troparion 2`},label:`plain`},{text:`O Virgin, thou hast delivered mortals from the primal curse of our ancestors, and opened unto us the life of Eden by thy birthgiving, which transcendeth nature. Wherefore, in gladness we magnify thee, O Theotokos.`,tier:1,src:{file:`11-18.pdf`,locus:`p11 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`Exalted in the breadth of thy struggles, O wise martyr, thou didst destroy the snares of the enemy, discomfiting them, O all-glorious one; and having run well the divine course, thou didst reach the expanse of heaven, rejoicing. Wherefore, the Church, resplendent today in an abundance of piety, doth celebrate thy memorial, O blessed one, and crieth out to thee: Entreat Christ God, that He grant remission of sins unto those who with love honor thy holy memory.`,tier:1,src:{file:`11-18.pdf`,locus:`p4 Ode III sessional (Plato)`},label:`plain`,saint:`Plato`,sourceLabel:`Sessional Hymn of the holy martyr Plato, in Tone VIII.`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`Having trampled underfoot the wicked one by fasting, thou wast glorified by suffering, O martyr of Christ, having endured manfully with a perfected mind. Wherefore, thou hast been numbered among the choirs of martyrs and reached the everlasting kingdom. Joining chorus therein, be thou mindful of us who celebrate thy holy memory with faith.`,tier:1,src:{file:`11-18.pdf`,locus:`p5 Ode III sessional (Romanus)`},label:`glory`,saint:`Romanus`,sourceLabel:`Glory ..., Sessional Hymn of the holy martyr Romanus, in Tone IV`,spec_mel:`Having been lifted up ...`,tone:4},{text:`O Theotokos, fleeing to thy divine protection after God, * I humbly fall down and beseech thee: * Have mercy, O most pure one, * for my sins have submerged my being, * and trembling O Lady, I fear the torments to come, * O pure one, entreat thy Son, ** that I may be delivered from them.`,tier:2,src:{file:`11-18.pdf`,locus:`p5 Ode III sessional Theotokion`},type:`theotokion`,label:[`both_now`,`theotokion`],sourceLabel:`Both now ..., Theotokion, in Tone IV`,tone:4},{text:`She who in the latter days * gave birth in the flesh unto Thee O Christ, * Who wast begotten of the beginningless Father, * upon seeing Thee hanging upon the Cross, cried aloud: * “Woe is me, O Jesus, most beloved Christ! * How is it that Thou Who art glorified as God by the angels * dost now consent to be crucified by iniquitous men O my Son? ** I hymn Thee, O Thou Long-suffering One!”`,tier:2,src:{file:`11-18.pdf`,locus:`p5 Ode III sessional Stavrotheotokion`},type:`stavrotheotokion`,label:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`,label_inline:!0}],exapostilarion:{text:`In all thy ways thou didst tread the hard and divine path, ascending unto the expanse of the kingdom of heaven, O Plato, glory of martyrs, shining with the light of the incorruptible Trinity. Wherefore, partaking of endless glory, be thou mindful of those who honor thee.`,tier:1,src:{file:`11-18.pdf`,locus:`p11 Exapostilarion`},label:`plain`,sourceLabel:`Exapostilarion of the holy martyrs`,spec_mel:`By the Spirit in the sanctuary ...`},exapostilarion_closer:{text:`O Virgin Theotokos, I set forth thy protection as a truly invincible help and wall of defense and thee as a mediator before God, that I may be delivered from everlasting torment, O Lady, and through thee find a share in the kingdom, and in life incorruptible.`,tier:1,src:{file:`11-18.pdf`,locus:`p11 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}},liturgy:{order:[`troparion`,`kontakion`]}}]},"11-19":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`saint`,title:{text:`COMMEMORATION OF THE HOLY PROPHET OBADIAH COMMEMORATION OF THE HOLY MARTYR BARLAAM OF CAESAREA IN CAPPADOCIA`,tier:1,src:{file:`11-19.pdf`,locus:`p1 title`},sourceLabel:`THE 19th DAY OF THE MONTH OF NOVEMBER`},rank:`simple`,fekula_section:`2B`,oca_primary:!0,source_file:`11-19.pdf`,note:"A double commemoration under two title lines: the Prophet Obadiah and the Martyr Barlaam. 3 + 3 stichera, Simple rank, double service (Fekula 2B) by the encoding_rule_v2.md 1.1 waterfall; ODS vol. III has no 11-19 entry. Two canons, interleaved in print and stored whole. STORED AS ONE ENTRY, the saints told apart by `saint` on each item, as on 11-18. The two saints have separate troparia, so there is no entry-level troparion: each is stored where it is printed, in `troparia` (the martyr's at Vespers and Liturgy, the prophet's at Liturgy only). The kontakion is the martyr's; no kontakion of the prophet and no ikos are printed. No Glory at Lord I have cried, no aposticha at Vespers, and at Liturgy only the troparia and kontakion.",kontakion:{text:`Thou wast shown to be most amazing * in the fortitude whereby thou didst endure immolation, * offering thyself in sacrifice unto Christ as incense of sweet savor. * Having received a crown of honor, O Barlaam, ** do thou ever pray for us, O spiritual athlete.`,tier:2,src:{file:`11-19.pdf`,locus:`p7 Kontakion of the holy martyr`},saint:`Barlaam`,verified_sites:[{locus:`p7 after Ode VI`,tone:4},{locus:`p10 AT LITURGY`,tone:4}],sourceLabel:`Kontakion of the holy martyr, in Tone IV`,spec_mel:`Thou hast appeared ...`,tone:4},vespers:{order:[`lic_rubric`,`lic`,`lic_closer`,`lic_stavrotheotokion`,`troparia`],lic_rubric:{text:`On “Lord, I have cried ...,” 6 Stichera; 3 of the holy prophet, in Tone I:`,tier:1,src:{file:`11-19.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`As a splendid receptacle of the Spirit * and one illumined by Him, * O Obadiah of most divine vision, * thou wast enriched by the image of prophecy, * the foreknowledge of things to come, * and the knowledge of the truth. * Pray thou now, that He grant our souls ** peace and great mercy.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC 1`},label:`plain`,saint:`Obadiah`,tone:1,spec_mel:`O all-praised martyrs ...`},{text:`Of the primary traits * and essential proofs * wherewith God is represented * do the glorious and honorable prophets * partake as a gift secondarily * through communion and grace * when the Lord illumineth His favored ones ** with His effulgence.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC 2`},label:`plain`,saint:`Obadiah`,spec_mel:`O all-praised martyrs ...`},{text:`Full of never-waning light, * beholding glory which transcendeth * understanding and reason, * and standing before the Master of all, * thou wast a glorious prophet * and a divine herald of God. * Him do thou entreat, that He grant our souls ** peace and great mercy.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC 3`},label:`plain`,saint:`Obadiah`,spec_mel:`O all-praised martyrs ...`},{text:`Firmer than a pillar, * stronger than brass, * and mightier than iron wast thou; * for, when heated by fire, each of them doth disintegrate * and is straightway destroyed, * overcome by the force thereof; * but thine unwavering right hand, * outstretched over the burning coals, O all-wise one, ** triumphed most gloriously.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC 4`},label:`plain`,saint:`Barlaam`,sourceLabel:`And 3 of the holy martyr, in Tone IV`,spec_mel:`As one valiant among the martyrs ...`,tone:4},{text:`As though thou wast a priest * standing before God * and coming before Him, not with another's blood, * but with thine own most of all, O blessed one, * thou didst offer an incense of sweet savor * with thy martyr's hand, * not to demonic illusions, * but to Christ, the Savior and Master, ** Who reigneth forever.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC 5`},label:`plain`,saint:`Barlaam`,spec_mel:`As one valiant among the martyrs ...`},{text:`A priest who offereth * and a lamb which is offered: * both do we joyously call thee, * O all-praised one; * for thou wast offered as both * in the fire of torment * as an unblemished sacrifice to God. * Him do thou entreat, that He save those ** who ever honor thy most glorious memory.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC 6`},label:`plain`,saint:`Barlaam`,spec_mel:`As one valiant among the martyrs ...`}],lic_closer:{text:`Bedew my mind * with showers of the Most holy Spirit, O most pure one, * who ineffably gaveth birth unto Christ * the drop Who with His compassions washeth away * the countless iniquities of mankind; * dry up the upwelling of my passions, * and grant unto me a torrent * of ever-living nourishment, ** by thy supplications.`,tier:2,src:{file:`11-19.pdf`,locus:`p1 LIC Glory/Both now Theotokion`},type:`theotokion`,sourceLabel:`Glory ..., Both now ..., Theotokion, in Tone IV`,tone:4},lic_stavrotheotokion:{text:`Upon beholding Thee, the Lamb and Shepherd, upon the Tree, * the ewe-lamb who gave birth to Thee * lamented and maternally cried aloud to Thee: * “O my Son most desired, * How is it that Thou art suspended upon the Tree of the Cross, * O Long-suffering One? * How have Thy hands and feet * been pierced with nails by the iniquitous, O Word! ** And how hast Thou shed Thy blood, O Master?`,tier:2,src:{file:`11-19.pdf`,locus:`p2 LIC Stavrotheotokion`},type:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`,label_inline:!0},troparia:[{text:`In his sufferings, Thy martyr Barlaam O Lord, * received an imperishable crown from Thee, our God; * for, possessed of Thy might, * he set at naught the tyrants and crushed the feeble audacity of the demons. ** By his supplications save Thou our souls.`,tier:2,src:{file:`11-19.pdf`,locus:`p2 Troparion of the holy martyr`},label:`plain`,saint:`Barlaam`,sourceLabel:`Troparion of the holy martyr, in Tone IV`,tone:4}]},matins:{order:[`canon_rubric`,`canons`,`sessional_ode3`,`kontakion`,`exapostilarion`,`exapostilarion_closer`],canon_rubric:{text:`One canon from the Oktoechos, and two canons of the saints.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Canon rubric`}},canons:[{title:`Canon of the holy prophet, the acrostic whereof is: “I hymn the glory of the clairvoyant Obadiah,” the composition of Theophanes, in Tone V:`,composer:`Theophanes`,acrostic:`I hymn the glory of the clairvoyant Obadiah`,tone:5,odes:{1:{irmos:{text:`Unto God the Savior * Who made His people pass dryshod through the sea, * but drowned Pharaoh with all his host, * unto Him alone let us sing: * For He hath been glorified.`,tier:2,src:{file:`11-19.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Standing now as a prophet before God the Savior, entreat Him with boldness, that He enlighten with rays of light those who with faith call thee blessed, O divinely inspired one.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`He who manifestly foreknoweth all things, beholding the untroubled and radiant purity of thy heart, O blessed one, appointed thee a God-pleasing prophet.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 2`},label:`plain`},{text:`Truly beholding visions revealed to thee by God, thou didst proclaim the impiety and cruel perniciousness of thy brethren and their just destruction, O blessed one.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 3`},label:`plain`},{text:`Saved by thy seedless birthgiving, O pure Theotokos, we beseech thee: from the temptations of the world do thou deliver us, who together offer a hymn of victory unto thee.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`By the power of Thy Cross, O Christ, * do Thou make steadfast mine understanding, * that I may hymn and glorify ** Thy saving Ascension.`,tier:2,src:{file:`11-19.pdf`,locus:`p3 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Like the waters of a mystic river dist thou appear, issuing forth from the abyss of the gifts of the Spirit, O herald of God.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 troparion 1`},label:`plain`},{text:`Thou wast put forth by the will and providence of God to proclaim things to come, O right glorious one.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 troparion 2`},label:`plain`},{text:`Illumined by the divine and heavenly light, O all-blessed one, thou didst proclaim the future salvation of the Gentiles.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`The Word made His abode within thee, O Virgin Mother, and by thy mediation He doth save those who know thee to be the Theotokos, O all-immaculate one.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`I have heard report of the mighty deed * of Thy Cross, O Lord, * how Paradise was opened thereby, and I cried: * Glory to Thy power, O Lord.`,tier:2,src:{file:`11-19.pdf`,locus:`p5 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having cleansed thy soul of the passions beforehand, receiving the grace of prophecy through the Holy Spirit, thou didst cry out: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 troparion 1`},label:`plain`},{text:`The prophet Obadiah, illumined by the brilliance of the lightning of the Bestower of light, hath enlightened us to cry to Thee: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 troparion 2`},label:`plain`},{text:`Thou wast revealed to be like a wedding attendant of the Church, the Bride of Christ, O all-blessed one, proclaiming that the Savior would come forth from Zion, to Whom we cry aloud: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 troparion 3`},label:`plain`},{text:`In a divine manner thou hast given birth, O pure one, unto the co-beginningless and everlasting Word of the Father, to Whom we cry: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`Waking at dawn, * we cry unto Thee, O Lord: * Save us, for Thou art our God; * we know none other besides Thee.`,tier:2,src:{file:`11-19.pdf`,locus:`p5 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Rising early unto the Lord, O all-praised one, thou didst receive the gift of the most holy Spirit from heaven.`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 5 troparion 1`},label:`plain`},{text:`Having acquired the godly life of Him Who helped thee, thou wast deemed worthy to behold Him Who is understood to be invisible.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 troparion 2`},label:`plain`},{text:`Light shone upon thee, in that thou art a prophet, O all-blessed one, and gladness was given thee as a bride.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 troparion 3`},label:`plain`},{text:`The supremely divine One, Who created all things by His will, was formed from thee after our kind, O most pure one.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`The abyss hath encompassed me, * the sea monster hath become my grave; * but I cried unto Thee, * the Lover of mankind, * and Thy right hand saved me, O Lord.`,tier:2,src:{file:`11-19.pdf`,locus:`p6 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`By the power of the divine Spirit thou didst behold things to come, receiving images of divine revelations as in a mirror through the splendor of thy soul.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 6 troparion 1`},label:`plain`},{text:`By thy supplications entreat the Lord, O all-blessed prophet, asking that He grant forgiveness of sins unto those who with faith keep thy memory.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 6 troparion 2`},label:`plain`},{text:`Take pity on Thy servants and grant them forgiveness of transgressions, O Lover of mankind, for Thy prophet who proclaimed Thee beforehand to the world doth entreat Thee.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 6 troparion 3`},label:`plain`},{text:`He Who beareth up all things by His word and divine power was borne in thine embrace, O thou who knewest not wedlock. Him do thou now beseech, that our souls be saved.`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`The children were saved * in the burning furnace, * chanting: Blessed art Thou * O God of our fathers.`,tier:2,src:{file:`11-19.pdf`,locus:`p7 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Truly supra-natural is the glory of Thy prophets, O blessed God of our fathers!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 troparion 1`},label:`plain`},{text:`Having been deemed worthy to dwell with God, thou dost chant: Blessed is the God of our fathers!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 troparion 2`},label:`plain`},{text:`Thou revealest Thy divine grace in Thy prophets, O blessed God of our fathers.`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 troparion 3`},label:`plain`},{text:`Delivered by thy birthgiving, O most pure Virgin, we chant: Blessed is the God of our fathers!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`Unto God the Son, Who was begotten of the Father before the ages * and was incarnate of a Virgin Mother in these last times, * give praise, O ye priests, ** and supremely exalt Him, O ye people, throughout all ages.`,tier:2,src:{file:`11-19.pdf`,locus:`p8 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Enlightened by God, the prophets proclaim beforehand knowledge of things to come, crying aloud with divine wisdom: Ye priests hymn; ye people supremely exalt God throughout all ages!`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 troparion 1`},label:`plain`},{text:`Illumined with divine beams of light, thou didst enlighten those who were in darkness like a ray in the deep, O herald of God, crying: Ye priests hymn; ye people supremely exalt God throughout all ages!`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 troparion 2`},label:`plain`},{text:`Thou hast revealed Thyself as of one nature with us, O Thou Who art consubstantial with Thy Father in the divine Essence, having become incarnate of the Mother, who kneweth not man. Wherefore, we hymn Thee, O Christ, and bless Thee throughout all ages.`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`O thou who art God’s Mother transcending mind and word, * who ineffably in time hast given birth unto the Timeless One, * thee do we the faithful * with one accord magnify.`,tier:2,src:{file:`11-19.pdf`,locus:`p8 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Adorned with divine discourse and activity, and having taken wing in the Spirit, O wondrous prophet, thou wast deemed worthy to behold things to come.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 troparion 1`},label:`plain`},{text:`O glorious one, who dwellest where the choirs of the prophets and the splendors of the saints are, entreat the Lord to save those who praise thee with faith.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 troparion 2`},label:`plain`},{text:`Cleaving wholly unto God with fervor, thou didst converse in a pure manner through divine revelations, wherein thou dost now delight, O all-blessed one.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 troparion 3`},label:`plain`},{text:`We hymn thee, the candle-stand of the Light and the tablet of grace, O pure one, and we magnify thee, who received the incarnate Word ..`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}},{title:`Canon of the holy martyr, the acrostic whereof is: “I hymn thy pangs of endurance, O Barlaam,” the composition of Theophanes, in Tone IV:`,composer:`Theophanes`,acrostic:`I hymn thy pangs of endurance, O Barlaam`,tone:4,odes:{1:{irmos:{text:`I hymn Thee, O Lord my God, * for Thou hast led Thy people out of the bondage of Egypt, * and hast drowned in the waters * the chariots and the might of Pharaoh.`,tier:2,src:{file:`11-19.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Rendered luminous by the splendors of thy contest, O Barlaam, do thou preserve us by thy supplications, for with faith we honor thy sacred memory.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`With hymnody let the wondrous Barlaam be honored, who, with fame, quenched the fire of impiety by the divinely inspired fire of his reverence for God.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 2`},label:`plain`},{text:`Having contended for piety, O crown-bearer Barlaam, thou hast now been honored at the right hand of the Almighty with a crown of glory, as is meet.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 3`},label:`plain`},{text:`The Master gave thee strength against divers wounds, O all-blessed martyr; where-fore, thou didst vanquish the savagery of the godless.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 troparion 4`},label:`plain`},{text:`The ladder leading to heaven, which Jacob, thine ancestor, foresaw of old, hast thou truly been revealed to be, whereby the Word hath descended to us, O Virgin.`,tier:1,src:{file:`11-19.pdf`,locus:`p3 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`The bow of the mighty hath waxed feeble * and the weak have girded themselves with strength: * therefore is my heart established * in the Lord.`,tier:2,src:{file:`11-19.pdf`,locus:`p4 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The whole bond of thy body and the cohesion of thy members were broken; yet the strength of thy soul was preserved intact.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 troparion 1`},label:`plain`},{text:`Mightily showing forth the endurance of youth, O all-blessed one, thou didst right mightily endure the assaults of those who lacerated thy sides.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 troparion 2`},label:`plain`},{text:`Who can rightly praise the mighty, powerful and tranquil understanding of thy thought, as is meet, O all-blessed one?`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`In the hypostatic Life which appeared unto us through thy womb, O most pure Bride of God, hath the corruption of death been brought to an end.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Proclaiming the advent of Thine appearance on earth, O Christ God, * the prophet cried aloud with gladness: * Glory to Thy power, O Lord!`,tier:2,src:{file:`11-19.pdf`,locus:`p5 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Spurning the foolish speech of the rhetors and accepting the true teaching of the apostles, O glorious one, thou wast a true witness.`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 troparion 1`},label:`plain`},{text:`Thou didst withstand the fire and torments even unto death for Christ, O patient-hearted one, chanting aloud: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 troparion 2`},label:`plain`},{text:`Constrained by the most powerful fervor, O all-blessed one, thou didst trample deception underfoot with godly wisdom, chanting: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 troparion 3`},label:`plain`},{text:`The Incorporeal One, incarnate of the Virgin, hath come to us on earth; wherefore, with faith we cry aloud: Glory to Thy power, O Lord!`,tier:1,src:{file:`11-19.pdf`,locus:`p5 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Thou Who hast caused the light to shine, * who hast made bright the dawn and revealed the day; * glory be to Thee, glory be to Thee, * O Jesus Thou Son of God.`,tier:2,src:{file:`11-19.pdf`,locus:`p6 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Christ hath shown us a witness to His own sufferings, who crieth out: Glory to Thee! Glory to Thee, O Jesus, Thou Son of God!`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 troparion 1`},label:`plain`},{text:`For thy great endurance is a reward given, and a wreath of victory woven for thee who criest: Glory to Thee! Glory to Thee, O Jesus, Thou Son of God!`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 troparion 2`},label:`plain`},{text:`With the darts of thy words thou didst penetrate the hearts of the foe, crying: Glory to Thee! Glory to Thee, O Jesus, Thou Son of God!`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 troparion 3`},label:`plain`},{text:`Understanding thee to be a holy mountain and the tabernacle of the Most High, O Virgin, we cry aloud: Glory to thee, O Theotokos, our hope!`,tier:1,src:{file:`11-19.pdf`,locus:`p6 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`Prefiguring Thy three-day burial * prophet Jonah praying in the belly of the sea-monster cried aloud: * Deliver me from corruption * O Jesus Thou King of hosts.`,tier:2,src:{file:`11-19.pdf`,locus:`p6 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Let the faces of the demons be smitten with the martyr's burned right hand; let the hearts of the faithful leap up, and let the choirs of the incorporeal ones be radiantly glad!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 6 troparion 1`},label:`plain`},{text:`The conquests and victories of thy good struggles and the athletic contests of those who watched are adorned, O chosen and radiant triumph of the firstborn.`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 6 troparion 2`},label:`plain`},{text:`Arise now, ye good artists! Adorn ye the image of the martyr with your goodly skills, manifestly depicting therein the Judge of the contest.`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 6 troparion 3`},label:`plain`},{text:`Delivered by thy birthgiving from the ancient curse and the bitter condemnation of death, our first mother rejoiceth in thee, O all-praised Mother of God.`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`O God of our fathers, put us not to shame, * but grant that with boldness we may sing to Thee: * 'O God of our fathers, Blessed art Thou'.`,tier:2,src:{file:`11-19.pdf`,locus:`p7 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`As an invincible martyr hast thou been deemed worthy to cry aloud to Christ with the choirs of the martyrs: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 troparion 1`},label:`plain`},{text:`With radiant lamps thou didst enter into the divine bridal chamber, O great martyr, crying out to Christ: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 troparion 2`},label:`plain`},{text:`Having acquired a right hand stronger than fire, as an intercessor at the right hand of thy Master thou criest out: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 troparion 3`},label:`plain`},{text:`Delivered by thy most pure birthgiving, we, the faithful, hymn thee, crying out unceasingly: Blessed is the Fruit of thy womb, O most pure one!`,tier:1,src:{file:`11-19.pdf`,locus:`p7 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`O all ye works of God and all creation, * bless ye the Lord, * ye venerable and humble of spirit * chant ye and supremely exalt Him throughout all ages`,tier:2,src:{file:`11-19.pdf`,locus:`p8 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou didst destroy all the armor of the enemy, O right glorious Barlaam, utterly consuming the deception of idolatry, crying aloud: Thee do we supremely exalt, O Christ, throughout all ages!`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 troparion 1`},label:`plain`},{text:`Adorned with magnificence, thou didst stand before Christ, O ever-memorable spiritual athlete, arrayed in fine linen empurpled with thy martyr's blood and hymning the Master throughout all ages.`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 troparion 2`},label:`plain`},{text:`Enkindled with the fire of piety, thou didst utterly consume all the illusions of the demons as if they were thorns, crying aloud: Thee do we exalt supremely, O Christ, throughout all ages!`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 troparion 3`},label:`plain`},{text:`Those who with faith call thee blessed, O all-immaculate one, are blessed by the Lord; for thou hast given birth unto the Master Who blesseth creation, Whom we supremely exalt, O pure one, throughout all ages.`,tier:1,src:{file:`11-19.pdf`,locus:`p8 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`A cornerstone not cut by hand O Virgin, * was cut from thee the unhewn mountain: * even Christ, Who hath joined together the disparate natures; * therefore rejoicing we magnify thee, * O Theotokos.`,tier:2,src:{file:`11-19.pdf`,locus:`p9 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The law of praise is overturned by the magnificence of thy struggles. Christ, the only Master, knoweth to glorify thee with divine radiance. Him do thou earnestly entreat on behalf of those who hymn thee.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 troparion 1`},label:`plain`},{text:`Having brought thy whole self to the Lord as a living sacrifice, thou wast revealed to be a fellow heir and sharer in His kingdom; and, rejoicing, thou now reignest with Him, O ever-memorable one.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 troparion 2`},label:`plain`},{text:`The godly martyr, having arrayed himself against sword, fire and torments, shedding his blood for the love of Thee, even unto death, O Savior, doth delight, re-ceiving immortality from Thee, O Lover of mankind.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 troparion 3`},label:`plain`},{text:`Rejoicing, I set thee forth as the helper of the world, the Virgin Mother of God, the intercessor and salvation of all my life; for having given birth unto God, thou art able to save those who hymn thee.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],sessional_ode3:[{text:`The great Obadiah, having acquired a mind luminous with divine splendor, spoke through the Holy Spirit, proclaiming things to come. Honoring him today with pious mind, we celebrate his sacred memory which enlightened men's hearts.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode III sessional (prophet)`},label:`plain`,saint:`Obadiah`,sourceLabel:`Sessional Hymn of the holy prophet, in Tone I`,spec_mel:`Thy tomb, O Savior ...`,tone:1},{text:`Let the glorious Barlaam, who quenched the flame of impiety and set the hearts of the faithful afire with the dew of the knowledge of God, now be faithfully honored with divine hymns; for he put to shame the deception of idolatry and, having taken the crown of victory, asketh remission of sins for all.`,tier:1,src:{file:`11-19.pdf`,locus:`p4 Ode III sessional (martyr)`},label:`glory`,saint:`Barlaam`,sourceLabel:`Glory ..., Sessional Hymn of the holy martyr, in Tone IV`,spec_mel:`Having been lifted up ...`,tone:4},{text:`He that sitteth upon the throne of the cherubim * and abideth in the bosom of the Father * sat in thy womb as upon a throne, O Lady; * for, being truly God incarnate, * He reigneth over all nations, * and with understanding we now chant to Him. * Him do thou also entreat, ** that thy servants be saved.`,tier:2,src:{file:`11-19.pdf`,locus:`p4 Ode III sessional Theotokion`},type:`theotokion`,label:[`both_now`,`theotokion`],sourceLabel:`Both now ..., Theotokion, in Tone IV`,tone:4},{text:`She who in the latter days * gave birth in the flesh unto Thee O Christ, * Who wast begotten of the beginningless Father, * upon seeing Thee hanging upon the Cross, cried aloud: * “Woe is me, O Jesus, most beloved Christ! * How is it that Thou Who art glorified as God by the angels * dost now consent to be crucified by iniquitous men O my Son? ** I hymn Thee, O Thou Long-suffering One!”`,tier:2,src:{file:`11-19.pdf`,locus:`p5 Ode III sessional Stavrotheotokion`},type:`stavrotheotokion`,label:`stavrotheotokion`,sourceLabel:`Stavrotheotokion`,label_inline:!0}],exapostilarion:{text:`Dance thou and join chorus, O prophet Obadiah, beholding the fulfillment of thy words. And, standing before the Trinity, remember those who honor and keep thy radiant memory, O all-blessed one.`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Exapostilarion`},label:`plain`,saint:`Obadiah`,spec_mel:`When the disciples beheld ...`,sourceLabel:`Exapostilarion of the holy prophet`,provenance_note:`The Spec. Mel. line closes with a hyphen where every other prints a colon: “When the disciples beheld ...”- (p9).`},exapostilarion_closer:{text:`Seeing God the Word crucified, Who ineffably issued forth from thy most pure womb, O Virgin Mother, thou didst cry aloud: Glory to Thine ineffable dispensation, O my Savior, whereby Thou hast saved Thy world!`,tier:1,src:{file:`11-19.pdf`,locus:`p9 Exapostilarion Theotokion`},type:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}},liturgy:{order:[`troparia`,`kontakion`],troparia:[{text:`Celebrating the memory of Thy prophet Obadiah, O Lord, * through him we entreat Thee: ** Save Thou our souls!`,tier:2,src:{file:`11-19.pdf`,locus:`p10 Troparion of the holy prophet at Liturgy`},label:`plain`,saint:`Obadiah`,sourceLabel:`Troparion of the holy prophet, in Tone II`,tone:2},{text:`In his sufferings, Thy martyr Barlaam O Lord, * received an imperishable crown from Thee, our God; * for, possessed of Thy might, * he set at naught the tyrants and crushed the feeble audacity of the demons. ** By his supplications save Thou our souls.`,tier:2,src:{file:`11-19.pdf`,locus:`p10 Troparion of the holy martyr at Liturgy`},label:`plain`,saint:`Barlaam`,sourceLabel:`Troparion of the holy martyr, in Tone IV`,tone:4}]}}]},"11-20":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`forefeast`,feast_ref:`entrance_theotokos`,title:{text:`FOREFEAST OF THE ENTRANCE OF THE MOST HOLY THEOTOKOS COMMEMORATION OF OUR VENERABLE FATHER GREGORY THE DECAPOLITE & OF OUR FATHER AMONG THE SAINTS PROCLUS, ARCHBISHOP OF CONSTANTINOPLE`,tier:1,src:{file:`11-20.pdf`,locus:`p1 title`},sourceLabel:`THE 20th DAY OF THE MONTH OF NOVEMBER`},rank:`simple`,fekula_section:`2G1`,oca_primary:!0,source_file:`11-20.pdf`,note:'ONE printed service for the Forefeast of the Entrance and two saints (Gregory the Decapolite, Proclus of Constantinople): one entry, every item tagged with `saint` ("forefeast", "Gregory", "Proclus", or "Gregory and Proclus" for the shared Troparion of the holy fathers). 3 stichera of the forefeast and 3 of St. Gregory at Lord I have cried; St. Proclus has the Vespers aposticha. No Polyeleos and no Great Doxology: stored Simple, Fekula 2G1 (weekday service in a forefeast), by the encoding_rule_v2.md 1.1 waterfall; ODS vol. III has no 11-20 entry. THREE canons, interleaved in print, stored whole. Two troparia and three kontakia, each printed at several sites, are stored at every site in positional lists and NOT as entry-level canonical fields. The `appendix` holds the "Be it known" order for a Sunday and two troparia printed only there (St. Gregory, Tone III; St. Proclus, Tone IV). kind is "forefeast" because the title leads with it; the saints share the entry.',vespers:{order:[`lic_rubric`,`lic`,`lic_closer`,`lic_closer_alternate_rubric`,`aposticha_rubric`,`aposticha`,`aposticha_closer`,`troparia`],lic_rubric:{text:`On “Lord, I have cried ...,” 6 Stichera: 3 of the forefeast, in Tone I:`,tier:1,src:{file:`11-20.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`The lamp-bearing virgins * who with splendor accompany the Ever-virgin * truly prophesy the future in spirit; * for, in that she is the temple of God, * the Theotokos is led as a child into the temple ** with virginal glory.`,tier:2,src:{file:`11-20.pdf`,locus:`p1 LIC 1`},label:`plain`,saint:`forefeast`,tone:1,spec_mel:`Joy of the ranks of heaven ...`},{text:`The Theotokos, the right glorious fruit of the holy promise, * is truly revealed to the world; * she who surpasseth all things * is piously accompanied into the temple of God * fulfilling the vow of her parents, ** and preserved by the divine Spirit.`,tier:2,src:{file:`11-20.pdf`,locus:`p1 LIC 2`},label:`plain`,saint:`forefeast`,spec_mel:`Joy of the ranks of heaven ...`},{text:`O Virgin, having been faithfully nurtured with heavenly bread * in the temple of the Lord, * thou hast given birth unto the Word, the Bread of life for the world. * To Him wast thou mystically betrothed beforehand by the Spirit, * in that thou art the chosen and all-immaculate temple, ** betrothed to God the Father.`,tier:2,src:{file:`11-20.pdf`,locus:`p1 LIC 3`},label:`plain`,saint:`forefeast`,spec_mel:`Joy of the ranks of heaven ...`},{text:`Dwelling with gladness in the mansions of heaven, O father, * and standing boldly with the angels * before the throne of the Lord, * pray thou that He grant * release from sins and the passions ** unto those who on earth celebrate thy memory.`,tier:2,src:{file:`11-20.pdf`,locus:`p1 LIC 4`},label:`plain`,saint:`Gregory`,sourceLabel:`And 3 Stichera of the venerable one, in the same melody`},{text:`Having hewn down the tares of the passions * with the scythe of prayer, O father Gregory, * and having worked the ground of thy soul with the plough of abstinence, * thou didst scatter the seeds of piety upon it, * thereby producing for us ** the fruits of healing.`,tier:2,src:{file:`11-20.pdf`,locus:`p1 LIC 5`},label:`plain`,saint:`Gregory`},{text:`We call thee a receptacle of the virtues, O venerable one, * a friend of silence, a keeper of vigils, * a model of chastity, * an abode of prayer which cannot be taken away, * a treasury of miracles, ** who prayest for those who honor thee, O Gregory.`,tier:2,src:{file:`11-20.pdf`,locus:`p1 LIC 6`},label:`plain`,saint:`Gregory`}],lic_closer:{text:`Today the Theotokos, the temple which contained God, is brought into the temple of the Lord, and Zachariah receiveth her; today the Holy of holies rejoiceth, and the choir of the angels doth mystically keep festival. And we, celebrating with them today, cry out with Gabriel: Rejoice, O thou who art full of grace! The Lord Who hath great mercy, is with thee!`,tier:1,src:{file:`11-20.pdf`,locus:`p1 LIC Glory/Both now of the forefeast`},type:`of_the_feast`,saint:`forefeast`,sourceLabel:`Glory ..., Both now ..., of the forefeast, in Tone IV`,tone:4},lic_closer_alternate_rubric:{text:`But if it be Friday evening: Glory ..., of the forefeast; Both now ..., Dogmaticon in the tone of the week.`,tier:1,src:{file:`11-20.pdf`,locus:`p1 If it be Friday evening`}},aposticha_rubric:{text:`On the Aposticha, these Stichera of Saint Proclus, in Tone IV:`,tier:1,src:{file:`11-20.pdf`,locus:`p2 Aposticha rubric`}},aposticha:[{text:`With the splendor of thy dogmas * and the beauty of thy life * thou didst adorn the hierarchy with piety, * O ever-memorable Proclus, * showing thyself to be truly a pillar of the Church, * illumining all with thy words. * Wherefore, we call thee blessed, * and in psalms and hymns ** celebrate thy most honored memory.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Aposticha 1`},label:`plain`,tone:4,saint:`Proclus`,spec_mel:`Thou hast given a sign ...`},{text:`Precious in the sight of the Lord * is the death of His saints.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`With splendor thou didst teach and with divine wisdom thou didst proclaim * the Theotokos, the most pure maiden, * who gave birth to the Creator and Master, * the Son and Word of the Father, * Who was begotten before all ages, * and in latter days of His own will became a man for our sake, * remaining immutable in His essence; * and thou didst put to shame Nestorius, ** the impious and most foolish one.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Aposticha 2`},label:`plain`,saint:`Proclus`,spec_mel:`Thou hast given a sign ...`},{text:`Thy priests shall be clothed with righteousness, * and thy righteous shall rejoice.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`O ever-memorable one, * thou didst draw forth the golden waters * of the wise preacher of God * whose successor thou wast, * and wast shown to be a seat of piety as well, * making steadfast the flock of Christ * with thy teaching of the truth; * and his most precious and all-honored relics ** didst thou give to the Church likened to imperial ornaments.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Aposticha 3`},label:`plain`,saint:`Proclus`,spec_mel:`Thou hast given a sign ...`}],aposticha_closer:{text:`Come, all ye faithful, let us praise her who alone is immaculate, who was proclaimed by the prophets and is led into the temple: her who before all ages was called to be a mother, and in the latter times was revealed to be the Theotokos. Through her supplications, O Lord, grant Thy peace and great mercy unto us.`,tier:1,src:{file:`11-20.pdf`,locus:`p2 Aposticha Glory/Both now of the forefeast`},type:`of_the_feast`,saint:`forefeast`,sourceLabel:`Glory ..., Both now ..., of the forefeast, in Tone IV`,tone:4},troparia:[{text:`O God of our fathers, * ever deal with us according to Thy meekness. * Take not Thy mercy from us, * but by the prayers of these saints ** direct our life in peace.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Troparion of the holy fathers`},label:`plain`,saint:`Gregory and Proclus`,sourceLabel:`Troparion of the holy fathers, in Tone IV`,tone:4},{text:`Anna now beforehand doth betroth joy unto all, * bringing forth the only Ever-virgin as a fruit assuaging grief, * and today bringeth her, rejoicing, * into the temple of the Lord, in fulfillment of her promise. ** For she is the pure Mother, the temple of God the Word.`,tier:2,src:{file:`11-20.pdf`,locus:`p2 Troparion of the forefeast`},label:[`glory`,`both_now`,`of_the_feast`],saint:`forefeast`,sourceLabel:`Glory ..., Both now ..., that of the forefeast, in Tone IV`,tone:4}]},matins:{order:[`troparia`,`troparia_closing_rubric`,`sessional_1`,`sessional_2`,`canon_rubric`,`canons`,`kontakia_ode3`,`sessional_ode3`,`kontakia_ode6`,`exapostilarion`,`exapostilarion_closer`,`aposticha_rubric`,`aposticha`,`aposticha_closer`],troparia:[{text:`Anna now beforehand doth betroth joy unto all, * bringing forth the only Ever-virgin as a fruit assuaging grief, * and today bringeth her, rejoicing, * into the temple of the Lord, in fulfillment of her promise. ** For she is the pure Mother, the temple of God the Word.`,tier:2,src:{file:`11-20.pdf`,locus:`p3 Troparion of the forefeast at God is the Lord`},label:`of_the_feast`,saint:`forefeast`,repeat:2,sourceLabel:`On “God is the Lord ...,” the Troparion of the forefeast, in Tone IV`,tone:4},{text:`O God of our fathers, * ever deal with us according to Thy meekness. * Take not Thy mercy from us, * but by the prayers of these saints ** direct our life in peace.`,tier:2,src:{file:`11-20.pdf`,locus:`p3 Troparion of the holy fathers at God is the Lord`},label:`glory`,saint:`Gregory and Proclus`,sourceLabel:`Glory ..., of the holy fathers, in Tone IV`,tone:4}],troparia_closing_rubric:{text:`Both now ..., of the forefeast.`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Both now, of the forefeast`}},sessional_1:[{text:`Before thy conception thou wast dedicated to God, O pure one, and, having been born on earth, thou hast now been brought to Him, fulfilling thy parents' vow; and given over with radiant lamps in the temple of God, as a divine temple pure from thine infancy, thou wast shown to be the receptacle of the unapproachable and divine Light. Truly great is thine arrival, O only Bride of God and Ever-virgin!`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Sessional 1`},label:`plain`,saint:`forefeast`,sourceLabel:`After the 1st chanting of the Psalter, the Sessional Hymn, in Tone IV`,spec_mel:`Joseph marveled ...`,tone:4},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Sessional 1 repeat device`},label:[`glory`,`both_now`]}],sessional_2:[{text:`The temple of God, the greatly honored chamber, with gladness cometh forth with radiant lamps to the temple of God to take up her abode therein. Zachariah rejoiceth in her, clearly perceiving the revelation of the sacred prophets fulfilled; and he is glad and hymneth the forefeast with song: Joy precedeth thine entry, O maiden, Virgin and Mother!`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Sessional 2`},label:`plain`,saint:`forefeast`,sourceLabel:`After the 2nd chanting of the Psalter, the Sessional Hymn, in the same melody`},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Sessional 2 repeat device`},label:[`glory`,`both_now`]}],canon_rubric:{text:`Canon of the forefeast, with 6 Troparia, including the Irmos; and those of the saints, with 4 Troparia each.`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Canon rubric`}},canons:[{title:`Canon of the forefeast, the acrostic whereof is the Greek alphabet, through ODE VII (ODE VIII with its own Stichoi, ODE IX is the composition of Joseph), in Tone IV:`,tone:4,odes:{1:{irmos:{text:`I shall open my mouth, * and be filled with the Spirit, * and utter discourse to the Queen and Mother; * and be seen radiantly keeping festival, * joyfully praising her wonders.`,tier:2,src:{file:`11-20.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The all-holy and immaculate one cometh forth to make her abode within the Holy of holies, that she may become the sanctified temple of our Most holy God; and virgin maidens precede her.`,tier:1,src:{file:`11-20.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`The pre-eternal counsel of our pre-eternal God cometh to fulfillment now that thou, O all-immaculate Lady, dost come forth to dwell in the Holy of holies, as the abode of the Word.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 2`},label:`plain`},{text:`Thy godly parents lead thee, who art to become the Mother of God, into the Holy of holies, to make thy habitation there, and thereby fulfill the promise they made when they offered up entreaty, O most pure one.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 3`},label:`plain`},{text:`O Lady, strengthen thou the weakness of my heart and make it steadfast, for it hath been shaken by the passions, that with faith and love I may call thee blessed, who art the ever-blessed and all-immaculate one.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 4`},label:`plain`}]},3:{irmos:{text:`O Theotokos, thou living and plentiful fount, * establish in spiritual fellowship those who sing hymns to thee, * and in thy divine glory * grant them crowns of glory.`,tier:2,src:{file:`11-20.pdf`,locus:`p5 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The virgin maidens who undertake to bear candles with splendor prefigure what is to come; for from her the enlightenment of knowledge will be born, Who looseth the darkness of deception.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 1`},label:`plain`},{text:`Anna of old, filled with divinely wise zeal, fulfilleth her vow and escorteth to the sanctuary thee, her most sacred offspring, who art to give birth unto God, O most immaculate one.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 2`},label:`plain`},{text:`The sun spread forth its rays, beholding the radiant cloud stretched forth at the behest of God within the Holy of holies, from whence remission will rain forth upon the stony passions.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 3`},label:`plain`},{text:`Having made His abode within thee in His tender compassion, O all-immaculate and pure one, God deifieth me who was seduced aforetime by the deception of the serpent and corruption; and hath again given me the food of incorruption.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 4`},label:`plain`}]},4:{irmos:{text:`Perceiving the profound counsel of God, * that the incarnation of Thee the Most High, * will be from a Virgin, * the prophet Habbakuk cried aloud: * Glory to Thy power, O Lord!`,tier:2,src:{file:`11-20.pdf`,locus:`p7 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Sacred tongues proclaimed thee beforehand to be the dwelling of Him Who is infinite in nature, O pure one. Wherefore, choirs of virgins accompany thee to the Holy of holies, bearing lamps.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode 4 troparion 1`},label:`plain`},{text:`Joachim and Anna won glory, walking and bearing thee with gladness into the holy temple, O most holy temple of God, pure and all-immaculate Lady.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode 4 troparion 2`},label:`plain`},{text:`The sentence pronounced upon our ancestors hath been annulled; for, lo! a branch hath sprung forth which shall bear for us the incorrupt cluster Who shall bring the wine of gladness unto the ends of the earth.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode 4 troparion 3`},label:`plain`},{text:`The Word, the Creator, finding thee alone to be all-immaculate, made His abode within thy womb, accomplishing our salvation through grace, O most pure one, in His ineffable wisdom.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode 4 troparion 4`},label:`plain`}]},5:{irmos:{text:`All creation stands in awe of thy divine glory; * for thou, O Virgin who hast not known wedlock, * didst contain within thy womb the God of all, * and gave birth to the timeless Son, * bestowing peace, upon all who hymn thee.`,tier:2,src:{file:`11-20.pdf`,locus:`p8 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Let the clouds drop down righteousness today, for in the noetic sky of the temple of God, the divine cloud is spread out letting drop the Sweetness which taketh away all bitterness from our souls.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 5 troparion 1`},label:`plain`},{text:`Strange is thy conception, strange thy nativity, O most pure Virgin, strange thy coming forth and thine entering of the holy place, and strange are Thy most glorious works, past all telling and understanding.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 5 troparion 2`},label:`plain`},{text:`The all-holy Spirit wholly sanctified thee who abode within the temple and wast fed with heavenly food, O most beauteous Bride of the Father, for Whose sake thou didst become the Mother of the Word.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 3`},label:`plain`},{text:`Setting all my hope on thee, O maiden, I flee to thy compassions. Show forth my fallen soul to be untouched by the malice of the demons and unweakened by the floods of pleasures.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 4`},label:`plain`}]},6:{irmos:{text:`Celebrating the divine and solemn feast * of the Mother of God * O ye divinely wise, * let us come, clapping our hands, * and glorify God who was born of her.`,tier:2,src:{file:`11-20.pdf`,locus:`p10 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Strengthened by the grace of God, the parents of the divine Virgin lovingly surrender her, like a pure dove, to be raised in the Holy of holies.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 1`},label:`plain`},{text:`Lighting lamps, O pure one, the maidens, dancing, radiantly accompany thee to the temple of God, for thou art to receive the Light Who proceedeth from the Light.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 2`},label:`plain`},{text:`A palace full of glory, the great proclamation of the prophets, the holy throne, is led into the Holy of holies, making herself ready for the King of all.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 3`},label:`plain`},{text:`I hymn thy conception, O maiden, I also hymn thine ineffable nativity; and I likewise hymn thy protection, whereby we who flee to thy serenity are delivered from all harm.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 4`},label:`plain`}]},7:{irmos:{text:`Refusing to worship created things * in place of the Creator, * the divinely wise youths bravely trampled down the threatening fire * and rejoicing they sang aloud: * O supremely hymned Lord and God of our Fathers, Blessed art Thou.`,tier:2,src:{file:`11-20.pdf`,locus:`p11 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The holy temple received thee as a radiant sun, shining forth with the radiance of salvation upon all the ends of the earth, O pure Virgin, who shalt contain the Son of God.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 7 troparion 1`},label:`plain`},{text:`Let us all clap our hands, beholding her who kneweth not wedlock bearing the images of deliverance; for by the hand of an angel, she who shall ineffably give birth for us to the Bread of life is fed.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 7 troparion 2`},label:`plain`},{text:`All the souls of the righteous beneath the earth proclaimed thee, O golden dove, and they declare thee to be her who beareth the calm which shall put an end to the noetic deluge wherefore she rejoiceth with piety in the Holy of holies.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 7 troparion 3`},label:`plain`},{text:`In that thou art beautiful, thou hast given birth to the Comely One Who restoreth our ugliness to its pristine beauty, O all-immaculate maiden. To Him do we chant: O Lord God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 4`},label:`plain`}]},8:{irmos:{text:`Hearken, O pure Virgin maiden, * that Gabriel may tell thee the true counsel of the Most High of old. * Make ready to receive the Godhead; * for through thee the Infinite One hath come to dwell among mankind. * Wherefore, rejoicing, I cry aloud: * Bless the Lord, all ye works of the Lord!`,tier:2,src:{file:`11-20.pdf`,locus:`p13 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`“Hearken and understand, O wise elder,” Anna saith to Zachariah through divine counsel; “Accept the pure maiden whom we have conceived, with valiant soul; for her sake shall deliverance come to pass. Let us lead her into the holy temple, crying aloud: Bless the Lord, all ye works of the Lord!”`,tier:1,src:{file:`11-20.pdf`,locus:`p13 Ode 8 troparion 1`},label:`plain`},{text:`“The Lord alone is blessed,” cried the priest; “Those who made declaration unto us now manifestly show us the gates of life, the divinely inhabited palace, wherein the Messiah, the King of all, shall make His abode. To Him doth all the earth cry aloud: Bless the Lord, all ye works of the Lord!”`,tier:1,src:{file:`11-20.pdf`,locus:`p13 Ode 8 troparion 2`},label:`plain`},{text:`“Behold, O most wise elder,” Anna said with reverence, “receive with splendor the most comely maiden whom God hath given me, and prophesy that she alone shall bring to a material end what was foretold. With the other prophets thou dost cry out: Bless the Lord, all ye works of the Lord!”`,tier:1,src:{file:`11-20.pdf`,locus:`p13 Ode 8 troparion 3`},label:`plain`},{text:`“Now have I most clearly realized,” the elder said with understanding, “a tree will grow in the midst of the temple, which will truly issue forth a divine Fruit Who shall lead into paradise those who were driven out because they ate of the food of corruption, and who shall cry out with joy: Bless the Lord, all ye works of the Lord!”`,tier:1,src:{file:`11-20.pdf`,locus:`p13 Ode 8 troparion 4`},label:`plain`},{text:`The elder manifestly spake words of ineffable teaching: “O pure Virgin maiden, thy soul shall make its habitation in this divine temple; for, fed by an angel, thou shalt give birth to the angel of great counsel, to Whom we chant: Bless the Lord, all ye works of the Lord!”`,tier:1,src:{file:`11-20.pdf`,locus:`p13 Ode 8 troparion 5`},label:`plain`},{text:`With joy we chant to thee with the cry of Gabriel, O pure maiden:' Rejoice, thou who alone art the cause of joy for all! Rejoice, cleansing of our souls, in that thou hast given birth to the deliverance of us who render praise in hymns to Him: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-20.pdf`,locus:`p13 Ode 8 troparion 6`},label:`plain`}]},9:{irmos:{text:`Let every mortal born on earth, * radiant with light, in spirit leap for joy; * and let the host of the angelic powers * celebrate and honor the holy feast of the Mother of God, * and let them cry aloud: * Rejoice! O all-blessed Theotokos, * thou pure Ever-virgin.`,tier:2,src:{file:`11-20.pdf`,locus:`p14 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Behold, the holy mountain of God entereth the Holy of holies escorted with radiant lamps. From her shall be quarried the Stone which shall destroy the temples and idols of the demons and shall make mortals themselves into temples and honorable habitations of God.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 1`},label:`plain`},{text:`God hath sworn and shall now fulfill His vow, giving us the Ever-virgin from the tribe of Judah, whose womb shall put forth the Tree of Life which shall deliver those who fell through eating of the deadly fruit and were ruined by the deception of the serpent.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 2`},label:`plain`},{text:`With radiant mouth Anna cried out in the temple of God: “To Thee, O Master, do I offer the maiden Thou hast given me, from whom, in Thine ineffable tender compassion, Thou shalt become a mortal man and shalt save the world which Thou hast created, magnifying her as Thy Mother!”`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 3`},label:`plain`},{text:`Lo! the day of salvation hath dawned for those in the night of evils! The portal of heaven, the holy habitation of God, opening the gates of the temple, entereth into the Holy of holies accompanied by lighted lamps, to be nurtured by the holy hosts.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 4`},label:`plain`},{text:`Illumine the eyes of my soul, O pure one who hast given birth to the Light, lest the most profound darkness of sin overtake me, and the deep of despair cover me; but do thou thyself save me and guide me to the haven of the will of God.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 5`},label:`plain`}]}}},{title:`Canon of the venerable Gregory, the composition of Joseph, in Tone VIII:`,composer:`Joseph`,tone:8,odes:{1:{irmos:{text:`The wonderworking staff of Moses, * striking and dividing the sea in the figure of a cross, * once drowned pharaoh the pursuing charioteer, * while it saved the fleeing people of Israel * as they fled on foot, * chanting a hymn unto God.`,tier:2,src:{file:`11-20.pdf`,locus:`p4 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`By thy supplications, O blessed Gregory, enliven my lowly soul, which hath been slain by the passions; for thou hast now received the life which ageth not, having mortified thy members on earth with the struggles of asceticism, O venerable one.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 1`},label:`plain`},{text:`Abstaining from the pleasures of the body with purity of mind, O father, from childhood thou wast an instrument of the Spirit, splendidly receiving His powers and being recognized as godly of visage.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 2`},label:`plain`},{text:`With divine desire thou didst cause the desires of the flesh to wither away, O blessed one, espousing to thyself purity as a bride, from whom thou didst beget all the virtues as children for thyself, and who made thee a child of God, O ever memorable one.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 3`},label:`plain`},{text:`O most pure and blessed one, thou heavenly ladder stretching from earth unto the heavens, ineffable is the wonder and incomprehensible the vision, for God the Word hath come down to mortal mankind! do thou save those who have recourse unto thee.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`O Lord, Creator of the vault of heaven * and Builder of the Church, * do Thou strengthen me in Thy love, O Summit of desire, * O Support of the faithful, * O only Lover of mankind.`,tier:2,src:{file:`11-20.pdf`,locus:`p5 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having ascended the mountain of the virtues, O venerable father, thou didst enter into the darkness of vision and, comprehending, thou didst contain, as far as thou wast able, Him Who is unapproachable in essence, O father, being filled with enlightenment.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 1`},label:`plain`},{text:`With heavenly light He Who was born in a cave for the deliverance of mortal mankind illumined thee like Paul, O all-blessed one, who of old wast dwelling in a cave, showing thee to be luminous, O father Gregory.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 2`},label:`plain`},{text:`The heavenly portal, the most pure Mother of Christ, furnished thee with wings, O father, who wast beset by the assaults of the demons, and through the grace of the Spirit rendered thee able to soar above them with strength.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 3 troparion 3`},label:`plain`},{text:`Rejoice, O thou who alone hast given birth to the Lord of all! Rejoice, thou who hast mediated life for all! Rejoice, thou mountain overshadowed and unquarried, confirmation of the faithful! Rejoice, O all-immaculate one!`,tier:1,src:{file:`11-20.pdf`,locus:`p6 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Thou, O Lord, art my strength and Thou art my power, * Thou art my God and Thou art my joy, * Thou Who, while never leaving the bosom of Thy Father, * hast visited our poverty. * Therefore with the prophet Habbakuk I cry unto Thee, * “Glory to Thy power, O Lover of mankind!”`,tier:2,src:{file:`11-20.pdf`,locus:`p7 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`He Who in His goodness for our sake became a stranger by a strange descent, O Gregory, seeing thee a stranger for His sake, received thee who wast far from thy homeland and made thee a divine heir of His kingdom, adorned with the virtues.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode 4 troparion 1`},label:`plain`},{text:`For Christ Who for our sake became a babe and a child, O venerable one, thou didst give thyself over to a school of children, being as innocent as a babe, O divinely wise and venerable father; and with divine humility thou didst humble the malice of the enemy, O blessed Gregory.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 troparion 2`},label:`plain`},{text:`Watered with the showers of thy tears as with divine dew, O father Gregory, thou didst cause every virtue to grow bringing forth the blossoming of fruitfulness from the tree of perfect fasting planted by the springs of water.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 troparion 3`},label:`plain`},{text:`O blessed and all-immaculate Mother of God, heal thou the wounds of my soul, still the pleasures of the flesh, illumine my darkened heart, bring peace to my mind and deliver me from all the harm and assaults of the enemy.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Light never-waning, * why hast Thou turned Thy face from me * and why hath the alien darkness surrounded me, * wretched though I be? * But do Thou guide my steps I implore Thee * and turn me back towards the light of Thy commandments.`,tier:2,src:{file:`11-20.pdf`,locus:`p9 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`By thine actions thou didst show thyself to be a fertile vine of the Word, O venerable father, bearing the magnificent ripe grapes of the virtues which exude the spiritual wine of salvation, making glad the hearts of the faithful.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 1`},label:`plain`},{text:`Glorious Rome, receiving thee from the East with faith, O father, as a never-waning lamp, became enlightened by thy precious gifts; for thou didst have Christ within thy soul like a light illumining those who beheld thee, O father.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 2`},label:`plain`},{text:`Walking the paths of life with godly vigilance as a favorite of God, as a husbandman of the commandments of Christ with the power of the Spirit, thou didst slay the serpent who lay in wait to bruise thy heel.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 3`},label:`plain`},{text:`O Ever-virgin Mother, intercessor for the world, pilot me and guide me to the right path, and direct my thoughts along the straight paths of righteousness, setting aright the steps of my soul.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`Cleanse me, O Savior, * for many are mine iniquities; * lead me up from the abyss of evils I pray Thee, * for unto Thee have I cried, * and Thou hast hearkened unto me, * O God of my salvation.`,tier:2,src:{file:`11-20.pdf`,locus:`p10 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Deified by mystic visions and divine splendors, and by thy yearning for God, O most sacred one, as a divine prophet, as a favorite of God thou hast been deemed worthy of the grace of God.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 1`},label:`plain`},{text:`Thou didst perfect thy life in silence, O divinely inspired one, and wast revealed to be greater than the tumults of this life, higher than the passions, and a strange wanderer throughout all the earth.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 2`},label:`plain`},{text:`Like a clear mirror thou wast enriched with divine radiance; like a sacred vessel thou hast adorned the temple, O Gregory, illumining the heavenly Church of the firstborn.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 troparion 3`},label:`plain`},{text:`O Mary, pure palace of the King, having cleansed me who have become the impure den of thieves by thy supplications, show me to be a holy temple for Him Who was born from thee.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`Once in Babylon the fire stood in awe * of God's condescension; * for which sake the youths in the furnace, * dancing with joyous steps as in a meadow, chanted: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`11-20.pdf`,locus:`p12 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`With the outpourings of thy tears thou didst quench the fire, O Gregory, pouring forth the water of dispassion and the pure beverage of healings upon those who chant: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 1`},label:`plain`},{text:`Borne up by the perfection of honorable love as in a chariot of fire, thou didst mount to the summit, upon which thou didst acquire thy life, O divinely wise one, crying aloud: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 2`},label:`plain`},{text:`With thy standing in all-night vigils thou didst still the threefold billows of the passions, and having fallen into the sleep of the righteous, thou hast passed over into the never-waning light, crying aloud: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 3`},label:`plain`},{text:`O pure virgin, thou who hast given birth to Light, enliven me who am perishing and dying through sin; save me and rescue me from Gehenna, who chant: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`In his wrath the Chaldean tyrant made the furnace blaze, * with heat fanned sevenfold for the servants of God; * but when he perceived that they had been saved by a greater power * he cried aloud to the Creator and Redeemer; * “Ye children bless, ye priests praise, * ye people, supremely exalt Him throughout all ages”.`,tier:2,src:{file:`11-20.pdf`,locus:`p13 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Patiently sending up thy supplications to God, thou didst receive that for which thou didst ask with faith, O all-blessed one; for when thou didst sleep at night, an angel appeared to thee, who gave thee a fiery sword which cutteth down the passions of thy heart, cleanseth thee with immaterial fire and illumining thee with ineffable glory.`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 troparion 1`},label:`plain`},{text:`Like the most radiant sun hast thou shone noetically with the brilliant light of the virtues, O Gregory, illumining all the earth with the effulgence of thy miracles and enlightening those who piously chant: Ye children bless; ye priests chant; ye people supremely exalt Christ throughout the ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 troparion 2`},label:`plain`},{text:`Hearing the hymnody of the angels while still in thy mortal body, from which the senses of thy soul were manifestly delighted, O Gregory, thou wast shown to be godly and radiant of visage, crying out to the Master: Ye children bless; ye priests chant; ye people supremely exalt Him throughout the ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 troparion 3`},label:`plain`},{text:`O all-pure one who hast given birth to the Judge and Lord, Him do thou entreat as thy Son, at the hour of judgment, condemnation and fire, of darkness devoid of light and the gnashing of teeth, to deliver those who piously chant with faith: Ye priests chant; ye people supremely exalt Him throughout the ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`Every ear is awestruck at hearing of God's ineffable condescension, * for the Most High voluntarily descended and assumed flesh, * becoming man in the Virgin's womb; * wherefore we the faithful magnify the most pure Theotokos.`,tier:2,src:{file:`11-20.pdf`,locus:`p15 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`With the sweat of thy fasting thou didst quench the burning ember of sin, O wise one, and manifestly receive graced from heaven in the guise of fire which burneth not, but rather bedewed and showed thee to be one mighty in strength over the passions.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 1`},label:`plain`},{text:`Thou didst blossom like a rose, like a fragrant lily, amid the vales of fasting, O father Gregory. Wherefore, thou pourest forth fragrant myrrh, and thy bones abundantly perfume our life; for thy cheeks have been shown to be full, like a cup, of sweet fragrance.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 2`},label:`plain`},{text:`Today, the council of fasters and the venerable, the patriarchs and prophets, rejoice with us on thy memorial, O blessed one, and the apostles and martyrs celebrate with us. With them be thou mindful of those who honor thee with faith, O right wondrous one.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 3`},label:`plain`},{text:`The shrine wherein thy precious and much suffering body lieth, poureth forth the grace of miracles upon us, O father Gregory, sanctifying the souls and bodies of us who have been enriched by thee and have thee as an intercessor and fervent helper.`,tier:1,src:{file:`11-20.pdf`,locus:`p15 Ode 9 troparion 4`},label:`plain`},{text:`We, the faithful, with the cry of Gabriel joyfully cry aloud to thee: Rejoice, O garden of paradise who put forth the Tree of life! Rejoice, thou lifting of the curse, crown of martyrs, boast of the venerable and confirmation of the pious.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}},{title:`Canon of the holy hierarch Proclus, the composition of Theophanes, in Tone I:`,composer:`Theophanes`,tone:1,odes:{1:{irmos:{text:`Thy victorious right arm, * in a manner befitting God, * hath been glorified in strength, O Immortal One; * for in its infinite strength it shattered the enemy, * fashioning anew a path for the Israelites through the deep.`,tier:2,src:{file:`11-20.pdf`,locus:`p4 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The peer of the noetic archangels in activity and true discourse, O God-receiver, thou standest with them before the throne of the adored Trinity, O Proclus, Whom do thou beseech, that we be saved.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 1`},label:`plain`},{text:`Manifestly following in the footsteps of Chrysostom, O all-blessed and ever-memorable one, thou didst receive his divine priestly vestments as a paternal inheritance, O right glorious father.`,tier:1,src:{file:`11-20.pdf`,locus:`p4 Ode 1 troparion 2`},label:`plain`},{text:`In that Isaiah of old cried out in the Spirit that God would come to earth, Nestorius, who blasphemously slandered the incarnation, was deposed in council by thee, O thrice blessed one.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 1 troparion 3`},label:`plain`},{text:`With divinely inspired discourses thou didst explain the awesome incarnation of the Word of God from the Virgin, proclaiming her to be the Theotokos, following the all-wise dogmas of the apostles.`,tier:1,src:{file:`11-20.pdf`,locus:`p5 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`Thou alone knowest the weakness of human nature * and in compassion hast assumed its form; * do Thou gird me with power from on high, * that I may cry unto Thee: * Holy is the animate temple of Thine ineffable glory, O Lover of mankind!`,tier:2,src:{file:`11-20.pdf`,locus:`p6 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Receiving light from Light in a most godly manner, O all-blessed one, thou didst become a light for the Church. Wherefore, the divine Light shone upon thee noetically, as is written, and, illumined thereby, thou dost enlighten those who hymn thy memory.`,tier:1,src:{file:`11-20.pdf`,locus:`p6 Ode 3 troparion 1`},label:`plain`},{text:`Sounding forth the thunder of thy dogmas, and as the walls of Jericho were cast down so were all the audacities and armies of heresy, and thou hast won the trophy of victory, manifestly proclaiming the incarnation of God from the Virgin.`,tier:1,src:{file:`11-20.pdf`,locus:`p6 Ode 3 troparion 2`},label:`plain`},{text:`Setting thy mouth to the well-spring of wisdom, O Proclus in that thou art pleasing to God, thou didst draw forth divine waters of spiritual wisdom, drowning the turbid rivers, and ungodly opinions of Nestorius, O all-blessed one.`,tier:1,src:{file:`11-20.pdf`,locus:`p6 Ode 3 troparion 3`},label:`plain`},{text:`The only-begotten Son who is ineffably understood to be with the Father on high, was the only-begotten born of thee below in a supra-natural manner past understanding, O most pure one; and hath deofied mankind, O most pure Lady Theotokos. Wherefore, we call thee blessed.`,tier:1,src:{file:`11-20.pdf`,locus:`p6 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`Perceiving thee with prophetic eyes * as the mountain overshadowed by the grace of God, * Habbakuk proclaimed that the Holy One of Israel * would come forth from thee, * for our salvation and restoration.`,tier:2,src:{file:`11-20.pdf`,locus:`p8 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The resounding thunder of the words of thy proclamation and the teachings of thy doctrines gladden the Church of God with wisdom, dispelling the audacity of heresy, O all-glorious and sacred Proclus.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 troparion 1`},label:`plain`},{text:`Having purified thine honored body by abstinence like gold by fire, O most sacred and wise one, thou didst present it to the Creator as beautiful. Wherefore, He hath forever bestowed the vesture of the priesthood upon thee.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 troparion 2`},label:`plain`},{text:`Being a sacred hierarch, and accustomed to divine knowledge, thou didst generously grant the divine radiance of enlightenment unto all, for the salvation of souls, O right glorious one.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 troparion 3`},label:`plain`},{text:`Having in a manner past understanding received the divine Ember in thy womb, O all-immaculate one, thou wast truly not consumed; for the bush of old prefigured thy birthgiving, for our salvation and restoration.`,tier:1,src:{file:`11-20.pdf`,locus:`p8 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Hou hast shone upon us with the radiance * of Thy coming O Christ, * and illumined the ends of the world with Thy Cross, * enlighten with the light of thine understanding * the hearts of those who with right worship hymn Thee.`,tier:2,src:{file:`11-20.pdf`,locus:`p9 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Radiant as a beacon, O all-blessed one, thou wast shown to be a champion of the Church of God, clearly explaining the nativity of the Immutable One from the divine and all-holy Virgin, O glorious one.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 1`},label:`plain`},{text:`Placing the dogmas of the glorious incarnation of God from the Virgin in thy sling, like the godly David of old thou didst fell the audacious character of Nestorius as did Goliath the Philistine.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 2`},label:`plain`},{text:`Full of the teachings of Paul, and having beheld a vision of him, O most elect one, thou wast shown to be another Elisha, mystically anointed with the priesthood as with divine unction.`,tier:1,src:{file:`11-20.pdf`,locus:`p9 Ode 5 troparion 3`},label:`plain`},{text:`God took upon Himself neither confusion nor co-mingling in the womb of the Virgin, issuing forth in the flesh; but what He had been, that He remained: revealed immutably to be both God and man in His activities.`,tier:1,src:{file:`11-20.pdf`,locus:`p10 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`The deepest abyss hath surrounded us, * and there is none to deliver us, * yea we have been counted as sheep for the slaughter; * save Thy people O our God, * for Thou art the strength and restoration of the weak.`,tier:2,src:{file:`11-20.pdf`,locus:`p10 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`With the noetic staff of thy teachings thou didst drive the proponents of heresy from the flock of Christ like marauding wild beasts, O blessed Proclus, leading thy flock into the fold of Orthodoxy.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 6 troparion 1`},label:`plain`},{text:`Like another ark, through thine exhortations, O Proclus, thou didst present the body of the all-blessed Chrysostom to the Church of Christ, gladdening the choirs of the Orthodox by its arrival.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 6 troparion 2`},label:`plain`},{text:`Ascending the great cathedra, O venerable one, with magnificent instructions thou didst adorn it in a most godly manner. Wherefore, assembling, we praise thee, O greatly wise and glorious hierarch Proclus.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 6 troparion 3`},label:`plain`},{text:`Thou hast been revealed to surpass the cherubim, O Virgin full of the grace of God; for He Who is borne upon their shoulders, O pure one, was borne also in thine arms. Wherefore, we all ever glorify thee, O Theotokos.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`We the faithful perceive thee, O Theotokos, * to be a noetic furnace; * for as He, the supremely exalted One, * saved the three children, * so hath He wholly refashioned fallen humanity, in thy womb, * O Thou praised and supremely glorified God of our fathers.`,tier:2,src:{file:`11-20.pdf`,locus:`p12 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having purified body, mind and soul by removing the passions, O wise hierarch Proclus, from thence thou didst declare the dogmas of God Who was born and received a body, soul and mind from the Virgin, without undergoing change, that He might save us.`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 1`},label:`plain`},{text:`Having acquired boldness before Christ, O holy one, pray thou that those who with hymnody praise thy glorious memory on earth, hymning the praised and supremely glorious God, may be delivered from all manner of dangers.`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 2`},label:`plain`},{text:`Having kindled a noetic fire in thy thoughts, thou didst utterly consume the vile heresy of the abominable Nestorius; wherefore, we beseech thee: having burned up the fuel of our pleasures by thy supplications to God, O glorious one, do thou cleanse us.`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 troparion 3`},label:`plain`},{text:`O pure one, like the throne of the cherubim thou didst bear in thine embrace God Who became wrapped in the flesh, and Who beareth up all things by the word of His power. To Him do we chant in gladness: O all-hymned and supremely glorious God of our fathers, blessed art Thou!`,tier:1,src:{file:`11-20.pdf`,locus:`p12 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`In the furnace as in a fiery smelter * the Israelite children shone more brightly than gold * with the beauty of godliness, * as they exclaimed: Bless the Lord all ye works of the Lord, * hymn and supremely exalt Him throughout all ages.`,tier:2,src:{file:`11-20.pdf`,locus:`p14 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Having cleansed the carnal passions like gold through purity in the glowing crucible, O all-glorious one, thou didst shine forth upon all, chanting: All ye works, hymn the Lord and supremely exalt Him throughout the ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 troparion 1`},label:`plain`},{text:`Adorned by the sound of the instrument of thine honorable tongue, the Church of God: hymned the descent of the Savior to earth, manifestly singing for all to hear and crying: Thee do we supremely exalt, O Christ, throughout all ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 troparion 2`},label:`plain`},{text:`Thou hast truly been shown to be a divine harp whose music soundeth for all who with faith accept the saving incarnation of God for us, O blessed father Proclus, who chantest with faith: Hymn the Lord, ye works, and supremely exalt Him throughout the ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 troparion 3`},label:`plain`},{text:`God the Master, preserving the tokens of thy virginity intact, O Virgin, passed through thee in a manner past understanding, that He might save those who cry: Hymn the Lord and supremely exalt Him throughout the ages!`,tier:1,src:{file:`11-20.pdf`,locus:`p14 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`The Bush, which burnt without being consumed, * prefigured thy pure birthgiving, O Theotokos. * Wherefore we now entreat Thee: * quench the raging furnace of temptations that beset us, * that we may unceasingly magnify Thee.`,tier:2,src:{file:`11-20.pdf`,locus:`p16 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Passing by images and shadows, and truly understanding Christ, having been reborn in the baptismal font, thou wast anointed a most sacred priest. Wherefore, thou didst proclaim as Theotokos her who gave Him birth.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Ode 9 troparion 1`},label:`plain`},{text:`Thou didst embrace the sacred character and dogmas of Chrysostom, O blessed one, and with his sacred zeal for the Faith, thou didst raise up from the noetic depths thy dogmas, which dry up the torrents of heresies with grace.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Ode 9 troparion 2`},label:`plain`},{text:`By thy sacred prayers bring an end to the turmoil which riseth up against us, and dispel the darkness of the passions and the afflictions of all mankind, in that thou hast boldness before our Master and God.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Ode 9 troparion 3`},label:`plain`},{text:`O thy wonders which pass understanding! For thou alone hast given birth supra-naturally to the Word of God, Who became flesh and wisely sustaineth, nurtureth, and preserveth all things by His divine will.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],kontakia_ode3:[{text:`The Church knoweth thee to be a sun radiant with the beauties of the virtues, * illumining all with rays of healings, O favorite of Christ. * Wherefore, we celebrate thine honored memory * and honor thy struggles, ** O all-blessed and most wise father Gregory.`,tier:2,src:{file:`11-20.pdf`,locus:`p6 Kontakion of the venerable Gregory (after Ode III)`},label:`plain`,saint:`Gregory`,sourceLabel:`Kontakion of the venerable Gregory, in Tone III`,tone:3},{text:`Today the most honored of all cities * doth truly celebrate as is meet on the feast of thine honored repose, ** O wise Proclus, father of fathers.`,tier:2,src:{file:`11-20.pdf`,locus:`p6 Kontakion of the holy hierarch Proclus (after Ode III)`},label:`plain`,saint:`Proclus`,sourceLabel:`Kontakion of the holy hierarch Proclus, in Tone IV`,spec_mel:`Thou hast appeared ...`,tone:4}],sessional_ode3:[{text:`Illumined with divine splendor, thou hast driven away the darkness of the soul-destroying passions, O most wise Gregory; and caught up to the most pure heights of dispassion, thou hast most gloriously shone forth rays of healings, having made thine abode in the never-waning light of the kingdom of Christ.`,tier:1,src:{file:`11-20.pdf`,locus:`p6 Ode III sessional (Gregory)`},label:`plain`,saint:`Gregory`,sourceLabel:`Sessional Hymn of venerable Gregory, in Tone IV`,spec_mel:`Go thou quickly before ...`,tone:4},{text:`Being a divine and sacred preacher, O all-praised teacher of the mysteries, enriching the Church with divine doctrine, thou didst proclaim the most pure Virgin to be the Theotokos and didst thereby put Nestorius to shame. Wherefore, we all faithfully honor thy memory, asking that we be granted great mercy.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode III sessional (Proclus)`},label:`glory`,saint:`Proclus`,sourceLabel:`Glory ..., Sessional Hymn of the holy hierarch Proclus, in Tone III`,spec_mel:`Of the divine Faith ...`,tone:3},{text:`Give praise, ye virgins! Keep the forefeast, ye mothers! Ye people, give glory! Ye priests, bless the most pure Mother of God! For having been born before, a babe in the flesh, she hath been brought to the temple as the most holy temple of God. Wherefore, celebrating this spiritual feast, we hymn her as the intercessor for the race of mankind.`,tier:1,src:{file:`11-20.pdf`,locus:`p7 Ode III sessional (forefeast)`},label:[`both_now`,`of_the_feast`],saint:`forefeast`,sourceLabel:`Both now ..., Sessional Hymn of the Forefeast, in Tone I`,spec_mel:`When the stone had been sealed ...`,tone:1}],kontakia_ode6:[{text:`Today, on the most eminent feast of the Theotokos * the whole world hath been filled with gladness, crying: ** She is the tabernacle of heaven!`,tier:2,src:{file:`11-20.pdf`,locus:`p11 Kontakion of the forefeast (after Ode VI)`},label:`of_the_feast`,saint:`forefeast`,sourceLabel:`Kontakion of the forefeast, in Tone IV`,spec_mel:`Thou hast appeared ...`,tone:4},{text:`The Creator, Fashioner and Master of all, Who bowed Himself down in the ineffable tender compassion of His love for mankind, and seeing that which He had fashioned with His own hands fallen, took pity, and wishing to raise it up by His condescension into a most divine building, in that He is good and by nature merciful, took Mary, the pure Virgin, and made her the mediatress of the mystery, and through her bore our nature, wherefore she is truly the tabernacle of heaven.`,tier:1,src:{file:`11-20.pdf`,locus:`p11 Ikos of the forefeast`},label:`of_the_feast`,saint:`forefeast`,sourceLabel:`Ikos`,label_inline:!0}],exapostilarion:{text:`Thou wast a holy temple, O hierarch, and through divine communion thou hast now become a god and citizen of paradise, wherein thou dost partake directly of the tree of knowledge and incorruptible glory, mindful of those who with love and faith praise thee, O wise Gregory, sacred father.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Exapostilarion`},label:`plain`,saint:`Gregory`,sourceLabel:`Exapostilarion of venerable Gregory`,spec_mel:`While the disciples watched ...`},exapostilarion_closer:{text:`The temple doth now observe a day of pre-festival for the most pure entrance of Mary, the Theotokos, whom the angels hymn and we call blessed, and whom is accompanied by virgins, bearing lamps and rejoicing, into the temple of the Lord.`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Exapostilarion Both now, of the forefeast`},type:`of_the_feast`,saint:`forefeast`,sourceLabel:`Both now ..., of the forefeast`,spec_mel:`Hearken, ye women ...`},aposticha_rubric:{text:`On the Aposticha, these Stichera of the forefeast, in Tone I:`,tier:1,src:{file:`11-20.pdf`,locus:`p16 Matins Aposticha rubric`}},aposticha:[{text:`Come, ye faithful, and, assembling, * let us honor with hymns her * who was most gloriously born from a barren mother: * the divine Bride and Mother of the Creator; * and let us go forth with virgins and lamps to meet her ** as she entereth the Holy of holies of the temple.`,tier:2,src:{file:`11-20.pdf`,locus:`p16 Matins Aposticha 1`},label:`plain`,tone:1,saint:`forefeast`,spec_mel:`Joy of the ranks of heaven ...`},{text:`The virgins that follow after her shall be brought unto the King, * those near her shall be brought unto Thee.`,tier:2,src:{file:`11-20.pdf`,locus:`p17 Matins Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Having gathered the words of the Spirit * from noetic meadows, * like noetic flowers, * let us joyously weave wreaths of praise for the Virgin * and offer her a gift as is meet, ** on her forefeast.`,tier:2,src:{file:`11-20.pdf`,locus:`p17 Matins Aposticha 2`},label:`plain`,saint:`forefeast`,spec_mel:`Joy of the ranks of heaven ...`},{text:`They shall be brought with gladness and rejoicing, * they shall be brought into the temple of the King.`,tier:2,src:{file:`11-20.pdf`,locus:`p17 Matins Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Let the gates of the temple of the Lord be made ready, * and let them be opened; * and, rejoicing, let them receive the dwelling-place of glory, * her who alone transcendeth the heavens * in a manner transcending understanding; ** and let them hymn Christ the Savior.`,tier:2,src:{file:`11-20.pdf`,locus:`p17 Matins Aposticha 3`},label:`plain`,saint:`forefeast`,spec_mel:`Joy of the ranks of heaven ...`}],aposticha_closer:{text:`Let heaven rejoice today from on high, and let the clouds rain down gladness for the exceeding glorious mighty works of our God; for, lo! the gate which faceth toward the East, having been born from the barren woman according to God's promise, hath been dedicated to God as His dwelling-place, and is today brought into the temple as an unblemished offering. Let David rejoice, striking his harp; for he said: Virgins shall follow after her, those near her shall be brought into the tabernacle of God, into His sanctuary, to be raised in the habitation of Him Who was incorruptibly begotten of the Father before all ages, for the salvation of our souls.`,tier:1,src:{file:`11-20.pdf`,locus:`p17 Matins Aposticha Glory/Both now`},type:`of_the_feast`,composer:`George of Nicomedia`,saint:`forefeast`,sourceLabel:`Glory ..., Both now ..., The composition of George of Nicomedia, in Tone I`,tone:1}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`troparia`,`kontakia`,`prokeimenon`,`prokeimenon_verse`,`epistle_rubric`,`epistle`,`alleluia`,`alleluia_verse`,`gospel_rubric`,`gospel`,`communion_verse`],beatitudes_rubric:{text:`On the Beatitudes, 8 Troparia: 4 from ODE III and 4 from ODE VI of the canon of the forefeast.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitudes rubric`}},beatitudes:[{text:`The virgin maidens who undertake to bear candles with splendor prefigure what is to come; for from her the enlightenment of knowledge will be born, Who looseth the darkness of deception.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 1`},label:`plain`,saint:`forefeast`},{text:`Anna of old, filled with divinely wise zeal, fulfilleth her vow and escorteth to the sanctuary thee, her most sacred offspring, who art to give birth unto God, O most immaculate one.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 2`},label:`plain`,saint:`forefeast`},{text:`The sun spread forth its rays, beholding the radiant cloud stretched forth at the behest of God within the Holy of holies, from whence remission will rain forth upon the stony passions.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 3`},label:`plain`,saint:`forefeast`},{text:`Having made His abode within thee in His tender compassion, O all-immaculate and pure one, God deifieth me who was seduced aforetime by the deception of the serpent and corruption; and hath again given me the food of incorruption.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 4`},label:`plain`,saint:`forefeast`},{text:`Strengthened by the grace of God, the parents of the divine Virgin lovingly surrender her, like a pure dove, to be raised in the Holy of holies.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 5`},label:`plain`,saint:`forefeast`},{text:`Lighting lamps, O pure one, the maidens, dancing, radiantly accompany thee to the temple of God, for thou art to receive the Light Who proceedeth from the Light.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 6`},label:`plain`,saint:`forefeast`},{text:`A palace full of glory, the great proclamation of the prophets, the holy throne, is led into the Holy of holies, making herself ready for the King of all.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 7`},label:`plain`,saint:`forefeast`},{text:`I hymn thy conception, O maiden, I also hymn thine ineffable nativity; and I likewise hymn thy protection, whereby we who flee to thy serenity are delivered from all harm.`,tier:1,src:{file:`11-20.pdf`,locus:`p18 Beatitude 8`},label:`plain`,saint:`forefeast`}],troparia:[{text:`Anna now beforehand doth betroth joy unto all, * bringing forth the only Ever-virgin as a fruit assuaging grief, * and today bringeth her, rejoicing, * into the temple of the Lord, in fulfillment of her promise. ** For she is the pure Mother, the temple of God the Word.`,tier:2,src:{file:`11-20.pdf`,locus:`p18 Troparion of the forefeast at Liturgy`},label:`of_the_feast`,saint:`forefeast`,sourceLabel:`Troparion of the forefeast, in Tone IV`,tone:4},{text:`O God of our fathers, * ever deal with us according to Thy meekness. * Take not Thy mercy from us, * but by the prayers of these saints ** direct our life in peace.`,tier:2,src:{file:`11-20.pdf`,locus:`p18 Troparion of the holy fathers at Liturgy`},label:`plain`,saint:`Gregory and Proclus`,sourceLabel:`Troparion of the holy fathers, in Tone IV`,tone:4}],kontakia:[{text:`The Church knoweth thee to be a sun radiant with the beauties of the virtues, * illumining all with rays of healings, O favorite of Christ. * Wherefore, we celebrate thine honored memory * and honor thy struggles, ** O all-blessed and most wise father Gregory.`,tier:2,src:{file:`11-20.pdf`,locus:`p18 Kontakion of the venerable Gregory at Liturgy`},label:`plain`,saint:`Gregory`,sourceLabel:`Kontakion of the venerable Gregory, in Tone III`,tone:3},{text:`Today the most honored of all cities * doth truly celebrate as is meet on the feast of thine honored repose, ** O wise Proclus, father of fathers.`,tier:2,src:{file:`11-20.pdf`,locus:`p18 Kontakion of the holy hierarch Proclus at Liturgy`},label:`plain`,saint:`Proclus`,sourceLabel:`Kontakion of the holy hierarch Proclus, in Tone IV`,tone:4},{text:`Today, on the most eminent feast of the Theotokos * the whole world hath been filled with gladness, crying: ** She is the tabernacle of heaven!`,tier:2,src:{file:`11-20.pdf`,locus:`p19 Kontakion of the forefeast at Liturgy`},label:`of_the_feast`,saint:`forefeast`,sourceLabel:`Kontakion of the forefeast, in Tone IV`,tone:4}],prokeimenon:{text:`My mouth shall speak wisdom, * and the meditation of my heart shall be of understanding.`,tier:2,src:{file:`11-20.pdf`,locus:`p19 Liturgy Prokeimenon`},sourceLabel:`Prokeimenon, in Tone I`,label_inline:!0,tone:1},prokeimenon_verse:{text:`Hear this, ye nations; give ear, all ye that inhabit the earth.`,tier:1,src:{file:`11-20.pdf`,locus:`p19 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle_rubric:{text:`EPISTLE OF THE DAY, AND THAT OF THE HOLY HIERARCH:`,tier:1,src:{file:`11-20.pdf`,locus:`p19 Epistle rubric`}},epistle:{heading:`HEBREWS,`,src:{file:`11-20.pdf`,locus:`p19 Epistle`},citation_verbatim:`§ 318(HEB. 7: 26, 8: 2)`,citation:{book:`Hebrews`,chapter:7,verses:`7:26-8:2`,pericope_number:318},citation_basis:`printed`},alleluia:{text:`The mouth of the righteous shall meditate wisdom and his tongue shall speak of judgment.`,tier:1,src:{file:`11-20.pdf`,locus:`p19 Alleluia`},sourceLabel:`Alleluia, in Tone II`,label_inline:!0,tone:2},alleluia_verse:{text:`The law of his God is in his heart, and his steps shall not be tripped.`,tier:1,src:{file:`11-20.pdf`,locus:`p19 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel_rubric:{text:`GOSPEL OF THE DAY, AND THAT OF THE HOLY HIERARCH:`,tier:1,src:{file:`11-20.pdf`,locus:`p19 Gospel rubric`}},gospel:{heading:`JOHN`,src:{file:`11-20.pdf`,locus:`p19 Gospel`},citation_verbatim:`§ 36(JN. 10: 9-16)`,citation:{book:`John`,chapter:10,verses:`9-16`,pericope_number:36},citation_basis:`printed`},communion_verse:{text:`In everlasting remembrance shall the righteous be; he shall not be afraid of evil tidings.`,tier:1,src:{file:`11-20.pdf`,locus:`p19 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}},appendix:[{text:`Be it known: if the forefeast of the Entrance of the most holy Theotokos falleth on a Sunday: On Saturday, at Little Vespers, the Stichera of the resurrection and the Theotokos as usual. At Great Vespers, after the usual Kathisma, on “Lord, 1 have cried ...,” 4 Stichera of the resurrection, 3 of the forefeast, 3 of the venerable Gregory; Glory ..., of the forefeast; Both now ..., the Dogmaticon of the current tone. The usual Stichera at the Litiya. On the Aposticha, Stichera of the resurrection; Glory ..., Both now ..., of the forefeast. At the blessing of the loaves, the Troparion: “Virgin Theotokos, rejoice! ...” (Thrice).`,tier:1,src:{file:`11-20.pdf`,locus:`p20 Be it known: forefeast on a Sunday (Vespers)`}},{text:`But if vigil not be served, we chant the Troparion of the resurrection. Glory ..., that of Saint Gregory, in Tone III:`,tier:1,src:{file:`11-20.pdf`,locus:`p20 If vigil not be served`}},{text:`Thou wast a model of abstinence, illumining all with the divine Spirit Thou hast completed the race of the Orthodox Faith, enlightened the world with thy teaching and denounced the thoughts of the heretical. O venerable father Gregory, entreat Christ God, that He grant us great mercy.`,tier:1,src:{file:`11-20.pdf`,locus:`p20 Troparion of Saint Gregory`},sourceLabel:`that of Saint Gregory, in Tone III`,tone:3,label:`glory`,saint:`Gregory`},{text:`Both now ..., of the forefeast.`,tier:1,src:{file:`11-20.pdf`,locus:`p20 Both now, of the forefeast`}},{text:`On “God is the Lord ...,” the Troparion of the resurrection, twice; Glory ..., that of Saint Gregory; Both now ..., of the forefeast. After the Kathismata, the Sessional Hymns of the resurrection with their Theotokia. Then, Polyeleos and the Evlogitaria, litany. the Hypacoi of the tone, song of ascents. Prokeimenon. Gospel of the resurrection, and the rest up to the canon. Canon of the resurrection. with 4 Troparia, including the Irmos; that of the Theotokos. with 2 Troparia; that of the forefeast, with 4; and that of the venerable one. with 4. Katavasia: “I will open my mouth ...” After Ode III. the Kontakion of the forefeast, with its Ikos; and the Kontakion of Saint Gregory and his Sessional Hymn; Glory ..., Both now ..., that of the forefeast. After Ode VI. the Kontakion of the resurrection with its Ikos. Before Ode IX we chant the Magnificat. Exapostilarion of the resurrection; Glory ..., of Saint Gregory; Both now ..., of the forefeast. On the Praises, 4 Stichera of the resurrection, and 4 of the forefeast (the three of the Aposticha with their Doxasticon) using the Verse of the Aposticha; Glory , the evangelical Sticheron; Both now ...,”Most blessed art thou “ Great Doxology. After the Trisagion prayers, the Resurrectional Troparion alone. Litanies, dismissal and First Hour. In the First Hour. the Troparion of the resurrection; Glory ..., that of the forefeast; Both now ..., the Theotokion of the Hour. After Our Father, the Kontakion of the forefeast. In the Third Hour, the Troparion of the resurrection; Glory ..., of Saint Gregory; Both now ..., the Theotokion of the Hour. After Our Father, the Kontakion of the resurrection. And thus also for the other Hours: we alternate the Kontakion of the resurrection and the forefeast. At Liturgy: On the Beatitudes, 10 Troparia: 6 for the resurrection from the current tone, and 4 for the forefeast, from Ode m. At the entrance, the Troparia of: the resurrection and the forefeast; then that of the temple, if it be dedicated to a saint; then that of Saint Gregory. Kontakia: of the resurrection and the temple; Glory ..., of Saint Gregory; Both now ..., of the forefeast. Prokimena, epistles, alleluias, Gospels and communion hymns, of the resurrection, then of Saint Gregory. using the service for a venerable one.`,tier:1,src:{file:`11-20.pdf`,locus:`p20 Be it known: forefeast on a Sunday (Matins, Hours, Liturgy)`}},{text:`The service of the holy hierarch Proclus is then chanted whenever the ecclesiarch desireth.`,tier:1,src:{file:`11-20.pdf`,locus:`p20 The service of the holy hierarch Proclus`}},{text:`O thou who wast made steadfast in the fear of the Lord by a divine beginning. from thence by sacred ascents thou didst rise to become a disciple of Chrysostom and didst become worthy of his hierarchal throne in the beauty of thy purity, having formed thyself according to the canons of the apostles, living not for thyself, but for Christ and thy flock. Wherefore, thou didst abide in life incorruptible like an apostle, O hierarch Proclus. Entreat Christ God that our souls be saved.`,tier:1,src:{file:`11-20.pdf`,locus:`p20-p21 Troparion of the hierarch`},label:`plain`,saint:`Proclus`,sourceLabel:`Troparion of the hierarch, in Tone IV`,tone:4}]}]},"11-21":{_encoded:[`c0.identity`,`c0.little_vespers`,`c0.great_vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`feast`,feast_ref:`entrance_theotokos`,title:{text:`THE ENTRY OF OUR MOST HOLY LADY, THE THEOTOKOS & EVER-VIRGIN MARY, INTO THE TEMPLE`,tier:1,src:{file:`11-21.pdf`,locus:`p1 title`},sourceLabel:`THE 21st DAY OF THE MONTH OF NOVEMBER`},rank:`great_feast`,fekula_section:`2F`,oca_primary:!0,source_file:`11-21.pdf`,note:'Great Feast of the Theotokos. Little Vespers, Great Vespers (Litiya, blessing of the loaves) and Matins as a Vigil: Fekula 2F, which names the Entrance (Nov. 21) among the feasts of the Theotokos it covers (the troparion of the feast alone, thrice; two canons of 8 each; no Magnificat) and, in its note 48, the special verses that replace "Through the prayers" after Psalm 50, stored here as the psalm50_* keys. TWO canons (George, Tone IV; Basil, Tone I), interleaved in print, stored whole; a katavasia after every ode under Canon II, and after Ode I the rubric that these katavasiae are chanted until 1 January. Ode IX prints rubrics and a refrain before each irmos and a refrain before every troparion: stored as `preface`, labeled `items`, and `closing`. The three Vespers lessons print no reference; their citations are identifications, flagged for checking. Texts printed twice are stored at both sites: the Beatitudes repeat Ode III of Canon I and Ode VI of Canon II; the Liturgy refrain and irmos repeat Ode IX of Canon I.',troparion:{text:`Today is the prelude of God's good will * and the proclamation of the salvation of mankind. * The Virgin hath manifestly appeared in the temple of God, proclaiming Christ unto all. * To her let us cry aloud: ** Rejoice, thou fulfillment of the Creator's dispensation!`,tier:2,src:{file:`11-21.pdf`,locus:`p2 Troparion of the feast`},sourceLabel:`Troparion of the feast, in Tone IV`,tone:4,verified_sites:[{locus:`p2 Little Vespers`,tone:4},{locus:`p6 blessing of the loaves`,tone:4,repeat:3},{locus:`p7 God is the Lord`,tone:4,repeat:3},{locus:`p19 after the Great Doxology`,tone:4},{locus:`p21 AT LITURGY`,tone:4}]},kontakion:{text:`The most pure temple of the Savior, * the precious bridal chamber and Virgin, * the sacred treasury of the glory of God, * hath been brought into the house of the Lord this day, * bringing with her the grace that is in the divine Spirit. * To her do the angels of God chant the hymn: ** She is the heavenly tabernacle!`,tier:2,src:{file:`11-21.pdf`,locus:`p14 Kontakion of the feast`},verified_sites:[{locus:`p14 after Ode VI`,tone:4},{locus:`p21 AT LITURGY`,tone:4}],sourceLabel:`Kontakion of the feast, in Tone IV`,spec_mel:`Having been lifted up ...`,tone:4},ikos:{text:`Beholding the grace of the ineffable and divine mysteries of God made plainly manifest in and filling the Virgin, I rejoice; yet I know not how to understand this strange and ineffable image. How hath the pure one alone been shown to be above all creation, visible and immaterial? Wherefore, wishing to praise her, I am greatly in awe in mind and word; yet, bold, I proclaim and magnify her, saying: She is the heavenly tabernacle!`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ikos`},sourceLabel:`Ikos`,label_inline:!0},little_vespers:{order:[`lic_rubric`,`lic`,`lic_closer`,`aposticha_rubric`,`aposticha`,`aposticha_closer`,`troparion`],lic_rubric:{text:`On “Lord, I have cried ...,” 4 Stichera of the feast, in Tone I:`,tier:1,src:{file:`11-21.pdf`,locus:`p1 Little Vespers LIC rubric`}},lic:[{text:`Having received from the Lord * the fruit of the promise, the Mother of God, * the right acceptable sacrifice, * Joachim and Anna lead her into the temple today; * and Zachariah, the great high priest, ** receiveth her with his blessing.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers LIC 1`},label:`plain`,tone:1,repeat:2,spec_mel:`Joy of the ranks of heaven ...`},{text:`The holy of holies is fittingly brought * to dwell in the sanctuary * as a sacrifice pleasing to God; * and virgins, well adorned with the virtues, * bearing candles before her, ** accompany her to the Lord, as a most hallowed vessel.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers LIC 2`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`},{text:`Let the portal of the God-receiving temple be opened! * For today the temple and throne of the King of all * is received therein with glory! * Joachim bringeth her forth, * dedicating to the Lord ** her who was chosen by Him to be His Mother.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers LIC 3`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`}],lic_closer:{text:`David foretold thee, O most pure one, foreseeing the sanctification of thine entry into the Temple. Therein do the ends of the earth, holding festival today, glorify thee, O all-hymned one, for, O Mother of the Word of life, who before giving birth wast Virgin and after giving birth remained incorrupt, today Zechariah rejoiceth with exceeding gladness in the Temple, accepting thee, O Lady; and the Holy of Holies rejoiceth, receiving thee, the wellspring of our life. Wherefore, we also cry out in psalms to thee: Beseech thy Son and our God on our behalf, that He grant us great mercy.`,tier:1,src:{file:`11-21.pdf`,locus:`p1 Little Vespers LIC Glory/Both now`},type:`of_the_feast`,sourceLabel:`Glory ..., Both now ..., in Tone VIII`,tone:8},aposticha_rubric:{text:`On the Aposticha, these Stichera, in Tone II:`,tier:1,src:{file:`11-21.pdf`,locus:`p1 Little Vespers Aposticha rubric`}},aposticha:[{text:`O ye heavenly gates, * accept ye the Virgin, * the undefiled tabernacle * of God Almighty, ** into the Holy of holies.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers Aposticha 1`},label:`plain`,tone:2,spec_mel:`O house of Ephratha ...`},{text:`The virgins that follow after her shall be brought unto the King, * those near her shall be brought unto Thee.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`O ye choirs of virgins, * receive the pure Virgin * as the Bride of God, the King of all, * splendidly bearing candles ** unto the Holy of holies.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers Aposticha 2`},label:`plain`,spec_mel:`O house of Ephratha ...`},{text:`They shall be brought with gladness and rejoicing, * they shall be brought into the temple of the King.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`The bridal-chamber of God the Word * receiveth noetic bread * from the hands of the divine angel, * while making her habitation ** in the Holy of holies.`,tier:2,src:{file:`11-21.pdf`,locus:`p1 Little Vespers Aposticha 3`},label:`plain`,spec_mel:`O house of Ephratha ...`}],aposticha_closer:{text:`The thrice-radiant Light * enkindling thee, O Theotokos, * in the temple of glory, * sendeth thee heavenly food, ** magnifying thee.`,tier:2,src:{file:`11-21.pdf`,locus:`p2 Little Vespers Aposticha Glory/Both now`},type:`of_the_feast`,sourceLabel:`Glory ..., Both now ..., in the same melody`}},great_vespers:{order:[`rubric`,`lic_rubric`,`lic`,`lic_closer`,`entrance_rubric`,`readings`,`litiya`,`litiya_closer`,`aposticha_rubric`,`aposticha`,`aposticha_closer`,`troparion_rubric`,`troparion`],rubric:{text:`After the Introductory Psalm, we chant “Blessed is the man ...,” the first antiphon.`,tier:1,src:{file:`11-21.pdf`,locus:`p3 Great Vespers rubric`}},lic_rubric:{text:`On “Lord, I have cried ...,” 8 Stichera of the feast; 4 in Tone I:`,tier:1,src:{file:`11-21.pdf`,locus:`p3 LIC rubric`}},lic:[{text:`Let us join chorus today, O ye faithful, chanting to the Lord in psalms and hymns, and honoring His sacred tabernacle, the animate ark, who contained the uncontainable Word; for she is brought to the Lord, having become a babe in a manner transcending nature. And Zachariah, the great high priest, receiveth her with gladness as the dwelling-place of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p3 LIC 1`},label:`plain`,tone:1,repeat:2,spec_mel:`O wondrous marvel ...`},{text:`Today the animate temple of the holy glory of Christ our God, the pure one who alone among women is blessed, is led into the temple of the law, to dwell in the Holy of holies; with her Joachim and Anna rejoice in spirit, and choirs of virgins sing to the Lord, chanting in psalms and honoring His Mother.`,tier:1,src:{file:`11-21.pdf`,locus:`p3 LIC 2`},label:`plain`,spec_mel:`O wondrous marvel ...`},{text:`Thou art the proclamation of the prophets, the glory of the apostles, the boast of the martyrs, the restoration of all mortals, O Virgin Mother of God; for through thee have we been reconciled with God. Wherefore, we honor thine entrance into the temple of the Lord, and with the angel all of us who find salvation through thy supplications cry out to thee in hymns: Rejoice, O most pure one!`,tier:1,src:{file:`11-21.pdf`,locus:`p3 LIC 3`},label:`plain`,spec_mel:`O wondrous marvel ...`},{text:`Into the Holy of holies * is the holy and immaculate one * led by the Holy Spirit; * and she is fed by a holy angel, * in that she is the most holy temple * of our holy God, * Who hath sanctified all things by her entry * and hath deified the nature of mortal men ** which had fallen.`,tier:2,src:{file:`11-21.pdf`,locus:`p3 LIC 4`},label:`plain`,repeat:2,sourceLabel:`And 4 Stichera in Tone IV`,spec_mel:`As one valiant among the martyrs ...`,tone:4},{text:`Rejoicing today * and bearing candles, * the maidens precede the noetic lamp * and escort her with sanctity * to the Holy of holies, * revealing beforehand * the Effulgence which would ineffably shine forth from her * to illumine with the Spirit ** those who sit in darkness of ignorance.`,tier:2,src:{file:`11-21.pdf`,locus:`p3 LIC 5`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`},{text:`The all-praised Anna cried out: * “O Zacharias, in gladness receive her * whom the prophets of God proclaimed in the Spirit, * and escort her to the holy temple, * there to be raised in sanctity, * that she might become * the divine throne, * the palace and bower, ** and the radiant abode of the Master of all!”`,tier:2,src:{file:`11-21.pdf`,locus:`p3 LIC 6`},label:`plain`,spec_mel:`As one valiant among the martyrs ...`}],lic_closer:{text:`After thy nativity, O Lady, Bride of God, thou didst go to the Temple of the Lord to be raised in the Holy of Holies as a consecrated maiden. Gabriel was then sent to thee, the all-immaculate one, bringing food unto thee. All of the heavenly powers marveled, beholding the Holy Spirit abiding within thee: Wherefore, O most pure and undefiled Mother of God, who art glorified in heaven and on earth, save thou our race.`,tier:1,src:{file:`11-21.pdf`,locus:`p3 LIC Glory/Both now`},type:`of_the_feast`,sourceLabel:`Glory ..., Both now ..., in Tone VIII`,tone:8},entrance_rubric:{text:`Entrance. Prokeimenon of the day. Three lessons:`,tier:1,src:{file:`11-21.pdf`,locus:`p4 Entrance`}},readings:[{heading:`A READING FROM EXODUS`,src:{file:`11-21.pdf`,locus:`p4 Lesson 1`},citation:{book:`Exodus`,chapter:40,verses:`1-5, 9-10, 16, 34-35`},citation_basis:`identified`,provenance_note:`No reference printed. The body opens "The Lord spake to Moses, saying: On the first day of the first month ... thou shalt set up the tabernacle of the witness" (Exodus 40). The span given is the lesson commonly appointed for feasts of the Theotokos; it is an identification by opening words, NOT read off this page. Confirm the verses against the body.`},{heading:`A READING FROM THE THIRD BOOK OF KINGS`,src:{file:`11-21.pdf`,locus:`p4 Lesson 2`},citation:{book:`3 Kings`,chapter:7,verses:`7:51, 8:1, 3-7, 9-11`},citation_basis:`identified`,provenance_note:`No reference printed. Opens "It came to pass that Solomon finished building the house of the Lord. And he assembled all the elders of Israel in Sion, to bring the ark of the covenant" (3 Kings 7:51-8:1). Composite; span identified by opening words, not read off this page. Confirm.`},{heading:`A READING FROM THE PROPHECY OF EZEKIEL`,src:{file:`11-21.pdf`,locus:`p4 Lesson 3`},citation:{book:`Ezekiel`,chapter:43,verses:`43:27-44:4`},citation_basis:`identified`,provenance_note:`No reference printed. Opens "Thus saith the Lord: It shall come to pass from the eighth day and onward, that the priests shall offer your wholeburnt-offerings on the altar" (Ezekiel 43:27), the lesson of the shut gate. Span identified by opening words, not read off this page. Confirm.`}],litiya:[{text:`Let heaven rejoice today from on high, and let the clouds drop down gladness at the exceedingly glorious and mighty works of our God! For, lo! the portal which faceth east, who was born from a barren woman according to God's promise, and who became a dwelling-place sanctified for God, is brought forth as an unblemished offering. Let David rejoice, striking his harp! For he said: “The virgins that follow after her shall be brought before the King; those near her shall be brought unto the tabernacle of God, into His sanctuary, to be reared in the dwelling-place of Him Who, for the salvation of our souls, was incorruptibly begotten of the Father before time.”`,tier:1,src:{file:`11-21.pdf`,locus:`p5 Litiya 1`},label:`plain`,composer:`George of Nicomedia`,sourceLabel:`At Litiya, the Stichera, the composition of George of Nicomedia, in Tone I`,tone:1},{text:`Today the Theotokos, the temple which held God, is escorted into the temple of the Lord; and Zachariah receiveth her. Today the Holy of holies rejoiceth and the choir of angels mystically keepeth festival. And we, celebrating with them today, cry aloud with Gabriel: Rejoice, O thou who art full of grace! The Lord, Who hath great mercy, is with thee!`,tier:1,src:{file:`11-21.pdf`,locus:`p5 Litiya 2`},label:`plain`,tone:4,sourceLabel:`In Tone IV`,label_inline:!0},{text:`Come, all ye faithful, let us praise her who alone is immaculate, who was proclaimed beforehand by the prophets, and is brought into the temple, the Mother chosen before all ages, the Theotokos who hath appeared in the latter days. O Lord, through her supplications grant us Thy peace and great mercy.`,tier:1,src:{file:`11-21.pdf`,locus:`p5 Litiya 3`},label:`plain`}],litiya_closer:{text:`The day of joy and the most honored feast hath shone forth! For today she who remained Virgin after giving birth, as she was before birthgiving, is led into the temple of the Lord, and the elder Zachariah, the father of the forerunner, rejoiceth and crieth out in gladness: “The intercessor for the sorrowful draweth nigh unto the holy temple, in that she is holy, to be hallowed in the habitation of the King of all! Let Joachim, her forebear, be glad, and let Anna rejoice! For they have offered unto God the unblemished Lady like a heifer three years of age. Rejoice, ye mothers! Leap up, O virgins! Ye barren women, join chorus! For the Queen of all, who hath been foretold, hath opened unto us the kingdom of heaven! Rejoice, ye people, and be glad!”`,tier:1,src:{file:`11-21.pdf`,locus:`p5 Litiya Glory/Both now`},type:`of_the_feast`,composer:`Leo Magister`,sourceLabel:`Glory ..., Both now ..., the composition of Leo Magister, in Tone V`,tone:5},aposticha_rubric:{text:`On the Aposticha, these Stichera, in Tone V:`,tier:1,src:{file:`11-21.pdf`,locus:`p5 Aposticha rubric`}},aposticha:[{text:`Rejoice, O heaven and earth, beholding the only immaculate Virgin, the noetic heaven, coming forth to be raised in honor in the house of God! To her Zachariah cried out, marveling: “O portal of the Lord, I open unto thee the gates of the temple! Rejoice therein, joining chorus! For I have come to know and believe that the deliverance of Israel is manifestly coming, and that God the Word will be born through thee, granting the world great mercy!”`,tier:1,src:{file:`11-21.pdf`,locus:`p5 Aposticha 1`},label:`plain`,tone:5,spec_mel:`Rejoice ...`},{text:`The virgins that follow after her shall be brought unto the King, * those near her shall be brought unto Thee.`,tier:2,src:{file:`11-21.pdf`,locus:`p6 Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`O divinely manifest grace! With gladness Anna leadeth into the temple of God the pure Ever-virgin given her by grace, and she calleth maidens to go before her, bearing lamps and saying: “Go forth, my child! Be thou an offering and incense of sweet savor unto Him Who gave thee to us! Enter into the impassable precincts and learn the mysteries! And prepare thyself to be the gladsome and comely dwelling-place of Jesus, Who bestoweth upon the world great mercy!”`,tier:1,src:{file:`11-21.pdf`,locus:`p6 Aposticha 2`},label:`plain`,spec_mel:`Rejoice ...`},{text:`They shall be brought with gladness and rejoicing, * they shall be brought into the temple of the King.`,tier:2,src:{file:`11-21.pdf`,locus:`p6 Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`The all-holy Virgin, the temple in which God dwelleth, is borne into the temple of God, and maidens bearing lamps now precede her. Joachim and Anna, the excellent couple, her parents, leap for joy, dancing, for they gave birth to her who gave birth to the Creator, who, rejoicing in the divine tabernacles is fed by the hand of an angel, and hath been revealed to be the all-immaculate Mother of Christ, Who bestoweth great mercy upon the world.`,tier:1,src:{file:`11-21.pdf`,locus:`p6 Aposticha 3`},label:`plain`,spec_mel:`Rejoice ...`}],aposticha_closer:{text:`Assembling today, ye councils of the faithful, let us keep spiritual festival, and let us piously praise the divine maiden, the Virgin Theotokos, who is led into the temple of the Lord, she who was chosen before out of all generations to be the habitation of Christ God, the King of all. Bearing candles, O virgins, go ye on before, doing homage to the honored entry of the Ever-virgin! Ye mothers, setting aside all grief, follow joyously her who is to become the Mother of God, the mediatress of joy for the world! And with the angel let us all joyfully cry out to the joyous one “Rejoice!”, for she ever prayeth for our souls.`,tier:1,src:{file:`11-21.pdf`,locus:`p6 Aposticha Glory/Both now`},type:`of_the_feast`,composer:`Sergius of Jerusalem`,sourceLabel:`Glory ..., Both now ..., the composition of Sergius of Jerusalem, in Tone VI`,tone:6},troparion_rubric:{text:`At the blessing of the loaves, the Troparion of the feast, in Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p6 Blessing of the loaves rubric`}}},matins:{order:`god_is_lord_rubric.troparion.sessional_1.sessional_2.megalynarion_rubric.megalynarion.megalynarion_verse_rubric.megalynarion_verse.megalynarion_closing_rubric.sessional_polyeleos.anabathmoi_rubric.prokeimenon.prokeimenon_verse.gospel_rubric.gospel.psalm50_rubric.psalm50_glory.psalm50_closer_rubric.psalm50_verse_rubric.psalm50_sticheron.canon_rubric.canons.sessional_ode3.kontakion.ikos.exapostilarion.praises_rubric.praises.praises_closer.great_doxology_rubric.closing_rubric`.split(`.`),god_is_lord_rubric:{text:`On “God is the Lord ...,” the Troparion of the feast, in Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p7 God is the Lord rubric`}},sessional_1:[{text:`The fruit of the righteous Joachim and Anna is offered to God in the holy sanctuary, the nourisher of our Life who became a babe in the flesh, whom the sacred Zachariah blessed. With faith let us all bless her as the Mother of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Sessional 1`},label:`plain`,sourceLabel:`After the 1st chanting of the Psalter, the Sessional Hymn, in Tone I`,spec_mel:`The choir of angels ...`,tone:1},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Sessional 1 repeat device`},label:[`glory`,`both_now`]}],sessional_2:[{text:`Even before thy conception thou wast consecrated to God, O pure one, and, having been born on earth, thou hast now been offered to Him as a gift, fulfilling thy parents' vow; and having been presented in the divine temple, accompanied as a babe by lighted lamps in purity, thou hast been revealed to be the receptacle of the unapproachable and divine light, as the temple of God. Truly great is thy going forth, O only Ever-virgin Bride of God!`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Sessional 2`},label:`plain`,sourceLabel:`After the 2nd chanting of the Psalter, the Sessional Hymn, in Tone IV`,spec_mel:`Joseph marveled ...`,tone:4},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Sessional 2 repeat device`},label:[`glory`,`both_now`]}],megalynarion_rubric:{text:`Polyeleos, and this magnification:`,tier:1,src:{file:`11-21.pdf`,locus:`p7 magnification rubric`}},megalynarion:{text:`We magnify thee, O most holy Virgin, divinely chosen maiden, and we honor thine entry into the temple of the Lord.`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Magnification`},label_inline:!0},megalynarion_verse_rubric:{text:`Selected Psalm verse:`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Selected Psalm verse rubric`}},megalynarion_verse:{text:`Great is the Lord, and greatly to be praised, in the city of our God, in His holy mountain.`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Selected Psalm verse`},label:`refrain`,sourceLabel:`A`,label_inline:!0},megalynarion_closing_rubric:{text:`Glory ..., Both now ..., Alleluia ..., Glory to Thee, O God! (Thrice)`,tier:1,src:{file:`11-21.pdf`,locus:`p7 after the selected verses`}},sessional_polyeleos:[{text:`Let David the psalmist rejoice, and let Joachim and Anna join chorus, for the radiant Mary, the divine lamp, issued forth from them like a holy fruit, and she rejoiceth, entering the temple. Beholding her, the son of Barachiah blessed her, and, rejoicing; cried aloud: “Rejoice, O wonder of the world!”`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Polyeleos sessional`},label:`plain`,repeat:2,sourceLabel:`After the Polyeleos, the Sessional Hymn, in Tone VIII`,spec_mel:`That which was mystically commanded ...`,tone:8},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Polyeleos sessional repeat device`},label:[`glory`,`both_now`]}],anabathmoi_rubric:{text:`Song of Ascents, the first antiphon of Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p7 Song of Ascents rubric`}},prokeimenon:{text:`Hearken, O daughter, and see, * and incline thine ear.`,tier:2,src:{file:`11-21.pdf`,locus:`p8 Prokeimenon`},sourceLabel:`Prokeimenon, in Tone IV`,label_inline:!0,tone:4},prokeimenon_verse:{text:`My heart hath poured forth a good word; I shall speak of my works to the king.`,tier:1,src:{file:`11-21.pdf`,locus:`p8 Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel_rubric:{text:`Let every breath praise the Lord.`,tier:1,src:{file:`11-21.pdf`,locus:`p8 Let every breath`}},gospel:{heading:`THE GOSPEL ACCORDING TO ST. LUKE`,src:{file:`11-21.pdf`,locus:`p8 Matins Gospel`},citation_verbatim:`§4(1:39-49,56)`,citation:{book:`Luke`,chapter:1,verses:`39-49, 56`,pericope_number:4},citation_basis:`printed`},psalm50_rubric:{text:`After Psalm 50, instead of “Through the prayers of the Theotokos ...,” we chant:`,tier:1,src:{file:`11-21.pdf`,locus:`p8 After Psalm 50 rubric`}},psalm50_glory:{text:`Today the animate temple of the great King entereth the temple to prepare herself as a divine dwelling-place for Him.`,tier:1,src:{file:`11-21.pdf`,locus:`p8 After Psalm 50, Glory`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},psalm50_closer_rubric:{text:`Both now ..., The foregoing is repeated.`,tier:1,src:{file:`11-21.pdf`,locus:`p8 After Psalm 50, Both now`}},psalm50_verse_rubric:{text:`Have mercy on me O God ...,`,tier:1,src:{file:`11-21.pdf`,locus:`p8 Have mercy on me O God`}},psalm50_sticheron:{text:`Today the Theotokos, the temple who contained God, was led into the temple of the Lord, and Zachariah received her. Today the Holy of holies rejoiceth, and the choir of angels keepeth mystic festival. And with them we also, celebrating today, cry out with Gabriel: Rejoice, O thou who art full of grace, the Lord is with thee, Who hath great mercy!`,tier:1,src:{file:`11-21.pdf`,locus:`p8 After Psalm 50 sticheron`},sourceLabel:`And then this Sticheron, in Tone VI`,tone:6},canon_rubric:{text:`Two canons of the Theotokos: the first with 8 Troparia including the Irmos, the Irmos being chanted twice, and the second like the first, with 8 Troparia, including the Irmos, the Irmos being chanted twice.`,tier:1,src:{file:`11-21.pdf`,locus:`p8 Canon rubric`}},canons:[{title:`Canon I of the Theotokos: The acrostic whereof is: “O Lady, grant me the grace of discourse”, the composition of George, in Tone IV:`,composer:`George`,tone:4,odes:{1:{irmos:{text:`I shall open my mouth, * and be filled with the Spirit, * and utter discourse to the Queen and Mother; * and be seen radiantly keeping festival, * joyfully praising her entry.`,tier:2,src:{file:`11-21.pdf`,locus:`p9 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O most pure one, we know thee to be a treasury of wisdom and an ever-flowing fountain of grace; and we pray thee rain down upon us knowledge, that we may praise thee forever.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 troparion 1`},label:`plain`},{text:`Being a temple and palace more exalted than the heavens, O most pure one, thou wast set apart in the Temple of God to be prepared as a divine dwelling-place for His advent.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 troparion 2`},label:`plain`},{text:`Shining with the Light of grace, the Theotokos hath illumined all and assembled us to adorn her most splendid festival. Come ye, let us draw nigh to her!`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 troparion 3`},label:`plain`},{text:`The glorious portal which surpasseth human thought, having opened the doors of the Temple of God, doth now command us who have assembled to delight in her divine wonders.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 troparion 4`},label:`plain`}]},3:{irmos:{text:`O Theotokos, thou living and plentiful fount, * establish in spiritual fellowship those who sing hymns to thee, * that by thine entry, * they be granted crowns of glory.`,tier:2,src:{file:`11-21.pdf`,locus:`p9 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Receiving the pure and undefiled one, who is more splendid than all creation, the animate bridal chamber of God, the beautiful Temple and chamber doth appear today like a bride adorned for her wedding.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 troparion 1`},label:`plain`},{text:`David, preceding the chorus, doth leap and dance with us, declaring thee, O all-pure one, to be the queen all-adorned, standing in the Temple before our King and God, O most pure one.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 troparion 2`},label:`plain`},{text:`From her, whom transgressions issued forth among the race of mankind, hath her correction and incorruption blossomed forth, the Theotokos, who is led today into the house of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 troparion 3`},label:`plain`},{text:`The angelic armies and the multitudes of all mankind leap for joy, and they advance as lamp-bearers before thy countenance, proclaiming thy majesty in the house of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 troparion 4`},label:`plain`}]},4:{irmos:{text:`Perceiving the profound counsel of God, * that the incarnation of Thee the Most High, * will be from a Virgin, * the prophet Habbakuk cried aloud: * Glory to Thy power, O Lord!`,tier:2,src:{file:`11-21.pdf`,locus:`p11 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The Temple of God, receiving today the portal through whom none may pass, hath ceased to perform any service of the Law, crying: Truly truth hath appeared to those who are on earth!`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 troparion 1`},label:`plain`},{text:`The mountain overshadowed, which Habbakuk beheld of old, prefigured her who hath made her abode in the inaccessible chambers of the Temple, flourishing with virtues, for she doth cover the ends of the earth therewith.`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 troparion 2`},label:`plain`},{text:`All the earth hath seen most glorious things, things strange and marvelous, for the Virgin, receiving food from an angel, doth receive tokens of God's dispensation.`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 troparion 3`},label:`plain`},{text:`Revealed as the temple and palace and animate heaven, O divine bride of the King, thou art brought today to the Temple of the Law to be kept for Him, O most pure one.`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 troparion 4`},label:`plain`}]},5:{irmos:{text:`All creation stands in awe of thy divine glory; * for thou, O Virgin who hast not known wedlock, * didst enter into the temple of the Lord; * thyself being a most pure temple, * bestowing peace, upon all who hymn thee.`,tier:2,src:{file:`11-21.pdf`,locus:`p12 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The most pure Virgin, the glorious sanctity and sacred offering which is brought today to the Temple of God, is preserved as a habitation for our one God, the King of all, as He Himself knoweth.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 troparion 1`},label:`plain`},{text:`Zachariah, having of old beheld the beauty of thy soul, cried out in faith: Thou art the deliverance, thou art the joy of all, thou art our restoration, through whom the Uncontainable One shall appear unto me contained.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 troparion 2`},label:`plain`},{text:`O, thy wonders which pass understanding, O all-pure one! Strange is thy birthgiving; strange is the manner of thy maturation; strange also, most glorious and unutterable by mortals, are all thy wonders, O Bride of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 troparion 3`},label:`plain`},{text:`As a most radiant lamp, O Bride of God, hast thou shone forth today in the house of the Lord, illumining us with the precious gifts of thy wonders, O pure and all-hymned Theotokos.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 troparion 4`},label:`plain`}]},6:{irmos:{text:`Celebrating the divine and solemn feast * of the Mother of God * O ye divinely wise, * let us come, clapping our hands, * and glorify God who was born of her.`,tier:2,src:{file:`11-21.pdf`,locus:`p13 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou Who hast upheld all things by Thy word hast hearkened to the prayer of the righteous ones. Wherefore, Thou hast loosed the infirmity of the barren woman, in that Thou art compassionate, and given them her who is the cause of joy.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 troparion 1`},label:`plain`},{text:`Wishing to make His salvation known to the Gentiles, the Lord hath now taken from among mankind her who hath not known wedlock, as a sign of reconciliation and renewal.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 troparion 2`},label:`plain`},{text:`As a house of grace, wherein treasures of the ineffable dispensation of God are laid up, O all-pure one, thou didst share in unfading delight in the Temple.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 troparion 3`},label:`plain`},{text:`Receiving thee as a royal diadem, O Bride of God, the Temple hath been rendered splendid and been elevated to better things, beholding in thee the fulfillment of the prophecies.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 troparion 4`},label:`plain`}]},7:{irmos:{text:`Refusing to worship created things * in place of the Creator, * the divinely wise youths bravely trampled down the threatening fire * and rejoicing they sang aloud: * O supremely hymned Lord and God of our Fathers, Blessed art Thou.`,tier:2,src:{file:`11-21.pdf`,locus:`p14 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Lo, today a joyous spring hath dawned upon the ends of the earth, enlightening our souls, thoughts and minds with grace: the festival of the Theotokos. Let us mystically make festival this day!`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 troparion 1`},label:`plain`},{text:`Let all things - heaven and earth, the ranks of angels and the multitudes of mankind - bear gifts today unto the Queen and Mother of God; and let them cry aloud: Our joy and deliverance is brought into the Temple!`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 troparion 2`},label:`plain`},{text:`The Scriptures have come to pass, the Law hath faded like a shadow, and rays of grace have shone forth upon thee who hast entered into the Temple of God, O pure Virgin Mother wherein thou art blessed.`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 troparion 3`},label:`plain`},{text:`Heaven and earth and the netherworld are subject to thine Offspring as Creator and God, O all-pure one, and every nation of mortals doth confess that the Lord and Savior of our souls hath appeared.`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 troparion 4`},label:`plain`}]},8:{irmos:{text:`Hearken, O pure Virgin maiden, * that Gabriel may tell thee the true counsel of the Most High of old. * Make ready to receive the Godhead; * for through thee the Infinite One hath come to dwell among mankind. * Wherefore, rejoicing, I cry aloud: * Bless the Lord, all ye works of the Lord!`,tier:2,src:{file:`11-21.pdf`,locus:`p15 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Anna, once, leading the most pure temple to the house of God, faithfully said unto the priest, crying aloud: Now accept thou this child, given me by God; lead her into the Temple of the Creator; and, rejoicing, chant unto Him: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 8 troparion 1`},label:`plain`},{text:`And Zachariah then, beholding them in the Spirit, said unto Anna: Thou dost bring hither the true Mother of Life, whom the prophets of God have clearly foretold as the Theotokos! How, therefore, can the Temple hold her? Wherefore, marveling, I cry out: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 8 troparion 2`},label:`plain`},{text:`The handmaid of God have I been, answered Anna unto him, and I call upon Him with faith and prayer to accept the fruit of my birth-pangs, that, having received this child, I might bring her that was born unto Him that bestowed her. Wherefore, I cry aloud: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 8 troparion 3`},label:`plain`},{text:`Truly this is a matter of the Law, the priest said to her, and strange doth this thing seem unto me, beholding her that doth most gloriously surpass the holy ones in grace led into the house of God. Wherefore, rejoicing, I cry out: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 8 troparion 4`},label:`plain`}]},9:{preface:[{text:`At ODE IX we do not chant the Magnificat, but sing instead the refrains of the feast:`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I preface rubric`},label:`rubric`},{text:`The angels, beholding the entry of the most pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I preface refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`The Irmos of Canon I is then chanted: “ In nowise may the hand of the defiled ...,” whereupon the second choir chanteth the same refrain and Irmos. A refrain is also chanted before each Troparion of the ode, alternating between both choirs.`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I preface rubric`},label:`rubric`}],irmos:{text:`In nowise may the hand of the defiled * touch the animate ark of God; * and let the lips of the faithful * never-silently cry out with joy to the Theotokos, * chanting the words of the angel: * Rejoice, O thou who art full of grace! * The Lord is with thee!`,tier:2,src:{file:`11-21.pdf`,locus:`p16 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The angels, beholding the entry of the all-pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`O pure Theotokos, as thou hast the most radiant beauty of purity of soul and art full of the grace of God from heaven, with the ever-existent light thou dost ever enlighten those who cry out with joy: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I 1`},label:`plain`},{text:`The angels, beholding the entry of the all-pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`Thy wonder doth surpass the power of words, O pure Theotokos, for in thee I perceive a body impervious to the movement of sin. Wherefore, thankfully I cry out to thee: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I 2`},label:`plain`},{text:`The angels, beholding the entry of the all-pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 9 Canon I refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`Most gloriously did the Law prefigure thee, O pure one, as the tabernacle, the divine jar, the awe-some ark, the veil, the staff, the inviolable temple and portal of God. Wherefore, all these things teach us to cry to thee: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-21.pdf`,locus:`p16-p17 Ode 9 Canon I 3`},label:`plain`},{text:`The angels, beholding the entry of the all-pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon I refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`In hymnody David cried out to thee prophetically, calling thee the daughter of the King in the comeliness of thy virtues, beholding thee standing, elaborately adorned, at the right hand of God. Wherefore, in prophecy he cried out: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon I 4`},label:`plain`},{text:`The angels, beholding the entry of the all-pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon I refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`Foreseeing thee who art pleasing to God, Solomon proclaimed thee to be the bower of the King, the living and sealed fountain, from whence untroubled waters have issued forth for us who cry out with faith: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon I 5`},label:`plain`},{text:`The angels, beholding the entry of the all-pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon I refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`O Theotokos, thou givest to my soul the tranquility of thy gifts, pouring forth life upon those who honor thee as is meet, defending, protecting and preserving them thyself, that they might cry to thee: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon I 6`},label:`plain`}]}}},{title:`Canon II of the Theotokos, the composition of Basil, in Tone I:`,composer:`Basil`,tone:1,odes:{1:{irmos:{text:`Let us all chant a triumphant hymn unto God * Who wrought wondrous miracles * with His upraised arm, * and saved Israel, * for He hath been glorified.`,tier:2,src:{file:`11-21.pdf`,locus:`p9 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Let us hasten today, honoring the Theotokos with hymns, and let us celebrate a spiritual feast; for she is offered as a gift to God in the temple.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 troparion 1`},label:`plain`},{text:`With songs let us hymn the glorious arrival of the Theotokos; for today, as the prophets foretold, she is borne as a gift of great price into the temple, though she is herself the temple of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 troparion 2`},label:`plain`},{text:`The blameless Anna rejoiced, maternally bringing a gift of great price to God in the temple; and with her Joachim keepeth splendid festival.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`Of old, David, thine ancestor, hymned thee, O Virgin Bride of God, calling thee the daughter of Christ the King; and, having given birth to Him, as a Mother thou didst feed Him with milk as a babe.`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Ode 1 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`Christ is born, render ye glory. * Christ cometh from heaven, meet ye Him. * Christ is on earth, be ye exalted. * O all the earth, sing unto the Lord, * and sing praises in gladness, O ye people, * for He hath been glorified.`,tier:2,src:{file:`11-21.pdf`,locus:`p9 Ode 1 katavasia`},sourceLabel:`Katavasia`,label_inline:!0},katavasia_rubric:{text:`(From this day until the 1st day of January, this Katavasia is chanted)`,tier:1,src:{file:`11-21.pdf`,locus:`p9 Katavasia rubric: until the 1st day of January`}}},3:{irmos:{text:`Let my heart be established in Thy will O Christ God, * Who hath established a second heaven over the waters, * and founded the earth upon the waters, * O all-powerful One.`,tier:2,src:{file:`11-21.pdf`,locus:`p10 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O ye who love the feasts of the Church, let us keep festival and rejoice today together in spirit, and in gladness, on the holy feast of the daughter of the King, the Mother of our God.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 troparion 1`},label:`plain`},{text:`Rejoice today, O Joachim! Be thou glad in spirit, O Anna, leading to the Lord the three year old child born from thee, as though she were a pure and most immaculate heifer.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 troparion 2`},label:`plain`},{text:`Mary, the Theotokos, the habitation of God, is led into the holy temple, being three years of age in the flesh; and, going before her, virgins bear lighted lamps.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`The pure ewe-lamb of God, the undefiled turtle-dove, the tabernacle containing God, the sanctuary of glory, hath chosen to dwell within the holy tabernacle.`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode 3 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`To the Son who was begotten of the Father * without change before all ages, * and in the last times, without seed, was made flesh of the Virgin, * to Christ our God let us cry aloud: * Thou hast raised up our horn, holy art Thou, O Lord.`,tier:2,src:{file:`11-21.pdf`,locus:`p10 Ode 3 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},4:{irmos:{text:`Foreseeing in the Spirit O prophet Habbakuk, * the incarnation of the Word, * thou didst proclaim, crying aloud: * When the years draw nigh, Thou shalt be known; * when the season cometh, Thou shalt be shown forth! * Glory to Thy power, O Lord!`,tier:2,src:{file:`11-21.pdf`,locus:`p11 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O prophet Isaiah, prophesy unto us: Who is the Virgin Who will conceive in her womb, who springing forth from the root of Judah, and who shall give birth to the right glorious Fruit of the holy seed of King David?`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 troparion 1`},label:`plain`},{text:`O virgins, commence ye to chant hymns, holding candles in your hands, and praising the arrival of the pure Theotokos who now cometh to the temple of God, celebrating with us!`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 troparion 2`},label:`plain`},{text:`Rejoice now, O Joachim and Anna, leading into the temple of the Lord, like a heifer three years of age, the pure one born from you, who will become the Mother of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`As the holy of holies, O pure one, thou didst love to dwell in the holy temple, remaining there and conversing most gloriously with the angels, receiving bread from heaven, O Virgin, thou nourisher of Life.`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode 4 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`Rod of the root of Jesse, * and flower that blossomed from his stem, * O Christ, Thou hast sprung from the Virgin. * From the Mountain overshadowed by the forest * Thou hast come, made flesh from her that knew not wedlock, * O God who art not formed from matter. * Glory to Thy power, O Lord.`,tier:2,src:{file:`11-21.pdf`,locus:`p12 Ode 4 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},5:{irmos:{text:`Shine forth thy radiant and everlasting light * upon us who rise early at dawn, * unto the judgments of Thy commandments, * O Master, Lover of mankind, * Christ our God.`,tier:2,src:{file:`11-21.pdf`,locus:`p12 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O all ye Orthodox, let us take up lamps, hastening to glorify the Mother of God, for she is led to the Lord today as a right acceptable sacrifice.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 troparion 1`},label:`plain`},{text:`Let thine ancestors be glad today, O Lady; and let her who gave birth to thee rejoice with thy father, for their fruit is offered to the Lord.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 troparion 2`},label:`plain`},{text:`Celebrating with faith, let us all hymn the unblemished heifer, most glorious and of great renown, for she gave birth to the divine Bullock in the flesh.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`The divine tokens of thy betrothal, of thy birthgiving which passeth understanding, O pure Virgin; are recorded today by the Holy Spirit in the house of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p12 Ode 5 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`As Thou art the God of peace and Father of compassions, * Thou hast sent unto us Thine angel of great counsel, * granting us peace. * Wherefore guided towards the light of the knowledge of God, * and watching by night we glorify Thee, * O Lover of mankind.`,tier:2,src:{file:`11-21.pdf`,locus:`p13 Ode 5 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},6:{irmos:{text:`Emulating the prophet Jonah, I cry aloud: * Free Thou my life from corruption, O good One; * and save me who crieth out: * O Savior of the world, Glory be to Thee!`,tier:2,src:{file:`11-21.pdf`,locus:`p13 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O ye faithful, let us celebrate the spiritual feast of the Mother of God, chanting piously; for she is more holy than the heavenly intelligences.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 troparion 1`},label:`plain`},{text:`With spiritual hymns let us praise the Mother of the Light, O ye faithful, for she hath appeared to us today, going forth into the temple of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 troparion 2`},label:`plain`},{text:`The unblemished ewe-lamb, the pure turtle-dove, is brought to dwell in the house of God, for, as one all-immaculate, she was chosen beforehand to be the Mother of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`The temple of God, the heavenly tabernacle, maketh entry into the temple of the law, and from her hath the Light shone forth upon us who are in darkness.`,tier:1,src:{file:`11-21.pdf`,locus:`p13 Ode 6 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`The sea monster spat forth Jonah as it had received him, * like a babe from the womb: * while the Word, having dwelt in the Virgin and taken flesh, * came forth from her yet kept her incorrupt. * For being Himself not subject to decay. * He preserved His Mother free from all harm.`,tier:2,src:{file:`11-21.pdf`,locus:`p13 Ode 6 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},7:{irmos:{text:`The furnace became bedewed, O Savior, * and the children dancing, chanted: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`11-21.pdf`,locus:`p14 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O ye who love the feasts of the Church let us join chorus and hymn the pure Lady honoring Joachim and Anna as is meet.`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 troparion 1`},label:`plain`},{text:`Prophesy, O David, speaking in the Spirit: The virgins who follow after thee shall be brought to thee into the temple of the Queen and Mother.`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 troparion 2`},label:`plain`},{text:`The ranks of the angels rejoiced and the souls of the righteous were gladdened, for the Mother of God is led into the Holy of holies,`,tier:1,src:{file:`11-21.pdf`,locus:`p14 Ode 7 Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`Receiving heavenly food, she who was to become the Mother of Christ God in the flesh, excelled in wisdom and grace.`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 7 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`Scorning the impious decree of the godless one, * the children brought up together in godliness * feared not the threat of fire, * but standing in the midst of the flames, they sang: * “O God of our fathers, blessed art Thou.”`,tier:2,src:{file:`11-21.pdf`,locus:`p15 Ode 7 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},8:{irmos:{text:`Him of whom the angels and all the hosts of heaven are in awe * as their Lord and Creator, * ye priests hymn, ye children praise, * ye peoples bless and supremely exalt * throughout all ages.`,tier:2,src:{file:`11-21.pdf`,locus:`p15 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Joachim rejoiceth today in splendor, and the blameless Anna offereth to the Lord God a sacrifice: the holy daughter given her according to God's promise.`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 8 troparion 1`},label:`plain`},{text:`The holy David and Jesse render praise, and Judah offereth homage; for the pure Virgin, of whom the pre-eternal God was born, grew forth as fruit from their root.`,tier:1,src:{file:`11-21.pdf`,locus:`p15 Ode 8 troparion 2`},label:`plain`},{text:`The most pure Mary, the animate tabernacle, is brought today into the house of God; and Zachariah taketh her in his arms as the sanctified treasure of the Lord.`,tier:1,src:{file:`11-21.pdf`,locus:`p15-p16 Ode 8 troparion under "We bless the Father"`},label:`plain`,sourceLabel:`We bless the Father, the son and the Holy Spirit, the Lord`},{text:`O ye faithful, let us truly honor the Virgin Mother of God, who is blessed by the hands of the priests, as the portal of salvation, the noetic mountain and the animate ladder.`,tier:1,src:{file:`11-21.pdf`,locus:`p16 Ode 8 Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],katavasia:{text:`The furnace moist with dew showed forth an image * of a wonder past nature, * for it burned not the youths whom it had received; * neither did the fire of the Godhead consume the Virgin * when it descended into her womb. * Wherefore, chanting, we sing: * Let all creation bless the Lord and supremely exalt Him throughout all ages!`,tier:2,src:{file:`11-21.pdf`,locus:`p16 Ode 8 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}},9:{preface:[{text:`Then the first choir chanteth the refrain of Canon II of the feast:`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon II preface rubric`},label:`rubric`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon II preface refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`Then the Irmos is chanted: “The light-bearing cloud upon whom ...” The second choir then chanteth the same refrain and Irmos of the feast. And before each Troparion of the canon we chant the above festal refrain.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon II preface rubric`},label:`rubric`}],irmos:{text:`The light-bearing cloud upon whom * the beginningless Master of all descended from heaven, * like the dew upon the fleece, * and of whom He was incarnate, * becoming a man for our sake, * let us all magnify as the pure Mother of God.`,tier:2,src:{file:`11-21.pdf`,locus:`p17 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0,repeat:2},items:[{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`The divine maiden Mary, the fruit of the promise, issued forth from the righteous Joachim and Anna, and, a babe in the flesh, she is brought into the holy sanctuary like pleasing incense, to dwell in the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon II 1`},label:`plain`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p17 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`With hymns let us praise her who was a babe by nature and was supernaturally re-vealed as the Mother of God; for she is led unto the Lord in the temple of the law, as the fragrance of sweet savor for the righteous, as the spiritual fruit of her righteous parents.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II 2`},label:`plain`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`O ye faithful, with the angel let us fittingly cry out to the Theotokos “Rejoice!” Rejoice, O most comely Bride! Rejoice, O radiant cloud, from whom the Lord hath shone forth upon us who sit in the darkness of ignorance! Rejoice, thou hope of all!`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II 3`},label:`plain`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`O pure Mary Mother of God, thou Holy of holies, from the snares of the enemy and from all heresy and tribulation do thou free us by thy supplications, who bow down with faith before the image of thy holy countenance.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II 4`},label:`plain`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`With the angel Gabriel all creation uttereth a fitting hymn to the Theotokos, crying: Rejoice, O most immaculate Mother of God, by whom we have been delivered from the primal curse, coming to share in incorruption!`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II 5`},label:`plain`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`O Virgin, thou hast been shown to be greater than the cherubim, more exalted than the seraphim and more spacious than the heavens, for thou didst contain within thy womb our God Whom naught can contain, and hast given birth to Him ineffably. Him do thou earnestly beseech on our behalf.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II 6`},label:`plain`},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`Let us glorify the indivisible Trinity, the Essence in three Hypostases, the undivided glory, Who in a single Godhead, is unceasingly hymned in heaven and on earth, piously worshiping the Father, the Son and the Spirit.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II Triadicon`},label:`trinitarion`,sourceLabel:`Triadicon`,label_inline:!0},{text:`Magnify, O my soul, her who hath been led into the temple of the Lord and been blessed by the hands of the priest.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},{text:`O Virgin Birthgiver of God, pray thou, that we who flee with faith beneath thy compassion and piously worship thy Son as God and Lord of the world be delivered from corruption, misfortunes and all manner of temptations.`,tier:1,src:{file:`11-21.pdf`,locus:`p18 Ode 9 Canon II 7`},label:`plain`}],closing:[{text:`Then both choirs, descending together, chant the refrain of Canon I, followed by the Katavasia:`,tier:1,src:{file:`11-21.pdf`,locus:`p18-p19 Ode 9 closing rubric`},label:`rubric`},{text:`The angels, beholding the entry of the most pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p19 Ode 9 closing refrain`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0}],katavasia:{text:`A strange and most wondrous mystery do I see: * the cave is heaven; * the Virgin the throne of the cherubim; * the manger a room, in which Christ God, * whom nothing can contain, is laid. * Whom we praise and magnify.`,tier:2,src:{file:`11-21.pdf`,locus:`p19 Ode 9 katavasia`},sourceLabel:`Katavasia`,label_inline:!0}}}}],sessional_ode3:[{text:`Tell us, O David: what is this present festival? Who is she whom of old thou didst hymn in the Book of Psalms as the daughter, divine maiden and Virgin? “The virgins that follow after her, together with those near her,” said he, “shall be mystically brought unto the King.” Make this a wondrous and universal feast for those who cry aloud: the Theotokos is come unto us, the mediatress of salvation!`,tier:1,src:{file:`11-21.pdf`,locus:`p10 Ode III sessional`},label:`plain`,sourceLabel:`Sessional Hymn, in Tone IV`,spec_mel:`Joseph marveled ...`,tone:4},{text:`With gladness Mary, the Theotokos, is most gloriously brought into the house of God: the unblemished ewe-lamb, the undefiled bridal-chamber, whom the angels of God, escort with faith and all the faithful ever call blessed and hymn her unceasingly with a loud voice in thanksgiving: Thou art our glory and salvation, O most immaculate one!`,tier:1,src:{file:`11-21.pdf`,locus:`p11 Ode III sessional Glory/Both now`},label:[`glory`,`both_now`],sourceLabel:`Glory ..., Both now ..., in the same melody`}],exapostilarion:{text:`With faith let us praise the divine maiden Mary, whom the company of the prophets of old proclaimed to be the jar, the staff, the tablet and the unquarried mountain; for she is led today into the Holy of holies to be raised for the Lord.`,tier:1,src:{file:`11-21.pdf`,locus:`p19 Exapostilarion`},sourceLabel:`Exapostilarion of the feast`,spec_mel:`Hearken, ye women ...`,label:`plain`,repeat:3},praises_rubric:{text:`On the Praises, 4 Stichera, in Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p19 Praises rubric`}},praises:[{text:`Virgins bearing lamps, * escorting the Ever-virgin with splendor, * truly prophesy the future in the Spirit; * for the Theotokos, as the temple of God, * is led as a child with virginal glory ** into the temple.`,tier:2,src:{file:`11-21.pdf`,locus:`p19 Praises 1`},label:`plain`,tone:4,spec_mel:`Joy of the ranks of heaven ...`},{text:`Truly the Theotokos hath appeared to the world * as the right glorious fruit of a holy promise, * for she surpasseth all. * Piously led into the temple of God, * she fulfilleth the supplication of her parents, ** and is preserved by the divine Spirit.`,tier:2,src:{file:`11-21.pdf`,locus:`p19 Praises 2`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`},{text:`Faithfully raised on heavenly bread, O Virgin, * in the temple of the Lord, * thou hast given birth to the Word, the Bread of life, for the world, * to Whom thou wast mystically promised beforehand by the Spirit * as the chosen and all-immaculate temple, ** betrothed to God the Father.`,tier:2,src:{file:`11-21.pdf`,locus:`p19 Praises 3`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`},{text:`Let the portal of the God-receiving temple be opened! * For today the temple and throne of the King of all * is received therein with glory! * Joachim bringeth her forth, * dedicating to the Lord ** her who was chosen by Him to be His Mother.`,tier:2,src:{file:`11-21.pdf`,locus:`p19 Praises 4`},label:`plain`,spec_mel:`Joy of the ranks of heaven ...`}],praises_closer:{text:`Today the all-immaculate Virgin is brought to the temple, to the habitation of God, the King of all, the Nourisher of our whole life. Today the most pure and holy one, is led to the Holy of holies like a heifer three years of age. Let us cry out unto her like the angel: “Rejoice, thou who alone art blessed among women!”`,tier:1,src:{file:`11-21.pdf`,locus:`p19 Praises Glory/Both now`},type:`of_the_feast`,composer:`Leo Magister`,sourceLabel:`Glory ..., Both now ..., the composition of Leo Magister, in Tone II`,tone:2},great_doxology_rubric:{text:`Great Doxology. Troparion, in Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p19 Great Doxology. Troparion`}},closing_rubric:{text:`Litanies. Dismissal. First Hour.`,tier:1,src:{file:`11-21.pdf`,locus:`p20 Litanies. Dismissal. First Hour.`}}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`troparia_rubric`,`troparion`,`kontakion_rubric`,`kontakion`,`prokeimenon`,`prokeimenon_verse`,`epistle`,`alleluia`,`alleluia_verse`,`gospel`,`megalynarion_rubric`,`megalynarion_refrain`,`megalynarion`,`megalynarion_closing_rubric`,`communion_verse`],beatitudes_rubric:{text:`On the Beatitudes, 8 Troparia: 4 from ODE III of Canon I, and 4 from ODE VI of Canon II of the feast.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitudes rubric`}},beatitudes:[{text:`Receiving the pure and undefiled one, who is more splendid than all creation, the animate bridal chamber of God, the beautiful Temple and chamber doth appear today like a bride adorned for her wedding.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude 1`},label:`plain`},{text:`David, preceding the chorus, doth leap and dance with us, declaring thee, O all-pure one, to be the queen all-adorned, standing in the Temple before our King and God, O most pure one.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude 2`},label:`plain`},{text:`From her, whom transgressions issued forth among the race of mankind, hath her correction and incorruption blossomed forth, the Theotokos, who is led today into the house of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude 3`},label:`plain`},{text:`The angelic armies and the multitudes of all mankind leap for joy, and they advance as lamp-bearers before thy countenance, proclaiming thy majesty in the house of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude 4`},label:`plain`},{text:`O ye faithful, let us celebrate the spiritual feast of the Mother of God, chanting piously; for she is more holy than the heavenly intelligences.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude 5`},label:`plain`},{text:`With spiritual hymns let us praise the Mother of the Light, O ye faithful, for she hath appeared to us today, going forth into the temple of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude 6`},label:`plain`},{text:`The unblemished ewe-lamb, the pure turtle-dove, is brought to dwell in the house of God, for, as one all-immaculate, she was chosen beforehand to be the Mother of God.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude Glory ...`},label:`glory`,sourceLabel:`Glory ...,`,label_inline:!0},{text:`The temple of God, the heavenly tabernacle, maketh entry into the temple of the law, and from her hath the Light shone forth upon us who are in darkness.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Beatitude Both now ...`},label:`both_now`,sourceLabel:`Both now ...,`,label_inline:!0}],troparia_rubric:{text:`After the entrance, the Troparion of the feast, in Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p21 After the entrance, the Troparion`}},kontakion_rubric:{text:`Glory ..., Both now ..., the Kontakion of the feast, in Tone IV:`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Glory, Both now, the Kontakion`}},prokeimenon:{text:`My soul doth magnify the Lord, * and my spirit hath rejoiced in God my Savior.`,tier:2,src:{file:`11-21.pdf`,locus:`p21 Liturgy Prokeimenon`},tone:3,sourceLabel:`Prokeimenon, in Tone III: the Song of the Theotokos`,label_inline:!0},prokeimenon_verse:{text:`For He hath looked upon the lowliness of His handmaiden; for behold, from henceforth all generations shall call me blessed.`,tier:1,src:{file:`11-21.pdf`,locus:`p21 Liturgy Prokeimenon verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},epistle:{heading:`EPISTLE TO THE HEBREWS,`,src:{file:`11-21.pdf`,locus:`p22 Epistle`},citation_verbatim:`§ 320(HEB. 9: 1-7)`,citation:{book:`Hebrews`,chapter:9,verses:`1-7`,pericope_number:320},citation_basis:`printed`},alleluia:{text:`Hearken, O daughter, and see, and incline thine ear.`,tier:1,src:{file:`11-21.pdf`,locus:`p22 Alleluia`},sourceLabel:`Alleluia, in Tone VIII`,label_inline:!0,tone:8},alleluia_verse:{text:`The rich among the people shall entreat thy countenance.`,tier:1,src:{file:`11-21.pdf`,locus:`p22 Alleluia verse`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},gospel:{heading:`GOSPEL ACCORDING TO LUKE,`,src:{file:`11-21.pdf`,locus:`p22 Gospel`},citation_verbatim:`§ 54(LK. 10: 38-42, 11: 27-28)`,citation:{book:`Luke`,chapter:10,verses:`10:38-42, 11:27-28`,pericope_number:54},citation_basis:`printed`},megalynarion_rubric:{text:`Instead of “It is truly meet...,” we chant the Irmos of ODE IX of Canon I:`,tier:1,src:{file:`11-21.pdf`,locus:`p22 Instead of It is truly meet`}},megalynarion_refrain:{text:`The angels, beholding the entry of the most pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-21.pdf`,locus:`p22 Refrain before the festal Irmos`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},megalynarion:{text:`In nowise may the hand of the defiled * touch the animate ark of God; * and let the lips of the faithful * never-silently cry out with joy to the Theotokos, * chanting the words of the angel: * Rejoice, O thou who art full of grace! * The Lord is with thee!`,tier:2,src:{file:`11-21.pdf`,locus:`p22 Irmos of Ode IX of Canon I, at Liturgy`},sourceLabel:`Irmos`,label_inline:!0},megalynarion_closing_rubric:{text:`This is done through to the leave-taking of the feast.`,tier:1,src:{file:`11-21.pdf`,locus:`p22 through to the leave-taking`}},communion_verse:{text:`I will take the cup of salvation, and I will call upon the name of the Lord.`,tier:1,src:{file:`11-21.pdf`,locus:`p22 Communion Verse`},sourceLabel:`Communion Verse`,label_inline:!0}}}]},"11-22":{_encoded:[`c0.identity`,`c0.vespers`,`c0.matins`,`c0.liturgy`],commemorations:[{kind:`afterfeast`,feast_ref:`entrance_theotokos`,title:{text:`AFTER-FEAST OF THE ENTRY OF THE THEOTOKOS INTO THE TEMPLE COMMEMORATION OF THE HOLY APOSTLE PHILEMON & THOSE WITH HIM`,tier:1,src:{file:`11-22.pdf`,locus:`p1 title`},sourceLabel:`THE 22nd DAY OF THE MONTH OF NOVEMBER`},rank:`simple`,fekula_section:`2G1`,oca_primary:!0,source_file:`11-22.pdf`,note:'ONE printed service for the Afterfeast of the Entry and the Apostle Philemon and those with him: one entry, every item tagged with `saint` ("feast" or "Philemon and those with him"). 3 stichera of the feast and 3 of the apostle at Lord I have cried; no Polyeleos, no Great Doxology (Matins ends with Aposticha): Simple, Fekula 2G1 (weekday service in an afterfeast). Two canons, interleaved in print, stored whole. Two troparia and two kontakia, each printed at several sites, are stored at every site in positional lists and NOT as entry-level canonical fields. The Liturgy prints TWO prokeimena, TWO alleluia verses and TWO communion verses (feast and apostles): stored as the lists `prokeimena`, `alleluias`, `communion_verses`. Only the apostles\' Epistle and Gospel are printed. The Ode V heading is printed with doubled letters ("OODDEE VV"); headings are not stored.',vespers:{order:[`lic_rubric`,`lic`,`lic_closer`,`aposticha_rubric`,`aposticha`,`aposticha_closer`,`troparia`],lic_rubric:{text:`On “Lord, I have cried ...,” 6 Stichera: 3 of the feast, in Tone VIII,`,tier:1,src:{file:`11-22.pdf`,locus:`p1 LIC rubric`}},lic:[{text:`O most glorious wonder, * the ineffable future * is now described beforehand, * understood today in visible images; * for she who shone forth the divine light upon the world * is led like a bride into the holy temple. * Let us praise her as the most resplendent temple, * holy and radiant, ** of Christ God, the Bestower of life.`,tier:2,src:{file:`11-22.pdf`,locus:`p1 LIC 1`},label:`plain`,saint:`feast`,tone:8,spec_mel:`O most glorious wonder ...`},{text:`Truly the wise Joachim and Anna * have manifestly offered * their right acceptable first-fruits, * the Virgin Mary, the divine maiden, * unto Him Who willed to grant her to them as a divine fruit, * whereby the debt of grief hath been cancelled. * In gladness let us piously hymn her, * for she hath been made the mediatress of joy ** for all the world.`,tier:2,src:{file:`11-22.pdf`,locus:`p1 LIC 2`},label:`plain`,saint:`feast`,spec_mel:`O most glorious wonder ...`},{text:`Come, let us now mystically hasten * and, adorned with lamps of faith, * let us now begin the procession of the Virgin; * for she hath gloriously entered the temple of God, * betrothed to Christ, * the King of all. * We all celebrate her beauteous solemnity, * keeping festival in a godly manner ** with her entry.`,tier:2,src:{file:`11-22.pdf`,locus:`p1 LIC 3`},label:`plain`,saint:`feast`,spec_mel:`O most glorious wonder ...`},{text:`As a branch of the Vine of life, * O glorious Philemon, * thou hast poured forth the wine of divine knowledge * upon those in pain of soul, * gladdening hearts downcast * by the darkness of deception * and held fast in the gloom of the madness of idolatry; * wherefore, in gladness ** we celebrate thy divinely radiant memory.`,tier:2,src:{file:`11-22.pdf`,locus:`p1 LIC 4`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`And 3 Stichera of the holy apostle, in Tone II`,spec_mel:`When from the Tree ...`,tone:2},{text:`The city of Gaza doth honor thee, * having through thee * come to see the light of understanding, O blessed one, * and the Colossians, possessing thy divine body as a treasure, * have healings and grace * which ever floweth forth; * wherefore, celebrating thy memory, * O glorious Philemon, ** we are preserved from misfortunes by thy supplications.`,tier:2,src:{file:`11-22.pdf`,locus:`p1 LIC 5`},label:`plain`,saint:`Philemon and those with him`,spec_mel:`When from the Tree ...`},{text:`With faith let us send up praises * to the wise hierarch Archippus * and the honorable Apphia, * lauding Philemon, and Onesimus, * the sacred preachers of God, * the honorable teachers, * who by their preaching uprooted the delusion of polytheism, * planting the knowledge of the Truth for all ** who ever honor them with piety.`,tier:2,src:{file:`11-22.pdf`,locus:`p1 LIC 6`},label:`plain`,saint:`Philemon and those with him`,spec_mel:`When from the Tree ...`}],lic_closer:{text:`Let heaven rejoice today from on high, and let the clouds drop down gladness at the exceedingly glorious and mighty works of our God! For, lo! the portal which faceth east, who was born from a barren woman according to God's promise, and who became a dwelling-place sanctified for God, is brought forth as an unblemished offering. Let David rejoice, striking his harp! For he said: “The virgins that follow after her shall be brought before the King; those near her shall be brought unto the tabernacle of God, into His sanctuary, to be reared in the dwelling-place of Him Who, for the salvation of our souls, was incorruptibly begotten of the Father before time.”`,tier:1,src:{file:`11-22.pdf`,locus:`p1-p2 LIC Glory/Both now, Doxasticon of the feast`},type:`of_the_feast`,saint:`feast`,sourceLabel:`Glory ..., Both now ..., Doxasticon of the feast, in Tone I`,tone:1},aposticha_rubric:{text:`On the Aposticha, these Stichera, in Tone II:`,tier:1,src:{file:`11-22.pdf`,locus:`p2 Aposticha rubric`}},aposticha:[{text:`Having lit their candles today, * the assembly of virgins, * chanting hymns, * doth splendidly precede her who alone ** is all-immaculate.`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Aposticha 1`},label:`plain`,tone:2,saint:`feast`,spec_mel:`O house of Ephratha ...`},{text:`The virgins that follow after her shall be brought unto the King; * those near her shall be brought unto Thee.`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`O prophet, receive her * who alone is all-immaculate: * the noetic mountain, * the divine table, ** the bridge and the jar.`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Aposticha 2`},label:`plain`,saint:`feast`,spec_mel:`O house of Ephratha ...`},{text:`They shall be brought with gladness and rejoicing, * they shall be brought into the temple of the King.`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`Opening the portals of the sanctuary, * O prophet Zachariah, * truly accept thou * the Mother of God, ** the only Ever-virgin.`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Aposticha 3`},label:`plain`,saint:`feast`,spec_mel:`O house of Ephratha ...`}],aposticha_closer:{text:`Today the all-immaculate Virgin is brought to the temple, to the habitation of God, the King of all, the Nourisher of our whole life. Today the most pure and holy one, is led to the Holy of holies like a heifer three years of age. Let us cry out unto her like the angel: “Rejoice, thou who alone art blessed among women!”`,tier:1,src:{file:`11-22.pdf`,locus:`p2 Aposticha Glory/Both now`},type:`of_the_feast`,saint:`feast`,sourceLabel:`Glory ..., Both now ..., in Tone II`,tone:2},troparia:[{text:`O holy apostles * entreat the Merciful God * that He grant remission of sins ** unto our souls.`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Troparion of the holy apostles`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Troparion of the holy apostles, in Tone III`,tone:3},{text:`Today is the prelude of God's good will * and the proclamation of the salvation of mankind. * The Virgin hath manifestly appeared in the temple of God, proclaiming Christ unto all. * To her let us cry aloud: ** Rejoice, O thou fulfillment of the Creator's dispensation!`,tier:2,src:{file:`11-22.pdf`,locus:`p2 Troparion of the feast`},label:[`glory`,`both_now`,`of_the_feast`],saint:`feast`,sourceLabel:`Glory ..., Both now ..., Troparion of the feast, in Tone IV`,tone:4}]},matins:{order:[`troparia`,`troparia_closing_rubric`,`sessional_1`,`sessional_2`,`canon_rubric`,`canons`,`kontakia_ode3`,`sessional_ode3`,`kontakia_ode6`,`exapostilarion`,`exapostilarion_closer_rubric`,`aposticha_rubric`,`aposticha`,`aposticha_closer`],troparia:[{text:`Today is the prelude of God's good will * and the proclamation of the salvation of mankind. * The Virgin hath manifestly appeared in the temple of God, proclaiming Christ unto all. * To her let us cry aloud: ** Rejoice, O thou fulfillment of the Creator's dispensation!`,tier:2,src:{file:`11-22.pdf`,locus:`p3 Troparion of the feast at God is the Lord`},label:`of_the_feast`,saint:`feast`,repeat:2,sourceLabel:`On “God is the Lord ...,” the Troparion of the feast, in Tone IV`,tone:4},{text:`O holy apostles * entreat the Merciful God * that He grant remission of sins ** unto our souls.`,tier:2,src:{file:`11-22.pdf`,locus:`p3 Troparion of the holy apostles at God is the Lord`},label:`glory`,saint:`Philemon and those with him`,sourceLabel:`Glory ..., that of the holy apostles, in Tone III`,tone:3}],troparia_closing_rubric:{text:`Both now ..., that of the feast.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Both now, that of the feast`}},sessional_1:[{text:`Praise ye, O virgins! Keep festival, ye mothers! Give glory, ye people! Ye priests, bless ye the most pure Mother of God! For she, who before was a little child in the flesh, is brought to the Temple as the most holy temple of God. Wherefore, celebrating a spiritual feast, we hymn her as an intercessor for the human race.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Sessional 1`},label:`plain`,saint:`feast`,sourceLabel:`After the first chanting of the Psalter, the Sessional Hymn, in Tone IV`,spec_mel:`When the stone had been sealed ...`,tone:4},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Sessional 1 repeat device`},label:[`glory`,`both_now`]}],sessional_2:[{text:`O David, go thou before us into the Temple of God, and, rejoicing, receive thou our Queen, and cry out unto her: Enter thou, O Sovereign Lady! Enter thou into the Temple of the King! Her glory is understood allegorically, for from her doth Christ the Light desire to pour Himself forth upon all!`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Sessional 2`},label:`plain`,saint:`feast`,sourceLabel:`After the second chanting of the Psalter, the Sessional Hymn, in Tone IV`,spec_mel:`Go thou quickly before ...`,tone:4},{text:`Glory ..., Both now ..., the foregoing is repeated.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Sessional 2 repeat device`},label:[`glory`,`both_now`]}],canon_rubric:{text:`Canon of the feast, with 8 Troparia, including the Irmos; and that of the holy apostles, with 4 Troparia.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Canon rubric`}},canons:[{title:`Canon of the feast, the acrostic whereof is “O Lady, grant thou grace and discourse”, the composition of George, in Tone IV:`,composer:`George`,tone:4,odes:{1:{irmos:{text:`I shall open my mouth, * and be filled with the Spirit, * and utter discourse to the Queen and Mother; * and be seen radiantly keeping festival, * joyfully praising her entry.`,tier:2,src:{file:`11-22.pdf`,locus:`p3 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O most pure one, we know thee to be a treasury of wisdom and an ever-flowing fountain of grace; and we pray thee rain down upon us knowledge, that we may praise thee forever.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Ode 1 troparion 1`},label:`plain`},{text:`Being a temple and palace more exalted than the heavens, O most pure one, thou wast set apart in the Temple of God to be prepared as a divine dwelling-place for His advent.`,tier:1,src:{file:`11-22.pdf`,locus:`p3 Ode 1 troparion 2`},label:`plain`},{text:`Shining with the Light of grace, the Theotokos hath illumined all and assembled us to adorn her most splendid festival. Come ye, let us draw nigh to her!`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 1 troparion 3`},label:`plain`},{text:`The glorious portal which surpasseth human thought, having opened the doors of the Temple of God, doth now command us who have assembled to delight in her divine wonders.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 1 troparion 4`},label:`plain`}]},3:{irmos:{text:`O Theotokos, thou living and plentiful fount, * establish in spiritual fellowship those who sing hymns of praise * of thine honored entry: * grant them crowns of glory.`,tier:2,src:{file:`11-22.pdf`,locus:`p4 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Receiving the pure and undefiled one, who is more splendid than all creation, the animate bridal chamber of God, the beautiful Temple and chamber doth appear today like a bride adorned for her wedding.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 3 troparion 1`},label:`plain`},{text:`David, preceding the chorus, doth leap and dance with us, declaring thee, O all-pure one, to be the queen all-adorned, standing in the Temple before our King and God, O most pure one.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 3 troparion 2`},label:`plain`},{text:`From her, whom transgressions issued forth among the race of mankind, hath her correction and incorruption blossomed forth, the Theotokos, who is led today into the house of God.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 3 troparion 3`},label:`plain`},{text:`The angelic armies and the multitudes of all mankind leap for joy, and they advance as lamp-bearers before thy countenance, proclaiming thy majesty in the house of God.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 3 troparion 4`},label:`plain`}]},4:{irmos:{text:`Perceiving the profound counsel of God, * that the incarnation of Thee the Most High, * will be from a Virgin, * the prophet Habbakuk cried aloud: * Glory to Thy power, O Lord!`,tier:2,src:{file:`11-22.pdf`,locus:`p5 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The Temple of God, receiving today the portal through whom none may pass, hath ceased to perform any service of the Law, crying: Truly truth hath appeared to those who are on earth!`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 1`},label:`plain`},{text:`The mountain overshadowed, which Habbakuk beheld of old, prefigured her who hath made her abode in the inaccessible chambers of the Temple, flourishing with virtues, for she doth cover the ends of the earth therewith.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 2`},label:`plain`},{text:`All the earth hath seen most glorious things, things strange and marvelous, for the Virgin, receiving food from an angel, doth receive tokens of God's dispensation.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 3`},label:`plain`},{text:`Revealed as the temple and palace and animate heaven, O divine bride of the King, thou art brought today to the Temple of the Law to be kept for Him, O most pure one.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 4`},label:`plain`}]},5:{irmos:{text:`All creation stands in awe of thy divine glory; * for thou, O Virgin who hast not known wedlock, * didst enter into the temple of the Lord; * thyself being a most pure temple, * bestowing peace, upon all who hymn thee.`,tier:2,src:{file:`11-22.pdf`,locus:`p6 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`The most pure Virgin, the glorious sanctity and sacred offering which is brought today to the Temple of God, is preserved as a habitation for our one God, the King of all, as He Himself knoweth.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 5 troparion 1`},label:`plain`},{text:`Zachariah, having of old beheld the beauty of thy soul, cried out in faith: Thou art the deliverance, thou art the joy of all, thou art our restoration, through whom the Uncontainable One shall appear unto me contained.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 5 troparion 2`},label:`plain`},{text:`O, thy wonders which pass understanding, O all-pure one! Strange is thy birthgiving; strange is the manner of thy maturation; strange also, most glorious and unutterable by mortals, are all thy wonders, O Bride of God.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 5 troparion 3`},label:`plain`},{text:`As a most radiant lamp, O Bride of God, hast thou shone forth today in the house of the Lord, illumining us with the precious gifts of thy wonders, O pure and all-hymned Theotokos.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 5 troparion 4`},label:`plain`}]},6:{irmos:{text:`Celebrating the divine and solemn feast * of the Mother of God * O ye divinely wise, * let us come, clapping our hands, * and glorify God who was born of her.`,tier:2,src:{file:`11-22.pdf`,locus:`p7 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou Who hast upheld all things by Thy word hast hearkened to the prayer of the righteous ones. Wherefore, Thou hast loosed the infirmity of the barren woman, in that Thou art compassionate, and given them her who is the cause of joy.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 6 troparion 1`},label:`plain`},{text:`Wishing to make His salvation known to the Gentiles, the Lord hath now taken from among mankind her who hath not known wedlock, as a sign of reconciliation and renewal.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 6 troparion 2`},label:`plain`},{text:`As a house of grace, wherein treasures of the ineffable dispensation of God are laid up, O all-pure one, thou didst share in unfading delight in the Temple.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 6 troparion 3`},label:`plain`},{text:`Receiving thee as a royal diadem, O Bride of God, the Temple hath been rendered splendid and been elevated to better things, beholding in thee the fulfillment of the prophecies.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 6 troparion 4`},label:`plain`}]},7:{irmos:{text:`Refusing to worship created things * in place of the Creator, * the divinely wise youths bravely trampled down the threatening fire * and rejoicing they sang aloud: * O supremely hymned Lord and God of our Fathers, Blessed art Thou.`,tier:2,src:{file:`11-22.pdf`,locus:`p8 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Lo, today a joyous spring hath dawned upon the ends of the earth, enlightening our souls, thoughts and minds with grace: the festival of the Theotokos. Let us mystically make festival this day!`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 7 troparion 1`},label:`plain`},{text:`Let all things - heaven and earth, the ranks of angels and the multitudes of mankind - bear gifts today unto the Queen and Mother of God; and let them cry aloud: Our joy and deliverance is brought into the Temple!`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 7 troparion 2`},label:`plain`},{text:`The Scriptures have come to pass, the Law hath faded like a shadow, and rays of grace have shone forth upon thee who hast entered into the Temple of God, O pure Virgin Mother wherein thou art blessed.`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 7 troparion 3`},label:`plain`},{text:`Heaven and earth and the netherworld are subject to thine Offspring as Creator and God, O all-pure one, and every nation of mortals doth confess that the Lord and Savior of our souls hath appeared.`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 7 troparion 4`},label:`plain`}]},8:{irmos:{text:`Hearken, O pure Virgin maiden, * that Gabriel may tell thee the true counsel of the Most High of old. * Make ready to receive the Godhead; * for through thee the Infinite One hath come to dwell among mankind. * Wherefore, rejoicing, I cry aloud: * Bless the Lord, all ye works of the Lord!`,tier:2,src:{file:`11-22.pdf`,locus:`p9 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Anna, once, leading the most pure temple to the house of God, faithfully said unto the priest, crying aloud: Now accept thou this child, given me by God; lead her into the Temple of the Creator; and, rejoicing, chant unto Him: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 8 troparion 1`},label:`plain`},{text:`And Zachariah then, beholding them in the Spirit, said unto Anna: Thou dost bring hither the true Mother of Life, whom the prophets of God have clearly foretold as the Theotokos! How, therefore, can the Temple hold her? Wherefore, marveling, I cry out: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 8 troparion 2`},label:`plain`},{text:`The handmaid of God have I been, answered Anna unto him, and I call upon Him with faith and prayer to accept the fruit of my birth-pangs, that, having received this child, I might bring her that was born unto Him that bestowed her. Wherefore, I cry aloud: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 8 troparion 3`},label:`plain`},{text:`Truly this is a matter of the Law, the priest said to her, and strange doth this thing seem unto me, beholding her that doth most gloriously surpass the holy ones in grace led into the house of God. Wherefore, rejoicing, I cry out: Bless the Lord, all ye works of the Lord!`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 8 troparion 4`},label:`plain`}]},9:{irmos:{text:`In nowise may the hand of the defiled * touch the animate ark of God; * and let the lips of the faithful * never-silently cry out with joy to the Theotokos, * chanting the words of the angel: * Rejoice, O thou who art full of grace! * The Lord is with thee!`,tier:2,src:{file:`11-22.pdf`,locus:`p10 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`O pure Theotokos, as thou hast the most radiant beauty of purity of soul and art full of the grace of God from heaven, with the ever-existent light thou dost ever enlighten those who cry out with joy: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 9 troparion 1`},label:`plain`},{text:`Thy wonder doth surpass the power of words, O pure Theotokos, for in thee I perceive a body impervious to the movement of sin. Wherefore, thankfully I cry out to thee: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 9 troparion 2`},label:`plain`},{text:`Most gloriously did the Law prefigure thee, O pure one, as the tabernacle, the divine jar, the awe-some ark, the veil, the staff, the inviolable temple and portal of God. Wherefore, all these things teach us to cry to thee: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 9 troparion 3`},label:`plain`},{text:`In hymnody David cried out to thee prophetically, calling thee the daughter of the King in the comeliness of thy virtues, beholding thee standing, elaborately adorned, at the right hand of God. Wherefore, in prophecy he cried out: Truly thou art more highly exalted than all, O pure Virgin!`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Ode 9 troparion 4`},label:`plain`}]}}},{title:`Canon of the holy apostle, the acrostic whereof is “I glorify thee who lovest Christ, O Philemon”, the composition of Joseph, in Tone II:`,composer:`Joseph`,tone:2,odes:{1:{irmos:{text:`Come, O ye people, * let us sing a song to Christ our God, * Who divided the sea, * and made a way for the nation * which He had brought up out of the bondage of Egypt; * for He hath been glorified.`,tier:2,src:{file:`11-22.pdf`,locus:`p4 Ode 1 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Joining chorus joyously in the mansions of heaven, O accomplisher of sacred things, grant grace unto me who hymn thy holy memory in a godly manner, for thou hast been glorified.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 1 troparion 1`},label:`plain`},{text:`Giving drink to men's hearts with the streams of thy words, O blessed and right wondrous apostle Philemon, thou hast prepared them to accomplish divine understandings with faith.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 1 troparion 2`},label:`plain`},{text:`Having delivered men's souls from the gloom of the madness of idolatry, O wise apostle, thou hast illumined them with the splendors of the Spirit, doing the sanctified works of the sacred Gospel.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 1 troparion 3`},label:`plain`},{text:`O pure one, of old the divine assembly of the prophets truly described thee from afar in many and varied images, as the only one who gave birth to the Master.`,tier:1,src:{file:`11-22.pdf`,locus:`p4 Ode 1 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},3:{irmos:{text:`O Lord, who didst slay sin upon the Tree, * firmly establish us in Thee, * and in the hearts of us who hymn Thee * plant the fear of Thee.`,tier:2,src:{file:`11-22.pdf`,locus:`p5 Ode 3 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Preaching the sufferings and resurrection of Christ, O right glorious Philemon, thou dost raise us up from the tomb of unbelief and mortality.`,tier:1,src:{file:`11-22.pdf`,locus:`p5 Ode 3 troparion 1`},label:`plain`},{text:`With sacred hymnody let us praise the godly Onesimus and Philemon, Apphia and Archippus, the stars who illumine the ends of the earth.`,tier:1,src:{file:`11-22.pdf`,locus:`p5 Ode 3 troparion 2`},label:`plain`},{text:`Having purified the eyes of your mind, ye received divine vision and have raised erring hearts up to knowledge, O most sacred ones.`,tier:1,src:{file:`11-22.pdf`,locus:`p5 Ode 3 troparion 3`},label:`plain`},{text:`Having been shown to be pure and supremely incorrupt, O Virgin, thou didst receive within thy womb God the Word Who hath cleansed nature, which had been defiled by our fall into sin.`,tier:1,src:{file:`11-22.pdf`,locus:`p5 Ode 3 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},4:{irmos:{text:`I hymn Thee, O Lord, for I have heard report of Thee, * and I was afraid; * for Thou comest to me, seeking me who am lost. * Wherefore, I glorify Thy great condescension towards me, * O greatly merciful One.`,tier:2,src:{file:`11-22.pdf`,locus:`p6 Ode 4 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`With the Cross as mast and sail, thou didst pass over the cruel abyss of the temptations of life without foundering, O blessed one, directing many of those at sea to the harbor of salvation through divine grace.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 1`},label:`plain`},{text:`The godly city of Colossae manifestly setteth forth radiant luminaries: the sacred Archippus, Philemon and Apphia, and the glorious Onesimus, who enlighten the ends of the world.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 2`},label:`plain`},{text:`A divine river arose in thy heart, O godly eloquent one, stopping the rivers and torrents of ungodliness; and through grace giving drink to souls parched by the burning heat of ignorance, O glorious one.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 troparion 3`},label:`plain`},{text:`I hymn thee, O truly all-hymned one, who supra-naturally gave birth to the all-hymned Word of God, and I pray: In that thou art good, O Bride of God, heal thou the infirmities of my lowly soul.`,tier:1,src:{file:`11-22.pdf`,locus:`p6 Ode 4 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},5:{irmos:{text:`O Lord, Bestower of light and Creator of the ages: * guide us in the light of Thy commandments, * for we know none other God than Thee.`,tier:2,src:{file:`11-22.pdf`,locus:`p7 Ode 5 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Seeing those ailing with the wounds of evil deeds, O glorious Philemon, by thine active discourse thou didst heal those cruelly sick with the madness of idolatry.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 5 troparion 1`},label:`plain`},{text:`As a sure guide, O Philemon, thou didst point out the paths of salvation to those grievously lost, and wondrously led them to love Christ, the only Way.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 5 troparion 2`},label:`plain`},{text:`Today the honored Church of Christ in Colossae doth sing the splendid festival of the godly Archippus, honoring also the divinely eloquent Philemon.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 5 troparion 3`},label:`plain`},{text:`O Lady, save us who are tempest-tossed by the cruel billows of temptations, the audacious assaults of barbarians and the attacks of the cruel demons.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 5 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},6:{irmos:{text:`Whirled about in the abyss of sin, * I appeal to the unfathomable abyss of Thy compassion: * Raise me up from corruption, O God.`,tier:2,src:{file:`11-22.pdf`,locus:`p7 Ode 6 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Thou hast been revealed to be a heaven proclaiming to all the saving glory of Him Who glorified thee and numbered thee among His seventy apostles, O spiritually rich martyr.`,tier:1,src:{file:`11-22.pdf`,locus:`p7 Ode 6 troparion 1`},label:`plain`},{text:`Having become a stranger to thy native land, with thy strange discourse thou didst pursue those who had become estranged from God, O hierarch Philemon, and showing them to be inhabitants of Sion.`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 6 troparion 2`},label:`plain`},{text:`Shining with sacred virtues, and splendidly pleasing God, thou didst hasten to the heavens, where thou dost rejoice with the angels, O Apphia.`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 6 troparion 3`},label:`plain`},{text:`The Word became incarnate within thy womb and became known as a man in His compassion, that He might deify mankind, O all-immaculate maiden.`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ode 6 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},7:{irmos:{text:`When the golden image was worshipped on the plain of Dura, * Thy three children spurned the impious command, * and, cast into the midst of the flame, * they were bedewed, and sang: * O God of our fathers, blessed art Thou!`,tier:2,src:{file:`11-22.pdf`,locus:`p9 Ode 7 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Beautiful were thy precious feet, O Philemon, which meekly trod the paths of the Gospel, announcing sacred peace to all those who do battle, and hindering the assaults of the demons.`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 7 troparion 1`},label:`plain`},{text:`The profound darkness of the Gazanenes was dispelled by the light of thy words, in that thou art a most sacred performer of the sacraments, O apostle, and among them thou wast most excellent, shepherding them all and teaching them to chant: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 7 troparion 2`},label:`plain`},{text:`The city of Gaza first shared in thy god-pleasing labors, being the first bishop there, O salvific hierarch Philemon, and as a sacred herald thou didst instruct them to cry aloud: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 7 troparion 3`},label:`plain`},{text:`As a lover of Christ, Who loved mortals in His compassion, O Philemon, thou didst transform hate-filled enemies into loving friends through love, whereby they chanted unto God: O God of our fathers, Blessed art Thou!`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 7 troparion 4`},label:`plain`},{text:`O Virgin, thou art the strength of the lowly, the radiant lamp, the divine table, the impassable gate, the throne and palace of God, the staff of Aaron and the golden jar bearing Christ, the Manna of life.`,tier:1,src:{file:`11-22.pdf`,locus:`p9 Ode 7 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},8:{irmos:{text:`God Who descended into the fiery furnace * with the Hebrew children, * and transformed the flame into dew, * do ye works hymn, * and supremely exalt as Lord throughout all ages.`,tier:2,src:{file:`11-22.pdf`,locus:`p10 Ode 8 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Bearing the word in thy heart like a splendidly lit lamp, O glorious one, thou didst raise up to the day of the knowledge of God those who before were like lamps extinguished and lay in the deep-darkness of ignorance.`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 8 troparion 1`},label:`plain`},{text:`Thy sacred departure unto God was rendered magnificent by the sacred presence of the apostles and the incorporeal intelligences, whose life thou didst emulate on earth, as an initiate of the sacred mysteries, O divinely eloquent Philemon.`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 8 troparion 2`},label:`plain`},{text:`Manifestly exuding the sweet-smelling myrrh of sacred miracles, O blessed and wise Philemon, thou didst perfume the minds and thoughts of the pious, dispelling the fetid passions of those who supremely exalt Christ.`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 8 troparion 3`},label:`plain`},{text:`Like radiant stars ever shining in the firmament of the Church, the wondrous Archippus, Apphia, Philemon and Onesimus illumine our souls.`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 8 troparion 4`},label:`plain`},{text:`Thy womb hath truly been revealed to us as a new garden of paradise, O pure Theotokos, producing the Tree of life, and it hath led back into paradise those who died through the fruit of the tree, giving them life.`,tier:1,src:{file:`11-22.pdf`,locus:`p10 Ode 8 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]},9:{irmos:{text:`God the Word, God of God, * Who by ineffable wisdom came to create Adam anew * after his grievous fall to corruption through eating * and Who took flesh beyond all telling from the Holy Virgin for our sake, * Him we faithful with one accord magnify in song.`,tier:2,src:{file:`11-22.pdf`,locus:`p11 Ode 9 irmos`},sourceLabel:`Irmos`,label_inline:!0},items:[{text:`Deified by divine communion, shining 'with ineffable light and ever filled with spiritual joy, O Philemon, thou dwellest in the heavens with the most sacred choir of the sacred apostles as is meet.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Ode 9 troparion 1`},label:`plain`},{text:`Wondrous is thy character, comely and beautiful thy life, and most glorious was thy repose, O blessed apostle, as the radiant day whereon, forsaking that which is on earth, thou didst ascend in gladness to the circles of heaven.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Ode 9 troparion 2`},label:`plain`},{text:`Today the whole Church of Christ is glad, spiritually ordaining festive joy at thy memorial, for thou hast preserved it unshaken by thy god-pleasing supplications to God the Savior, O most sacred Philemon.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Ode 9 troparion 3`},label:`plain`},{text:`The shrine of thy relics poureth forth drops of healing upon those who approach it reverently, O blessed apostle Philemon, for it banishes illnesses and hallows the souls of all who ever celebrate thy divine memory.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Ode 9 troparion 4`},label:`plain`},{text:`O all-immaculate one, thou bearest Him Who holdeth all things, and who didst nourish the Nurturer, in nowise experiencing the usual pangs of birthgiving. Thy wonder surpasseth understanding, and fills with awe both angels and mortals, who know thee to be the only Virgin Mother of God.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Ode 9 Theotokion`},label:`theotokion`,sourceLabel:`Theotokion`,label_inline:!0}]}}}],kontakia_ode3:[{text:`Let us praise the apostles of Christ, * the glorious Philemon, the sacred Archippus, Onesimus, Mark and Apollos, * and with them the all-wise Apphia * as most radiant stars illumining the ends of the earth; ** and let us cry out: Pray ye unceasingly on behalf of us all!`,tier:2,src:{file:`11-22.pdf`,locus:`p5 Kontakion of the holy apostles (after Ode III)`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Kontakion of the holy apostles, in Tone II`,spec_mel:`Seeking the highest ...`,tone:2}],sessional_ode3:[{text:`Cultivating stony hearts with the plough of the word, O sacred husbandman, thou didst prepare them for divine knowledge, and, casting down the temples of the idols, O blessed one, thou didst erect churches to the glory of thy Creator. Wherefore, assembling, we who are illumined in a most sacred manner glorify thy holy memory, O Philemon, and cry out to thee together: Entreat Christ God, that He grant re-mission of sins unto those who honor thy holy memory with love.`,tier:1,src:{file:`11-22.pdf`,locus:`p5 Ode III sessional (apostle)`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Sessional Hymn of the holy apostle, in Tone VIII`,spec_mel:`Of the Wisdom ...`,tone:8},{text:`Let David the psalmist rejoice, and let Joachim and Anna join chorus, for the radiant Mary, the divine lamp, issued forth from them like a holy fruit, and she rejoiceth, entering the temple, and beholding her, the son of Barachiah blessed her, and, rejoicing, cried aloud: “Rejoice, O wonder of the universe!”`,tier:1,src:{file:`11-22.pdf`,locus:`p5 Ode III sessional (feast)`},tone:8,label:[`glory`,`both_now`,`of_the_feast`],saint:`feast`,sourceLabel:`Glory ..., Both now ..., Sessional Hymn of the feast, in the same tone`,spec_mel:`That which was mystically commanded ...`}],kontakia_ode6:[{text:`The most pure temple of the Savior, * the precious bridal chamber and Virgin, * the sacred treasury of the glory of God, * hath been brought into the house of the Lord this day, * bringing with her the grace that is in the divine Spirit. * To her do the angels of God chant the hymn: ** She is the heavenly tabernacle!`,tier:2,src:{file:`11-22.pdf`,locus:`p8 Kontakion of the feast (after Ode VI)`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Kontakion of the feast, in Tone IV`,spec_mel:`Having been lifted up ...`,tone:4},{text:`Beholding the grace of the ineffable and divine mysteries of God made plainly manifest in and filling the Virgin, I rejoice; yet I know not how to understand this strange and ineffable image. How hath the pure one alone been shown to be above all creation, visible and immaterial? Wherefore, wishing to praise her, I am greatly in awe in mind and word; yet, bold, I proclaim and magnify her, saying: She is the heavenly tabernacle!`,tier:1,src:{file:`11-22.pdf`,locus:`p8 Ikos of the feast`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Ikos`,label_inline:!0}],exapostilarion:{text:`With faith let us praise the divine maiden Mary, whom the company of the prophets of old proclaimed to be the jar, the staff, the tablet and the unquarried mountain; for she is led today in to the Holy of holies to be raised for the Lord.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Exapostilarion of the feast`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Exapostilarion of the feast`,spec_mel:`Hearken, ye women ...`},exapostilarion_closer_rubric:{text:`Glory ..., Both now ..., The foregoing is repeated.`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Exapostilarion repeat device`}},aposticha_rubric:{text:`On the Aposticha, these Stichera, in Tone VI:`,tier:1,src:{file:`11-22.pdf`,locus:`p11 Matins Aposticha rubric`}},aposticha:[{text:`Join chorus together, O ye virgins! * Leap up, ye maidens! * And, bearing your candles, * hymn ye with splendor * the only pure and most holy Theotokos! ** Sing forth, ye heavens!`,tier:2,src:{file:`11-22.pdf`,locus:`p11 Matins Aposticha 1`},label:`plain`,tone:6,saint:`feast`,spec_mel:`On the third day ...`},{text:`The virgins that follow after her shall be brought unto the King, * those near her shall be brought unto Thee.`,tier:2,src:{file:`11-22.pdf`,locus:`p12 Matins Aposticha verse 1`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`By the hand of the angel, O Virgin, * did thy Son, the Creator of all, * nourish thee with food, * O pure Lady, * revealing thy magnificence to the world ** as far greater than that of the Holy of holies.`,tier:2,src:{file:`11-22.pdf`,locus:`p12 Matins Aposticha 2`},label:`plain`,saint:`feast`,spec_mel:`On the third day ...`},{text:`They shall be brought with gladness and rejoicing, * they shall be brought into the temple of the King.`,tier:2,src:{file:`11-22.pdf`,locus:`p12 Matins Aposticha verse 2`},label:`refrain`,sourceLabel:`Verse`,label_inline:!0},{text:`O Virgin Bride of God, * holier than all the saints, * who hast given birth to the Master of all, * Who is One of the Trinity, * beseech Him, that He deliver from misfortunes ** all who hymn thee.`,tier:2,src:{file:`11-22.pdf`,locus:`p12 Matins Aposticha 3`},label:`plain`,saint:`feast`,spec_mel:`On the third day ...`}],aposticha_closer:{text:`Today the Theotokos, the temple which held God, is escorted into the temple of the Lord; and Zachariah receiveth her. Today the Holy of holies rejoiceth and the choir of angels mystically keepeth festival. And we, celebrating with them today, cry aloud with Gabriel: Rejoice, O thou who art full of grace! The Lord, Who hath great mercy, is with thee!`,tier:1,src:{file:`11-22.pdf`,locus:`p12 Matins Aposticha Glory/Both now`},type:`of_the_feast`,saint:`feast`,sourceLabel:`Glory ..., Both now ..., in Tone IV`,tone:4}},liturgy:{order:[`beatitudes_rubric`,`beatitudes`,`troparia`,`kontakia`,`prokeimena`,`epistle`,`alleluias`,`gospel`,`megalynarion_rubric`,`megalynarion_refrain`,`megalynarion`,`communion_verses`],beatitudes_rubric:{text:`On the Beatitudes, 6 Troparia from ODE I of the canon of the feast.`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitudes rubric`}},beatitudes:[{text:`O most pure one, we know thee to be a treasury of wisdom and an ever-flowing fountain of grace; and we pray thee rain down upon us knowledge, that we may praise thee forever.`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitude 1`},label:`plain`,saint:`feast`},{text:`Being a temple and palace more exalted than the heavens, O most pure one, thou wast set apart in the Temple of God to be prepared as a divine dwelling-place for His advent.`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitude 2`},label:`plain`,saint:`feast`},{text:`Shining with the Light of grace, the Theotokos hath illumined all and assembled us to adorn her most splendid festival. Come ye, let us draw nigh to her!`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitude 3`},label:`plain`,saint:`feast`},{text:`The glorious portal which surpasseth human thought, having opened the doors of the Temple of God, doth now command us who have assembled to delight in her divine wonders.`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitude 4`},label:`plain`,saint:`feast`},{text:`Let us hasten today, honoring the Theotokos with hymns, and let us celebrate a spiritual feast; for she is offered as a gift to God in the temple.`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitude 5`},label:`plain`,saint:`feast`},{text:`With songs let us hymn the glorious arrival of the Theotokos; for today, as the prophets foretold, she is borne as a gift of great price into the temple, though she is herself the temple of God.`,tier:1,src:{file:`11-22.pdf`,locus:`p13 Beatitude 6`},label:`plain`,saint:`feast`}],troparia:[{text:`Today is the prelude of God's good will * and the proclamation of the salvation of mankind. * The Virgin hath manifestly appeared in the temple of God, proclaiming Christ unto all. * To her let us cry aloud: ** Rejoice, O thou fulfillment of the Creator's dispensation!`,tier:2,src:{file:`11-22.pdf`,locus:`p13 Troparion of the feast at Liturgy`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Troparion of the feast, in Tone IV`,tone:4},{text:`O holy apostles * entreat the Merciful God * that He grant remission of sins ** unto our souls.`,tier:2,src:{file:`11-22.pdf`,locus:`p13 Troparion of the holy apostles at Liturgy`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Troparion of the holy apostles, in Tone III`,tone:3}],kontakia:[{text:`Let us praise the apostles of Christ, * the glorious Philemon, the sacred Archippus, Onesimus, Mark and Apollos, * and with them the all-wise Apphia * as most radiant stars illumining the ends of the earth; ** and let us cry out: Pray ye unceasingly on behalf of us all!`,tier:2,src:{file:`11-22.pdf`,locus:`p13 Kontakion of the holy apostles at Liturgy`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Kontakion of the holy apostles, in Tone II`,tone:2},{text:`The most pure temple of the Savior, * the precious bridal chamber and Virgin, * the sacred treasury of the glory of God, * hath been brought into the house of the Lord this day, * bringing with her the grace that is in the divine Spirit. * To her do the angels of God chant the hymn: ** She is the heavenly tabernacle!`,tier:2,src:{file:`11-22.pdf`,locus:`p13 Kontakion of the feast at Liturgy`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Kontakion of the feast, in Tone IV`,tone:4}],prokeimena:[{text:`My soul doth magnify the Lord, * and my spirit hath rejoiced in God my Savior.`,tier:2,src:{file:`11-22.pdf`,locus:`p14 Prokeimenon of the feast`},tone:3,label:`of_the_feast`,saint:`feast`,sourceLabel:`Prokeimenon, in Tone III: the Song of the Theotokos`,label_inline:!0},{text:`Their sound hath gone forth into all the earth, * and their words unto the ends of the world.`,tier:2,src:{file:`11-22.pdf`,locus:`p14 Prokeimenon of the apostles`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Prokeimenon, in Tone VIII`,label_inline:!0,tone:8},{text:`The heavens declare the glory of God, and the firmament proclaimeth the work of His hands.`,tier:1,src:{file:`11-22.pdf`,locus:`p14 Prokeimenon verse`},label:`refrain`,saint:`Philemon and those with him`,sourceLabel:`Verse`,label_inline:!0}],epistle:{heading:`EPISTLE TO PHILEMON,`,src:{file:`11-22.pdf`,locus:`p14 Epistle`},citation_verbatim:`FROM AFTER §302(PHILM. 1-24)`,citation:{book:`Philemon`,chapter:1,verses:`1-24`,pericope_number:302},citation_basis:`printed`},alleluias:[{text:`Hearken, O daughter, and see, and incline thine ear.`,tier:1,src:{file:`11-22.pdf`,locus:`p15 Alleluia of the feast`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Alleluia, in Tone VIII`,label_inline:!0,tone:8},{text:`The heavens shall confess Thy wonders, O Lord, and Thy truth in the congregation of saints.`,tier:1,src:{file:`11-22.pdf`,locus:`p15 Alleluia of the apostles`},tone:1,label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Alleluia, in Tone I: Verse`,label_inline:!0},{text:`God Who is glorified in the council of the saints.`,tier:1,src:{file:`11-22.pdf`,locus:`p15 Alleluia verse`},label:`refrain`,saint:`Philemon and those with him`,sourceLabel:`Verse`,label_inline:!0}],gospel:{heading:`GOSPEL ACCORDING TO LUKE;`,src:{file:`11-22.pdf`,locus:`p15 Gospel`},citation_verbatim:`§ 50(LK. 10: 1-15)`,citation:{book:`Luke`,chapter:10,verses:`1-15`,pericope_number:50},citation_basis:`printed`},megalynarion_rubric:{text:`Instead of “It is truly meet...”`,tier:1,src:{file:`11-22.pdf`,locus:`p15 Instead of It is truly meet`}},megalynarion_refrain:{text:`The angels, beholding the entry of the most pure one, were amazed to see the Virgin enter into the Holy of holies.`,tier:1,src:{file:`11-22.pdf`,locus:`p15 Refrain before the festal Irmos`},label:`refrain`,sourceLabel:`Refrain`,label_inline:!0},megalynarion:{text:`In nowise may the hand of the defiled * touch the animate ark of God; * and let the lips of the faithful * never-silently cry out with joy to the Theotokos, * chanting the words of the angel: * Rejoice, O thou who art full of grace! * The Lord is with thee!`,tier:2,src:{file:`11-22.pdf`,locus:`p15 Irmos of Ode IX of the feast, at Liturgy`},sourceLabel:`Irmos`,label_inline:!0},communion_verses:[{text:`I will take the cup of salvation, and I will call upon the name of the Lord.`,tier:1,src:{file:`11-22.pdf`,locus:`p15 Communion Verse for the feast`},label:`of_the_feast`,saint:`feast`,sourceLabel:`Communion Verse for the feast`,label_inline:!0},{text:`Their sound hath gone forth into all the earth, and their words unto the ends of the world.`,tier:1,src:{file:`11-22.pdf`,locus:`p16 Communion Verse for the saints`},label:`plain`,saint:`Philemon and those with him`,sourceLabel:`Communion Verse for the saints`,label_inline:!0}]}}]}};export{e as default};